import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResponse, RiskDetection, BoundingBox } from "../types";

// Configuration interface for the simulation feature
export interface SimulationConfig {
  mode: 'CLEAN' | 'RECONSTRUCT';
  humans: 'KEEP' | 'REMOVE';
  furniture: 'KEEP' | 'REPLACE';
  engine: 'AUTO' | 'GOOGLE' | 'EXTERNAL'; // Added engine choice
}

// Module-level variable to track current key index
// RANDOMIZE START: Don't always start at 0 to avoid hammering the first key
let currentKeyIndex = -1; 

// Track keys that recently failed (timestamp of failure)
const failedKeys: Record<string, number> = {}; 
const KEY_COOLDOWN_MS = 60000 * 5; // 5 Minutes cooldown for exhausted keys

// Helper to get ALL available keys from LOCAL STORAGE ONLY
export const getKeyPool = (): string[] => {
  let keys: string[] = [];

  // 1. Get from Multi-Key Storage (User's private local storage)
  const savedKeys = localStorage.getItem('user_gemini_api_keys');
  if (savedKeys) {
    try {
        const parsed = JSON.parse(savedKeys);
        if (Array.isArray(parsed)) keys = [...keys, ...parsed];
    } catch(e) {}
  }

  // 2. Fallback to Single Key Storage (Old format)
  const singleKey = localStorage.getItem('user_gemini_api_key');
  if (singleKey && !keys.includes(singleKey)) {
      keys.push(singleKey);
  }

  // 3. Fallback to Env Var (Local Dev only)
  const envKey = (typeof process !== 'undefined' && process.env) ? process.env.API_KEY : undefined;
  if (envKey && !keys.includes(envKey)) {
      keys.push(envKey);
  }

  // Clean keys (remove empty strings or too short keys)
  return keys.map(k => k.trim()).filter(k => k && k.length > 10);
};

// Reset index when user updates settings
export const resetKeyIndex = () => {
    // Pick a random start index again when keys change
    const pool = getKeyPool();
    if (pool.length > 0) {
        currentKeyIndex = Math.floor(Math.random() * pool.length);
    } else {
        currentKeyIndex = 0;
    }
    // Clear failed keys cache
    for (const k in failedKeys) delete failedKeys[k];
};

// Get current key status for UI
export const getKeyStatus = () => {
    const pool = getKeyPool();
    // Initialize index if not set
    if (currentKeyIndex === -1 && pool.length > 0) {
        currentKeyIndex = Math.floor(Math.random() * pool.length);
    }

    if (pool.length === 0) return { active: false, label: 'NO KEY' };

    // Count how many keys are actually healthy (not in failedKeys)
    const now = Date.now();
    const healthyCount = pool.filter(k => !failedKeys[k] || (now - failedKeys[k] > KEY_COOLDOWN_MS)).length;

    return { 
        active: true, 
        label: `KEY [${currentKeyIndex + 1}/${pool.length}]`, 
        count: pool.length,
        healthy: healthyCount
    };
};

// Helper function to get the AI client securely using Rotation and Health Check
const getAIClient = () => {
  const keys = getKeyPool();
  if (keys.length === 0) {
    throw new Error("Sila masukkan API Key di dalam Tetapan (Settings).");
  }

  // Initialize random start if first run
  if (currentKeyIndex === -1) {
      currentKeyIndex = Math.floor(Math.random() * keys.length);
  }

  // Ensure index is valid
  if (currentKeyIndex >= keys.length) currentKeyIndex = 0;

  // Check if current key is in cooldown
  const now = Date.now();
  let attempts = 0;

  // Try to find a healthy key by rotating until we find one not in failedKeys
  while (failedKeys[keys[currentKeyIndex]] && (now - failedKeys[keys[currentKeyIndex]] < KEY_COOLDOWN_MS)) {
      // If key is bad, move to next
      currentKeyIndex = (currentKeyIndex + 1) % keys.length;
      attempts++;

      // If we've checked all keys and they are ALL bad
      if (attempts >= keys.length) {
          console.warn("⚠️ All keys are in cooldown. Forcing usage of current key and hoping for the best.");
          break;
      }
  }

  const activeKey = keys[currentKeyIndex];
  return new GoogleGenAI({ apiKey: activeKey });
};

// Rotate to next key
const rotateKey = () => {
    const keys = getKeyPool();
    // Mark current key as failed
    const currentKey = keys[currentKeyIndex];
    if (currentKey) {
        console.warn(`❌ Marking Key ${currentKeyIndex + 1} as FAILED/EXHAUSTED.`);
        failedKeys[currentKey] = Date.now();
    }

    if (keys.length > 1) {
        const oldIndex = currentKeyIndex;
        // Find next key that isn't failed (simple loop)
        let foundNew = false;
        for(let i=1; i<keys.length; i++) {
            const nextIdx = (oldIndex + i) % keys.length;
            if (!failedKeys[keys[nextIdx]]) {
                currentKeyIndex = nextIdx;
                foundNew = true;
                break;
            }
        }

        // If all marked failed, just go to next one anyway
        if (!foundNew) {
            currentKeyIndex = (oldIndex + 1) % keys.length;
        }

        console.warn(`🔄 Rotating Key: ${oldIndex + 1} -> ${currentKeyIndex + 1}`);
        return true; // Rotation happened
    }
    return false; // No other keys to rotate to
};

// Retry utility with Key Rotation and Backoff
const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 3, delay = 2000): Promise<T> => {
    try {
        return await fn();
    } catch (error: any) {
        const msg = error.message || "";
        const isQuotaError = msg.includes("429") || msg.includes("503") || msg.includes("quota") || msg.includes("exhausted") || msg.includes("resource");

        // Check specifically for the "limit: 20" image generation error
        const isImageQuotaError = msg.includes("limit: 20") || msg.includes("generate_content_free_tier_requests");

        if (isQuotaError || isImageQuotaError) {
            console.warn(`⚠️ Quota Error on Key ${currentKeyIndex + 1}.`);

            // STRATEGY 1: Try to rotate key FIRST (If user has multiple keys)
            const rotated = rotateKey();

            if (rotated) {
                // IMPORTANT: If we rotated, do NOT wait. Try immediately.
                // The previous key is dead, but the new key is fresh.
                if (retries > 0) {
                     console.log("🚀 Switching to new key immediately...");
                     // Small 100ms buffer just to let state settle
                     await new Promise(resolve => setTimeout(resolve, 100)); 
                     // Recurse with same retry count (don't decrement retries on rotation to give new key a fair chance)
                     return retryWithBackoff(fn, retries, delay); 
                }
            }

            // STRATEGY 2: If rotation failed (only 1 key available or all exhausted), THEN wait
            if (retries > 0) {
                const timeMatch = msg.match(/retry in (\d+(\.\d+)?)s/);
                let waitMs = delay;

                if (timeMatch && timeMatch[1]) {
                    // If Google says "retry in 36s", we wait
                    waitMs = Math.ceil(parseFloat(timeMatch[1]) * 1000) + 1000; 
                    console.warn(`🛑 Google requested wait: ${waitMs/1000}s`);
                } else {
                    // Exponential backoff
                    console.warn(`🛑 Rate limit hit. Retrying in ${delay/1000}s...`);
                    waitMs = delay * 2;
                }

                await new Promise(resolve => setTimeout(resolve, waitMs));
                return retryWithBackoff(fn, retries - 1, waitMs); 
            }
        }
        throw error;
    }
};

/**
 * Smart Analysis Function with Auto-Fallback
 */
export const analyzeLandscape = async (base64Image: string, mimeType: string, mode: 'FAST' | 'DETAILED' = 'DETAILED', language: string = 'ms'): Promise<AnalysisResponse> => {
  // Config Setup
  const langMap: Record<string, string> = {
    'ms': 'Bahasa Melayu',
    'en': 'English',
    'zh': 'Chinese (Simplified)',
    'ta': 'Tamil'
  };
  const targetLang = langMap[language] || 'Bahasa Melayu';

  // PRIORITIZE FLASH MODELS FOR STABILITY
  let modelsToTry = ["gemini-2.5-flash", "gemini-1.5-flash"];

  const schemaDescription = `
  {
    "risks": [
      {
        "id": "string (unique id)",
        "category": "VECTOR | HYGIENE | SAFETY",
        "label": "string (Short Title in ${targetLang}. DO NOT use IDs like 'risk_1'. Use real names e.g. 'Tikus', 'Sampah', 'Wayar Terdedah')",
        "agent": "string (Scientific Name or Hazard Source)",
        "disease": "string (Associated Disease/Injury in ${targetLang})",
        "microbiology": "string (Bacteria/Virus names or Physical Risk Type)",
        "statistics": "string (Real world death/case/accident stats in ${targetLang})",
        "description": "string (Full technical analysis in ${targetLang})",
        "solution": "string (Professional solution in ${targetLang})",
        "box_2d": { "ymin": number, "xmin": number, "ymax": number, "xmax": number } (Scale 0-1000),
        "citations": [ { "source": "string", "title": "string", "url": "string" } ]
      }
    ],
    "generalAdvice": "string (Executive summary in ${targetLang})",
    "savageCommentary": "string (Sarcastic/Funny comment in ${targetLang})",
    "hygieneLevel": number (1-5)
  }
  `;

  let lastError: any = null;

  // Random small delay to prevent burst issues
  await new Promise(resolve => setTimeout(resolve, Math.random() * 500));

  // LOOP THROUGH MODELS (Model Fallback)
  for (const modelId of modelsToTry) {
     try {
         console.log(`🤖 Attempting analysis with model: ${modelId} using Key Index: ${currentKeyIndex + 1}`);

         const tools = (mode === 'DETAILED') ? [{ googleSearch: {} }] : undefined;
         const maxRetries = Math.max(3, getKeyPool().length * 2);

         const response = await retryWithBackoff(async () => {
              const ai = getAIClient();
              return await ai.models.generateContent({
                model: modelId,
                contents: {
                    parts: [
                        { inlineData: { mimeType, data: base64Image } },
                        { text: `Visual forensic analysis for Vector Control, Hygiene, AND Occupational Safety & Health (OSH).

                                STRICT SCORING RUBRIC (Follow this laws, do not be lenient):
                                - SCORE 1 (CRITICAL): Presence of VECTORS (Rats, Flies, Mosquitoes, Roaches), Sewage/Mold, OR IMMEDIATE SAFETY DANGER (Exposed wiring, Fire Hazard, Chemical Leak, Collapse Risk, Blocked Emergency Exits).
                                - SCORE 2 (BAD): Visible stains, unorganized trash, food waste, OR OSH HAZARDS (Slippery floors, Trip hazards/cables, Blocked walkways, Sharp objects, Unsafe stacking, PPE violations).
                                - SCORE 3 (AVERAGE): General clutter, dusty, messy but no immediate bio-hazard or critical safety danger.
                                - SCORE 4 (GOOD): Tidy, organized, but minor imperfections.
                                - SCORE 5 (EXCELLENT): Hospital/Lab grade sterile and fully compliant with OSH standards.

                                INSTRUCTIONS:
                                1. Scan for VECTORS & HYGIENE: Stains, dust, corners, trash, pests.
                                2. Scan for OSH SAFETY HAZARDS:
                                   - Physical: Slips/Trips (wet floor, cables), blocked exits, uneven surfaces.
                                   - Electrical: Exposed wires, overloaded sockets, damaged equipment.
                                   - Chemical: Unlabeled bottles, improper storage, spills.
                                   - Structural: Cracks, unstable shelving, ceiling damage.
                                   - Ergonomic/Fire: Poorly stacked items, fire risks.
                                3. If you see trash OR trip hazards, MAX SCORE is 2.
                                4. If you see insects/rats OR exposed live wires/fire risks, MAX SCORE is 1.
                                5. Translate output to ${targetLang}.
                                6. LABEL MUST BE HUMAN READABLE. No 'risk_1'. Use 'Rats', 'Exposed Wire', etc.
                                7. Output valid JSON:
                                ${schemaDescription}

                                DO NOT use Markdown blocks. Raw JSON.` }
                    ]
                },
                config: {
                    tools: tools,
                    thinkingConfig: undefined 
                }
            });
         }, maxRetries, 1000); 

         let text = response.text;
         if (!text) throw new Error("AI returned empty response.");

         // ROBUST JSON CLEANING:
         // Sometimes AI adds text before/after JSON. We extract only the JSON block.
         const jsonMatch = text.match(/\{[\s\S]*\}/);
         if (jsonMatch) {
             text = jsonMatch[0];
         } else {
             // Fallback cleanup
             text = text.replace(/```json/g, '').replace(/```/g, '').trim();
         }

         let parsedResult: AnalysisResponse;
         try {
             parsedResult = JSON.parse(text) as AnalysisResponse;
         } catch (e) {
             console.error("JSON Parse Error on model " + modelId, text);
             throw new Error("Gagal memproses format data AI. Sila cuba gambar lain.");
         }

         const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
         if (groundingChunks) parsedResult.groundingChunks = groundingChunks;

         return parsedResult;

     } catch (error: any) {
         console.warn(`⚠️ Model ${modelId} failed:`, error.message);
         lastError = error;
     }
  }

  throw lastError || new Error("Semua model AI sibuk. Sila cuba sebentar lagi.");
};

/**
 * Manual Region Analysis
 */
export const analyzeManualRegion = async (base64Image: string, mimeType: string, box: BoundingBox, userContext: string, language: string = 'ms'): Promise<RiskDetection> => {

    const langMap: Record<string, string> = {
      'ms': 'Bahasa Melayu',
      'en': 'English',
      'zh': 'Chinese (Simplified)',
      'ta': 'Tamil'
    };
    const targetLang = langMap[language] || 'Bahasa Melayu';

    const prompt = `Focus ONLY on coordinates: Y[${box.ymin}-${box.ymax}], X[${box.xmin}-${box.xmax}] (scale 0-1000).
    User Observation: "${userContext}".
    Analyze risk for Hygiene, Vectors, OR Occupational Safety (OSH).
    Target Language: ${targetLang}.
    Label must be readable (e.g. "Lipas", not "risk_id").
    Return JSON matching RiskDetection format.`;

    const schema = {
        type: Type.OBJECT,
        properties: {
            id: { type: Type.STRING },
            category: { type: Type.STRING, enum: ["VECTOR", "HYGIENE", "SAFETY"] },
            label: { type: Type.STRING },
            agent: { type: Type.STRING },
            disease: { type: Type.STRING },
            microbiology: { type: Type.STRING },
            statistics: { type: Type.STRING },
            description: { type: Type.STRING },
            solution: { type: Type.STRING },
            box_2d: {
                type: Type.OBJECT,
                properties: {
                  ymin: { type: Type.NUMBER },
                  xmin: { type: Type.NUMBER },
                  ymax: { type: Type.NUMBER },
                  xmax: { type: Type.NUMBER }
                }
            },
            citations: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { id: {type:Type.NUMBER}, source: {type:Type.STRING}, title:{type:Type.STRING}, url:{type:Type.STRING} } } }
        }
    };

    const response = await retryWithBackoff(async () => {
        const ai = getAIClient();
        return await ai.models.generateContent({
            // Use Flash for manual region to be fast and safe
            model: "gemini-2.5-flash", 
            contents: {
                parts: [
                    { inlineData: { mimeType, data: base64Image } },
                    { text: prompt }
                ]
            },
            config: {
                responseMimeType: "application/json",
                responseSchema: schema,
            }
        });
    });

    const text = response.text;
    const result = JSON.parse(text!);
    result.id = `manual-${Date.now()}`; 
    return result;
};

export const generateHighEndPrompt = async (base64Image: string, mimeType: string): Promise<string> => {
    const prompt = `
    Analyze this image for an "Image-to-Image" (Img2Img) AI clean-up task.
    Goal: Create a prompt to regenerate this scene with hygiene issues resolved, BUT KEEP THE LAYOUT AND PEOPLE.

    STRICT INSTRUCTIONS:
    1. PRESERVE LAYOUT: The room geometry, windows, and furniture positions MUST remain identical.
    2. PRESERVE PEOPLE: If there are humans, keep them in the exact same spots. Describe them as "professional workers" if needed, but do not remove them.
    3. CLEAN UP: Only remove trash, stains, clutter, and pests.
    4. ATMOSPHERE: Bright, clean, sterile.

    Output a detailed prompt for Midjourney/Flux. 
    Start with: "A photo of [describe room]..."
    End with: "--no trash, dirt, pests --iw 2" (Image Weight high).
    `;

    const response = await retryWithBackoff(async () => {
        const ai = getAIClient();
        return await ai.models.generateContent({
            model: "gemini-2.5-flash", 
            contents: {
                parts: [
                    { inlineData: { mimeType, data: base64Image } },
                    { text: prompt }
                ]
            }
        });
    });

    return response.text || "Modern clean room, same layout, professional workers, sterile environment, no trash, photorealistic, 8k.";
};

/**
 * REFACTORED: Hybrid Image Generation System with User Preference
 */
export const generateCleanSimulation = async (base64Image: string, mimeType: string, config: SimulationConfig): Promise<string> => {

    // STEP 1: Describe the room layout using a reliable text model
    console.log("🎨 Step 1: Analyzing room geometry...");
    let genPrompt = "";
    let roomDescription = "A standard room layout.";

    try {
        const layoutPrompt = `
        Analyze this image. Describe the room's perspective, architectural layout, window placement, and major furniture geometry in detail.
        Mention if there are people and where they are standing.
        Ignore the dirt, trash, and mess. Focus ONLY on the structure and humans.
        `;

        const descResponse = await retryWithBackoff(async () => {
             const ai = getAIClient();
             return await ai.models.generateContent({
                model: "gemini-2.5-flash",
                contents: {
                    parts: [
                        { inlineData: { mimeType, data: base64Image } },
                        { text: layoutPrompt }
                    ]
                }
            });
        });

        roomDescription = descResponse.text || roomDescription;

        // Construct the prompt - FORCE BRIGHT LIGHTING
        genPrompt = `Photorealistic wide shot of: ${roomDescription}. `;

        if (config.mode === 'RECONSTRUCT') {
            genPrompt += "Style: Modern futuristic sterile white hospital laboratory, blue LED accents, bright daylight. ";
        } else {
            // CLEAN mode
            genPrompt += "Style: Extremely clean version of the same room. Tidy, organized, freshly polished floors. ";
        }

        if (config.humans === 'REMOVE') {
            genPrompt += "No people, empty room. ";
        } else {
            genPrompt += "Keep the people in the exact same positions but wearing clean clothes or safety gear. ";
        }

        if (config.furniture === 'REPLACE') {
            genPrompt += "Replace old furniture with modern white equipment. ";
        } else {
            genPrompt += "Keep existing furniture but make it look new and clean. ";
        }

        genPrompt += "Unreal Engine 5 render, 8k resolution, high key lighting, crisp details, no trash, no dirt.";

    } catch (e) {
        console.warn("Step 1 Analysis Failed, using generic prompt");
        genPrompt = "A clean, modern version of this room, sterile environment, 8k resolution, bright cinematic lighting, same layout.";
    }

    // Define function for external generator
    const callExternalGenerator = async () => {
        console.log("✅ Using External Engine: Pollinations.ai");
        try {
            const seed = Math.floor(Math.random() * 1000000);
            const simplePrompt = `modern clean room, ${genPrompt.substring(0, 150)}, bright lighting, 8k, photorealistic`;
            const fallbackUrl = `https://image.pollinations.ai/prompt/${encodeURIComponent(simplePrompt)}?width=1280&height=720&seed=${seed}&nolog=true&model=flux`;
            await new Promise(r => setTimeout(r, 2500)); // Artificial delay
            return fallbackUrl;
        } catch (error) {
            throw new Error("External Generator Failed.");
        }
    };

    // DECISION TREE BASED ON CONFIG
    if (config.engine === 'EXTERNAL') {
        return await callExternalGenerator();
    }

    // DEFAULT OR GOOGLE MODE
    console.log("🎨 Step 2: Attempting Google Imagen...");

    try {
        // Use the Imagen model for generation
        const maxRetries = 2; 

        const imageResponse = await retryWithBackoff(async () => {
             const ai = getAIClient();
             return await ai.models.generateImages({
                model: "imagen-3.0-generate-001", 
                prompt: genPrompt,
                config: {
                    numberOfImages: 1,
                    aspectRatio: "1:1" 
                }
            });
        }, maxRetries, 1000);

        const generatedImage = imageResponse.generatedImages?.[0]?.image?.imageBytes;
        if (!generatedImage) throw new Error("No image data received from Imagen.");

        return `data:image/png;base64,${generatedImage}`;

    } catch (e: any) {
        // Handle Failure
        if (config.engine === 'GOOGLE') {
             // If user explicitly wanted Google but it failed, throw error
             throw new Error(`Google Imagen Failed: ${e.message}. Try changing Engine to 'External'.`);
        } else {
             // AUTO mode: Fallback to External
             console.warn("⚠️ Google Imagen Failed. Falling back to External Engine...");
             return await callExternalGenerator();
        }
    }
};

export const askRiskFollowUp = async (risk: RiskDetection, question: string, language: string = 'ms'): Promise<string> => {
    const langMap: Record<string, string> = {
      'ms': 'Bahasa Melayu',
      'en': 'English',
      'zh': 'Chinese (Simplified)',
      'ta': 'Tamil'
    };
    const targetLang = langMap[language] || 'Bahasa Melayu';

    const response = await retryWithBackoff(async () => {
        const ai = getAIClient();
        return await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: `Context: Risk "${risk.label}" (Agent: ${risk.agent}). Question: "${question}". Answer in ${targetLang}. Keep it short.`
        });
    });
    return response.text || "Tiada jawapan.";
};

