}

const ExternalExportModal: React.FC<ExternalExportModalProps> = ({ isOpen, onClose, imageSrc }) => {
  const [prompt, setPrompt] = useState<string>("");
  const [isGenerating, setIsGenerating] = useState(false);
  const [copyStatus, setCopyStatus] = useState<"IDLE" | "COPIED_IMG" | "COPIED_PROMPT">("IDLE");

  useEffect(() => {
    if (isOpen && !prompt) {
      setIsGenerating(true);
      const base64Data = imageSrc.split(',')[1];
      const mimeType = imageSrc.split(';')[0].split(':')[1];

      generateHighEndPrompt(base64Data, mimeType)
        .then(text => setPrompt(text))
        .catch(err => setPrompt("Failed to generate prompt."))
        .finally(() => setIsGenerating(false));
    }
  }, [isOpen, imageSrc]);

  const handleCopyImage = async () => {
    try {
      const response = await fetch(imageSrc);
      const blob = await response.blob();
      await navigator.clipboard.write([
        new ClipboardItem({ [blob.type]: blob })
      ]);
      setCopyStatus("COPIED_IMG");
      setTimeout(() => setCopyStatus("IDLE"), 2000);
    } catch (err) {
      console.error(err);
      alert("Browser anda tidak menyokong salinan imej automatik. Sila 'Right Click > Copy Image' pada gambar di papan utama.");
    }
  };

  const handleCopyPrompt = () => {
    navigator.clipboard.writeText(prompt);
    setCopyStatus("COPIED_PROMPT");
    setTimeout(() => setCopyStatus("IDLE"), 2000);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[170] bg-black/90 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in">
        <div className="bg-slate-900 border border-purple-500 rounded-xl p-6 w-full max-w-lg shadow-[0_0_50px_rgba(168,85,247,0.3)] flex flex-col max-h-[90vh]">
