                <div className="bg-slate-800/50 p-4 rounded border border-slate-700">
                    <h4 className="text-sm font-bold text-white mb-2 flex items-center justify-between">
                        1. COPY SOURCE IMAGE
                        {copyStatus === "COPIED_IMG" && <span className="text-emerald-400 text-[10px] animate-pulse">COPIED!</span>}
                    </h4>
                    <p className="text-xs text-slate-400 mb-3">Copy this dirty image to paste into the external AI website.</p>
                    <button 
                        onClick={handleCopyImage}
                        className="w-full py-2 bg-slate-700 hover:bg-slate-600 text-white text-xs font-bold rounded border border-slate-500 flex items-center justify-center gap-2"
