                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
                        COPY IMAGE TO CLIPBOARD
                    </button>
                </div>

                <div className="bg-slate-800/50 p-4 rounded border border-slate-700">
                     <h4 className="text-sm font-bold text-white mb-2 flex items-center justify-between">
                        2. COPY HIGH-FIDELITY PROMPT
                        {copyStatus === "COPIED_PROMPT" && <span className="text-emerald-400 text-[10px] animate-pulse">COPIED!</span>}
                    </h4>
                    <p className="text-[10px] text-emerald-400 mb-2 italic">
