interface SimulationResultModalProps {
  isOpen: boolean;
  onClose: () => void;
  originalImage: string;
  generatedImage: string;
}

const SimulationResultModal: React.FC<SimulationResultModalProps> = ({ isOpen, onClose, originalImage, generatedImage }) => {
  // Slider state: 0 to 100
  const [sliderPos, setSliderPos] = useState(50);
  const containerRef = useRef<HTMLDivElement>(null);
  const isDragging = useRef(false);

  const handleDownload = () => {
     const link = document.createElement('a');
     link.href = generatedImage;
     link.download = `VectorGuard_Sim_${Date.now()}.png`;
     document.body.appendChild(link);
     link.click();
     document.body.removeChild(link);
  };

  const handleMove = (clientX: number) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
    const percent = Math.max(0, Math.min(100, (x / rect.width) * 100));
    setSliderPos(percent);
  };

  const onMouseDown = (e: React.MouseEvent) => {
    isDragging.current = true;
    handleMove(e.clientX);
  };

  const onTouchStart = (e: React.TouchEvent) => {
    isDragging.current = true;
    handleMove(e.touches[0].clientX);
  };

  const onMouseMove = (e: React.MouseEvent) => {
    if (isDragging.current) handleMove(e.clientX);
  };

  const onTouchMove = (e: React.TouchEvent) => {
    if (isDragging.current) handleMove(e.touches[0].clientX);
  };

  const onStop = () => {
    isDragging.current = false;
  };

  useEffect(() => {
      document.addEventListener('mouseup', onStop);
      document.addEventListener('touchend', onStop);
      return () => {
          document.removeEventListener('mouseup', onStop);
          document.removeEventListener('touchend', onStop);
      };
  }, []);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[180] bg-black/90 backdrop-blur-md flex items-center justify-center p-4 animate-fade-in">
        <div className="bg-slate-900 border border-cyan-500 rounded-xl w-full max-w-5xl h-[85vh] flex flex-col shadow-[0_0_50px_rgba(34,211,238,0.2)] overflow-hidden">
             {/* Header */}
             <div className="p-4 border-b border-slate-700 flex justify-between items-center bg-slate-950">
                 <h3 className="text-lg md:text-xl font-sci-fi font-bold text-white flex items-center gap-2">
                    <span className="text-cyan-400 animate-pulse">✨ SIMULATION COMPLETE</span>
                 </h3>
                 <button onClick={onClose} className="p-2 hover:bg-slate-800 rounded-full text-slate-400 hover:text-white transition">
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
                      <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                    </svg>
                 </button>
             </div>

             {/* Content: Slider */}
             <div className="flex-1 relative bg-black/50 overflow-hidden flex items-center justify-center p-4 select-none">
                 <div 
                    ref={containerRef}
                    className="relative w-full h-full max-h-full aspect-video border border-slate-700 shadow-2xl rounded overflow-hidden cursor-ew-resize"
                    onMouseDown={onMouseDown}
                    onTouchStart={onTouchStart}
                    onMouseMove={onMouseMove}
                    onTouchMove={onTouchMove}
                 >
                    {/* Background (Before) */}
                    <img 
                        src={originalImage} 
                        alt="Before" 
                        className="absolute inset-0 w-full h-full object-contain bg-slate-900 select-none pointer-events-none" 
                    />
                    <div className="absolute top-4 left-4 bg-black/70 text-white text-xs font-bold px-3 py-1 rounded backdrop-blur border border-slate-600 z-10">
                        ORIGINAL (BEFORE)
                    </div>

                    {/* Foreground (After) - Clipped */}
                    <div 
                        className="absolute inset-0 overflow-hidden bg-slate-900"
                        style={{ clipPath: `inset(0 ${100 - sliderPos}% 0 0)` }}
                    >
                        <img 
                            src={generatedImage} 
                            alt="After" 
                            className="absolute inset-0 w-full h-full object-contain select-none pointer-events-none" 
                        />
                        <div className="absolute top-4 right-4 bg-cyan-600/90 text-white text-xs font-bold px-3 py-1 rounded backdrop-blur border border-cyan-400 z-10 shadow-[0_0_15px_cyan]">
                             SIMULATION (AFTER)
                        </div>
                    </div>

                    {/* Slider Handle */}
                    <div 
                        className="absolute top-0 bottom-0 w-1 bg-white cursor-ew-resize z-20 shadow-[0_0_10px_black]"
                        style={{ left: `${sliderPos}%` }}
                    >
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-lg border-4 border-cyan-500">
                             <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5 text-cyan-700">
                                <path strokeLinecap="round" strokeLinejoin="round" d="M8.25 15L12 18.75 15.75 15m-7.5-6L12 5.25 15.75 9" />
                             </svg>
                        </div>
                    </div>
                 </div>
             </div>

             {/* Footer Controls */}
             <div className="p-4 bg-slate-950 border-t border-slate-700 flex flex-col md:flex-row gap-4 justify-between items-center">
                 <div className="text-xs text-slate-400 font-mono-sci hidden md:block">
                    DRAG SLIDER TO COMPARE
                 </div>

                 <button 
                    onClick={handleDownload}
                    className="flex items-center gap-2 px-6 py-3 bg-emerald-600 hover:bg-emerald-500 text-white font-bold rounded shadow-lg shadow-emerald-500/20 transition-all active:scale-95 w-full md:w-auto justify-center"
                 >
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                      <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75V16.5M12 12.75l-3-3m0 0l3-3m-3 3h12" />
                    </svg>
                    DOWNLOAD RESULT
                 </button>
             </div>
        </div>
