                    <div className="text-[10px] text-slate-400 font-mono-sci uppercase">Hygiene Score</div>
                    <div className="text-xl font-bold text-white font-sci-fi">LEVEL {result.hygieneLevel}/5</div>
                 </div>
                 <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-lg border-2 ${result.hygieneLevel >= 4 ? 'border-emerald-500 text-emerald-400' : result.hygieneLevel >= 3 ? 'border-amber-500 text-amber-400' : 'border-red-500 text-red-500 bg-red-900/20'}`}>
                    {result.hygieneLevel}
                 </div>
              </div>
           </div>

           <div className="grid grid-cols-1 gap-4">
              {bioRisks.length > 0 && (
                <div className="bg-slate-900/50 border border-slate-800 rounded-lg p-3 md:p-4">
                   <h3 className="text-xs text-slate-500 font-mono-sci uppercase mb-3 flex items-center gap-2">
                      <span className="w-2 h-2 bg-amber-500 rounded-full"></span> {t('risk_vector')}
                   </h3>
                   <div className="space-y-2 max-h-[300px] overflow-y-auto custom-scrollbar">
                      {bioRisks.map((risk) => (
                         <RiskListItem key={risk.id} risk={risk} index={getRiskIndex(risk)} activeId={activeRisk.id} onClick={handleRiskChange} />
                      ))}
                   </div>
                </div>
              )}

              {safetyRisks.length > 0 && (
                <div className="bg-slate-900/50 border border-slate-800 rounded-lg p-3 md:p-4">
                   <h3 className="text-xs text-slate-500 font-mono-sci uppercase mb-3 flex items-center gap-2">
                      <span className="w-2 h-2 bg-indigo-500 rounded-full"></span> {t('risk_safety')}
                   </h3>
                   <div className="space-y-2 max-h-[300px] overflow-y-auto custom-scrollbar">
                      {safetyRisks.map((risk) => (
                         <RiskListItem key={risk.id} risk={risk} index={getRiskIndex(risk)} activeId={activeRisk.id} onClick={handleRiskChange} />
                      ))}
                   </div>
                </div>
              )}
           </div>
        </div>

        <div id="details-panel" className="lg:col-span-5 flex flex-col h-full gap-4">
            <HygieneVerdictCard hygieneLevel={result.hygieneLevel} isSavage={isSavageMode} />

            {result.groundingChunks && result.groundingChunks.length > 0 && (
                <div className="bg-blue-900/20 border border-blue-500/30 p-4 rounded-xl backdrop-blur-sm animate-fade-in-up">
                    <h3 className="text-xs text-blue-400 font-bold font-mono-sci uppercase mb-3 flex items-center gap-2">
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-4 h-4"><path fillRule="evenodd" d="M12 2.25c-5.385 0-9.75 4.365-9.75 9.75s4.365 9.75 9.75 9.75 9.75-4.365 9.75-9.75S17.385 2.25 12 2.25zm4.28 10.28a.75.75 0 000-1.06l-3-3a.75.75 0 10-1.06 1.06l1.72 1.72H8.25a.75.75 0 000 1.5h5.69l-1.72 1.72a.75.75 0 101.06 1.06l3-3z" clipRule="evenodd" /></svg>
                        {t('card_source')}
                    </h3>
                    <div className="flex flex-wrap gap-2">
                        {result.groundingChunks.map((chunk, i) => (
                             chunk.web?.uri ? (
                                <a 
                                  key={i} 
                                  href={chunk.web.uri} 
                                  target="_blank" 
                                  rel="noopener noreferrer"
                                  className="text-[10px] bg-blue-950/50 hover:bg-blue-800 text-blue-300 border border-blue-800 rounded-full px-3 py-1 truncate max-w-[200px] transition-colors flex items-center gap-1"
                                >
                                    <span className="w-1.5 h-1.5 bg-blue-500 rounded-full shrink-0"></span>
                                    {chunk.web.title || "Source Link"}
                                </a>
                             ) : null
                        ))}
                    </div>
                </div>
            )}

            <div className={`relative flex-1 bg-slate-900/90 border border-slate-700 rounded-xl p-6 md:p-8 backdrop-blur-md shadow-2xl overflow-hidden flex flex-col transition-all duration-500 ${isSavageMode ? 'border-red-500/30 shadow-[0_0_30px_rgba(220,38,38,0.1)]' : ''}`}>
                <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none">
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-32 h-32 md:w-48 md:h-48">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126zM12 15.75h.007v.008H12v-.008z" />
                    </svg>
                </div>

                <div className="relative z-10 flex-1 flex flex-col">
                    <div className="mb-6 md:mb-8 border-b border-slate-700/50 pb-6">
                        <div className="flex items-center gap-3 mb-3">
                            <span className={`px-2 py-0.5 rounded text-[10px] md:text-xs font-bold font-mono-sci uppercase tracking-widest ${activeRisk.category === 'HYGIENE' ? 'bg-amber-500 text-black' : activeRisk.category === 'SAFETY' ? 'bg-indigo-500 text-white' : 'bg-red-600 text-white'}`}>
                                {activeRisk.category} THREAT
                            </span>
                            <span className="text-slate-500 text-[10px] md:text-xs font-mono-sci">
                                #{getRiskIndex(activeRisk).toString().padStart(2, '0')}
                            </span>
                        </div>

                        <h2 className="text-2xl md:text-3xl lg:text-4xl font-sci-fi font-bold text-white mb-2 leading-tight break-words">
                            {activeRisk.label}
                        </h2>

                        <div className="mt-2">
                             <h3 className="text-slate-400 text-[10px] md:text-xs font-mono-sci tracking-widest uppercase mb-1">Identified Agent</h3>
                             <p className="text-lg md:text-xl lg:text-2xl text-emerald-400 font-mono-sci italic break-words leading-tight">
                                {activeRisk.agent}
                             </p>
                        </div>
                    </div>

                    <div className="flex-1 overflow-y-auto custom-scrollbar space-y-6 md:space-y-8 pr-2">
                        <div>
                             <h4 className="text-emerald-500 font-bold text-xs font-sci-fi uppercase mb-2 flex items-center gap-2">
                                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                                {t('card_analysis')}
                             </h4>
                             <p className="text-slate-300 text-sm md:text-base leading-relaxed font-light">
                                {activeRisk.description}
                             </p>
                        </div>

                         <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                             <div className="bg-slate-950/50 p-3 rounded border border-slate-800">
                                 <h4 className="text-purple-400 font-bold text-[10px] font-mono-sci uppercase mb-2">{t('card_microbio')}</h4>
                                 <p className="text-slate-300 text-xs md:text-sm">{activeRisk.microbiology}</p>
                             </div>
                             <div className="bg-slate-950/50 p-3 rounded border border-slate-800">
                                 <h4 className="text-red-400 font-bold text-[10px] font-mono-sci uppercase mb-2">{t('card_stats')}</h4>
                                 <p className="text-slate-300 text-xs md:text-sm">{activeRisk.statistics}</p>
                             </div>
                         </div>

                         <div className={`p-4 md:p-5 rounded-lg border relative overflow-hidden transition-colors duration-500 ${isSavageMode ? 'bg-red-900/10 border-red-500/30' : 'bg-emerald-900/10 border-emerald-500/30'}`}>
                             <div className="absolute top-3 right-3 opacity-20 md:opacity-100">
                                <NightmareChefAvatar hygieneLevel={result.hygieneLevel} isSavage={isSavageMode} />
                             </div>

                             <h4 className={`font-bold text-xs font-sci-fi uppercase mb-3 flex items-center gap-2 ${isSavageMode ? 'text-red-400' : 'text-emerald-400'}`}>
                                {isSavageMode ? t('card_savage_verdict') : t('card_recommendation')}
                             </h4>

                             <div className="pr-0 md:pr-16 text-sm md:text-base text-slate-200 leading-relaxed italic">
                                 {isSavageMode 
                                    ? `"${result.savageCommentary || 'This place is a disaster waiting to happen.'}"` 
                                    : activeRisk.solution
                                 }
                             </div>
                         </div>

                         <a 
                            href={generateYoutubeLink(activeRisk)} 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className="flex items-center justify-center gap-2 w-full bg-slate-800 hover:bg-slate-700 py-3 rounded text-xs md:text-sm font-bold text-white transition-colors border border-slate-600"
                         >
                            <svg className="w-4 h-4 text-red-500" fill="currentColor" viewBox="0 0 24 24"><path d="M19.615 3.184c-3.604-.246-11.631-.245-15.23 0-3.897.266-4.356 2.62-4.385 8.816.029 6.185.484 8.549 4.385 8.816 3.6.245 11.626.246 15.23 0 3.897-.266 4.356-2.62 4.385-8.816-.029-6.185-.484-8.549-4.385-8.816zm-10.615 12.816v-8l8 3.993-8 4.007z"/></svg>
                            {t('btn_microscope')}
                         </a>

                    </div>

                    <div className="mt-4 pt-4 border-t border-slate-800">
                        {chatMessages.length > 0 && (
                            <div className="mb-3 max-h-[150px] overflow-y-auto custom-scrollbar bg-black/40 rounded p-2 text-xs space-y-2">
                                {chatMessages.map((msg, idx) => (
                                    <div key={idx} className={`${msg.role === 'user' ? 'text-right text-emerald-300' : 'text-left text-slate-300'}`}>
                                        <span className="font-bold">{msg.role === 'user' ? 'YOU: ' : 'AI: '}</span>
                                        {msg.text}
                                    </div>
                                ))}
                                <div ref={chatEndRef}></div>
                            </div>
                        )}

                        <form onSubmit={handleAskAI} className="relative">
                            <input 
                                type="text" 
                                value={userQuestion}
                                onChange={(e) => setUserQuestion(e.target.value)}
                                placeholder={t('chat_placeholder')}
                                disabled={isChatLoading}
                                className="w-full bg-slate-950 border border-slate-700 rounded-full py-3 px-5 pr-12 text-sm text-white focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none placeholder:text-slate-600"
                            />
                            <button 
                                type="submit" 
                                disabled={isChatLoading || !userQuestion.trim()}
                                className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-emerald-600 rounded-full text-white disabled:opacity-50 hover:bg-emerald-500 transition-colors"
                            >
                                {isChatLoading ? (
                                    <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                                ) : (
                                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-4 h-4">
                                        <path d="M3.478 2.405a.75.75 0 00-.926.94l2.432 7.905H13.5a.75.75 0 010 1.5H4.984l-2.432 7.905a.75.75 0 00.926.94 60.519 60.519 0 0018.445-8.986.75.75 0 000-1.218A60.517 60.517 0 003.478 2.405z" />
                                    </svg>
                                )}
                            </button>
                        </form>
                    </div>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
