  const [prompt, setPrompt] = useState<string>("");
  const [isGenerating, setIsGenerating] = useState(false);
  const [copyStatus, setCopyStatus] = useState<"IDLE" | "COPIED_IMG" | "COPIED_PROMPT">("IDLE");

  useEffect(() => {
    if (isOpen && !prompt) {
      setIsGenerating(true);
      const base64Data = imageSrc.split(',')[1];
      const mimeType = imageSrc.split(';')[0].split(':')[1];

      generateHighEndPrompt(base64Data, mimeType)
        .then(text => setPrompt(text))
        .catch(err => setPrompt("Failed to generate prompt."))
        .finally(() => setIsGenerating(false));
    }
  }, [isOpen, imageSrc]);

  const handleCopyImage = async () => {
    try {
      const response = await fetch(imageSrc);
      const blob = await response.blob();
      await navigator.clipboard.write([
        new ClipboardItem({ [blob.type]: blob })
      ]);
      setCopyStatus("COPIED_IMG");
      setTimeout(() => setCopyStatus("IDLE"), 2000);
