  const [cleanImage, setCleanImage] = useState<string | null>(null);
  const [showCleanModal, setShowCleanModal] = useState(false);
  const [showConfigModal, setShowConfigModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);

  const { language, t } = useLanguage();

  useEffect(() => {
    if (currentRisks && currentRisks.length > 0) {
      if (!activeRisk) setActiveRisk(currentRisks[0]);
    }
  }, [currentRisks]);

  const handleRiskChange = (risk: RiskDetection) => {
    setActiveRisk(risk);
    setChatOpen(false);
    setChatMessages([]);
    if (window.innerWidth < 1024) {
      setTimeout(() => {
        document.getElementById('details-panel')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 100);
    }
  }

  const bioRisks = currentRisks.filter(r => r.category === 'VECTOR' || r.category === 'HYGIENE');
  const safetyRisks = currentRisks.filter(r => r.category === 'SAFETY');

  // Helper to find index across full array for display
  const getRiskIndex = (risk: RiskDetection) => {
     return currentRisks.findIndex(r => r.id === risk.id) + 1;
  };

  const handleRegionDrawn = (box: BoundingBox) => {
    setManualBox(box);
    setShowManualModal(true);
    setIsEditing(false);
  };

  const submitManualAnalysis = async () => {
    if (!manualBox || !manualContext) return;
    setIsProcessingManual(true);
    try {
        const cleanBase64 = imageSrc.split(',')[1] || imageSrc;
        const mimeType = imageSrc.split(';')[0].split(':')[1] || 'image/jpeg';

        // The service now uses Gemini 3.0 Pro with a strict bounding box prompt
        const newRisk = await analyzeManualRegion(cleanBase64, mimeType, manualBox, manualContext, language);

        const updatedRisks = [newRisk, ...currentRisks];
        setCurrentRisks(updatedRisks);
        setActiveRisk(newRisk);
        setShowManualModal(false);
        setManualContext("");
        setManualBox(null);
    } catch (e) {
        alert("Gagal memproses kawasan manual. Sila cuba lagi.");
        console.error(e);
    } finally {
        setIsProcessingManual(false);
    }
  };

  const cancelManualMode = () => {
    setIsEditing(false);
    setShowManualModal(false);
    setManualBox(null);
    setManualContext("");
  };

  const handleOpenSimulation = () => {
      if (cleanImage) {
          setShowCleanModal(true);
      } else {
          setShowConfigModal(true);
      }
  };

  const startSimulation = async (config: SimulationConfig) => {
      setShowConfigModal(false);
      setIsCleaning(true);
      try {
          const base64Data = imageSrc.split(',')[1];
          const mimeType = imageSrc.split(';')[0].split(':')[1] || 'image/jpeg';
          const generatedImage = await generateCleanSimulation(base64Data, mimeType, config);
          setCleanImage(generatedImage);
          setShowCleanModal(true);
      } catch (error: any) {
          const msg = error.message || "";
          if (msg.includes("AI Refusal") || msg.includes("Safety") || msg.includes("blocked")) {
              alert("SIMULATION FAILED: Safety filters triggered.");
          } else {
              alert(`SIMULATION FAILED: ${msg}`);
          }
      } finally {
          setIsCleaning(false);
      }
  };

  const handleAskAI = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userQuestion.trim() || !activeRisk) return;
    const newMsg: ChatMessage = { role: 'user', text: userQuestion };
    setChatMessages(prev => [...prev, newMsg]);
    setUserQuestion("");
    setIsChatLoading(true);
    try {
      const response = await askRiskFollowUp(activeRisk, newMsg.text, language);
      setChatMessages(prev => [...prev, { role: 'model', text: response }]);
    } catch (error) {
      console.error(error);
      setChatMessages(prev => [...prev, { role: 'model', text: "Error contacting AI." }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const handlePrint = () => {
      window.print();
  };

  const generateYoutubeLink = (risk: RiskDetection) => {
     const query = encodeURIComponent(`microscope view ${risk.agent} ${risk.label}`);
     return `https://www.youtube.com/results?search_query=${query}`;
  };

  if (showReportPreview) {
    return (
      <div className="fixed inset-0 z-[200] bg-gray-100 overflow-y-auto font-sans text-slate-900 animate-fade-in">
         {/* ... (Report Preview Code Remains Same) ... */}
         {/* Reusing existing code structure for brevity, assuming standard report layout */}
         <div className="sticky top-0 z-50 bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center no-print">
            <h2 className="font-bold text-lg flex items-center gap-2">
               <span className="text-emerald-500">📄</span> {t('btn_view_report')}
            </h2>
            <div className="flex gap-3">
               <button onClick={() => setShowReportPreview(false)} className="px-4 py-2 rounded border border-slate-600 hover:bg-slate-800 transition">
                  BACK
               </button>
               <button onClick={handlePrint} className="bg-emerald-600 hover:bg-emerald-500 px-6 py-2 rounded font-bold shadow-lg flex items-center gap-2">
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                     <path strokeLinecap="round" strokeLinejoin="round" d="M6.72 13.829c-.24.03-.48.062-.72.096m.72-.096a42.415 42.415 0 0110.56 0m-10.56 0L6.34 18m10.94-4.171c.24.03.48.062.72.096m-.72-.096L17.66 18m0 0l.229 2.523a1.125 1.125 0 01-1.12 1.227H7.231c-.662 0-1.18-.568-1.12-1.227L6.34 18m11.318 0h1.091A2.25 2.25 0 0021 15.75V9.456c0-1.081-.768-2.015-1.837-2.175a48.055 48.055 0 00-1.913-.247M6.34 18H5.25A2.25 2.25 0 013 15.75V9.456c0-1.081.768-2.015 1.837-2.175a48.041 48.041 0 011.913-.247m10.5 0a48.536 48.536 0 00-10.5 0m10.5 0V3.375c0-.621-.504-1.125-1.125-1.125h-8.25c-.621 0-1.125.504-1.125 1.125v3.659M18 10.5h.008v.008H18V10.5zm-3 0h.008v.008H15V10.5z" />
                  </svg>
                  PRINT / PDF
               </button>
            </div>
         </div>

         <div className="max-w-[210mm] mx-auto bg-white min-h-[297mm] shadow-2xl my-8 p-8 md:p-12 box-border">
            <div className="border-b-2 border-slate-800 pb-6 mb-8 flex justify-between items-start">
               <div>
                  <h1 className="text-3xl font-extrabold text-slate-900 tracking-tight uppercase mb-2">{t('results_title')}</h1>
                  <p className="text-sm text-slate-500 font-mono">VECTORGUARD.AI INTELLIGENCE UNIT</p>
                  <p className="text-sm text-slate-500 mt-1">Date: {new Date().toLocaleDateString()}</p>
               </div>
               <div className="text-right">
                  <div className="bg-slate-900 text-white px-4 py-2 inline-block rounded-lg mb-2">
                     <span className="block text-xs uppercase tracking-widest opacity-70">Score</span>
                     <span className="block text-2xl font-bold">{result.hygieneLevel}/5</span>
                  </div>
               </div>
            </div>

            <div className="mb-8 p-2 border border-slate-200 rounded bg-slate-50">
               <img src={imageSrc} alt="Evidence" className="w-full h-auto max-h-[400px] object-contain mx-auto" />
            </div>

            {/* Grounding Info */}
             {result.groundingChunks && result.groundingChunks.length > 0 && (
                <div className="mb-8 bg-blue-50 border border-blue-200 p-4 rounded-lg">
                    <h3 className="text-sm font-bold text-blue-800 uppercase mb-2">{t('card_source')}</h3>
                    <ul className="text-xs text-blue-700 space-y-1">
                        {result.groundingChunks.map((chunk, i) => (
                            <li key={i} className="truncate">
                                <a href={chunk.web?.uri} target="_blank" rel="noopener" className="hover:underline">
                                    [{i+1}] {chunk.web?.title} - {chunk.web?.uri}
                                </a>
                            </li>
                        ))}
                    </ul>
                </div>
            )}

            <div className="mb-8">
               <h3 className="text-lg font-bold text-slate-800 uppercase border-l-4 border-emerald-600 pl-3 mb-4">{t('card_recommendation')}</h3>
               <p className="text-slate-700 leading-relaxed text-justify bg-slate-50 p-4 rounded border border-slate-100 text-sm">
                  {result.generalAdvice}
               </p>
            </div>

            <div className="mb-8">
               <h3 className="text-lg font-bold text-slate-800 uppercase border-l-4 border-red-600 pl-3 mb-4">{t('card_analysis')}</h3>
               <div className="space-y-6">
                  {currentRisks.map((risk, index) => (
                     <div key={risk.id} className="break-inside-avoid border border-slate-300 rounded-lg overflow-hidden">
                        <div className="bg-slate-100 px-4 py-3 border-b border-slate-300 flex justify-between items-center">
                           <div className="font-bold text-slate-800 flex items-center gap-2">
                              <span className="bg-slate-800 text-white w-6 h-6 rounded-full flex items-center justify-center text-xs">{index + 1}</span>
                              {risk.label}
                           </div>
                           <span className={`text-xs font-bold px-2 py-1 rounded border ${risk.category === 'VECTOR' ? 'bg-red-100 text-red-800 border-red-200' : 'bg-amber-100 text-amber-800 border-amber-200'}`}>
                              {risk.category}
                           </span>
                        </div>
                        <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
                           <div className="col-span-2 md:col-span-1">
                              <p className="text-xs text-slate-500 uppercase tracking-wide font-bold mb-1">Agent:</p>
                              <p className="font-semibold text-slate-900 italic">{risk.agent}</p>
                           </div>
                           <div className="col-span-2 md:col-span-1">
                              <p className="text-xs text-slate-500 uppercase tracking-wide font-bold mb-1">Disease:</p>
                              <p className="text-slate-900">{risk.disease}</p>
                           </div>
                           <div className="col-span-2 bg-slate-50 p-3 rounded border border-slate-200">
                              <p className="text-xs text-slate-500 uppercase tracking-wide font-bold mb-1">Details:</p>
                              <p className="text-slate-700 text-justify leading-relaxed">{risk.description}</p>
                           </div>
                           <div className="col-span-2 md:col-span-1 bg-red-50 p-3 rounded border border-red-100">
                              <p className="text-xs text-red-500 uppercase tracking-wide font-bold mb-1">Microbiology:</p>
                              <p className="text-slate-800">{risk.microbiology}</p>
                           </div>
                           <div className="col-span-2 md:col-span-1 bg-blue-50 p-3 rounded border border-blue-100">
                              <p className="text-xs text-blue-500 uppercase tracking-wide font-bold mb-1">Stats:</p>
                              <p className="text-slate-800">{risk.statistics}</p>
                           </div>
                           <div className="col-span-2 border-t border-slate-200 pt-3 mt-1">
                              <p className="text-xs text-emerald-600 uppercase tracking-wide font-bold mb-1">Action:</p>
                              <p className="text-slate-800 font-medium">{risk.solution}</p>
                           </div>
                        </div>
                     </div>
                  ))}
               </div>
            </div>

            <div className="border-t-2 border-slate-800 pt-6 mt-12 text-center text-xs text-slate-500">
               <p>Generated by VectorGuard AI.</p>
            </div>
         </div>
      </div>
    );
  }

  // MANUAL TARGETING MODAL
  if (showManualModal) {
     return (
        <div className="fixed inset-0 z-[200] bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-slate-900 border border-emerald-500 rounded-xl p-6 w-full max-w-sm shadow-2xl animate-fade-in-up">
                <h3 className="text-lg font-sci-fi font-bold text-white mb-4 flex items-center gap-2">
                    <span className="text-emerald-400">🎯 MANUAL TARGETING</span>
                </h3>
                <div className="mb-4">
                    <label className="text-xs text-slate-400 block mb-2 font-mono-sci">WHAT ARE WE LOOKING AT?</label>
                    <textarea 
                        value={manualContext}
                        onChange={(e) => setManualContext(e.target.value)}
                        placeholder="e.g. Look at the dark spot in the corner..."
                        rows={3}
                        className="w-full bg-slate-950 border border-slate-700 rounded p-3 text-white text-sm focus:border-emerald-500 outline-none"
                    />
                </div>
                <div className="flex gap-2">
                    <button onClick={cancelManualMode} disabled={isProcessingManual} className="flex-1 py-2 bg-slate-800 text-slate-300 rounded hover:bg-slate-700 transition">
                        CANCEL
                    </button>
                    <button 
                        onClick={submitManualAnalysis} 
                        disabled={!manualContext.trim() || isProcessingManual}
                        className="flex-1 py-2 bg-emerald-600 text-white rounded font-bold hover:bg-emerald-500 transition shadow-[0_0_15px_rgba(16,185,129,0.4)] disabled:opacity-50 flex items-center justify-center gap-2"
                    >
                        {isProcessingManual ? (
                            <>
                                <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                                SCANNING...
                            </>
                        ) : (
                            "ANALYZE REGION"
                        )}
                    </button>
                </div>
            </div>
        </div>
     )
  }

  if (!activeRisk) return null;

  return (
    <div className="animate-fade-in pb-20">
      <SimulationConfigModal 
        isOpen={showConfigModal} 
        onClose={() => setShowConfigModal(false)}
        onStart={startSimulation}
      />
      <SimulationResultModal
        isOpen={showCleanModal}
        onClose={() => setShowCleanModal(false)}
        originalImage={imageSrc}
        generatedImage={cleanImage || ""}
      />
      <ExternalExportModal
        isOpen={showExportModal}
        onClose={() => setShowExportModal(false)}
        imageSrc={imageSrc}
      />
      {/* ... (Rest of AnalysisResults render remains same) ... */}
      <div className="flex flex-wrap gap-3 justify-between items-center mb-4 md:mb-6 no-print">
         <div className="flex gap-2">
            <button 
                onClick={() => setIsEditing(!isEditing)}
                className={`flex items-center gap-2 px-3 py-1.5 md:px-4 md:py-2 rounded text-xs md:text-sm font-bold uppercase tracking-wider transition-all border
                    ${isEditing 
                        ? 'bg-red-600 text-white border-red-500 shadow-[0_0_15px_red] animate-pulse' 
                        : 'bg-slate-800 text-slate-300 border-slate-600 hover:border-emerald-500 hover:text-emerald-400'}
                `}
            >
                {isEditing ? '🔴 TARGETING ACTIVE' : `🎯 ${t('btn_manual_scan')}`}
            </button>

            <button
                onClick={handleOpenSimulation}
                disabled={isCleaning}
                className={`flex items-center gap-2 px-3 py-1.5 md:px-4 md:py-2 rounded text-xs md:text-sm font-bold uppercase tracking-wider transition-all border border-cyan-500/50 hover:bg-cyan-900/30 text-cyan-400 hover:shadow-[0_0_15px_rgba(34,211,238,0.4)] disabled:opacity-50`}
            >
                {isCleaning ? (
                    <span className="flex items-center gap-2 animate-pulse">
                        SIMULATING...
                    </span>
                ) : (
                    <>✨ {t('btn_simulation')}</>
                )}
            </button>

            <button
                onClick={() => setShowExportModal(true)}
                className="flex items-center gap-2 px-3 py-1.5 md:px-4 md:py-2 rounded text-xs md:text-sm font-bold uppercase tracking-wider transition-all border border-purple-500/50 hover:bg-purple-900/30 text-purple-400 hover:shadow-[0_0_15px_rgba(168,85,247,0.4)]"
            >
                🚀 {t('btn_export')}
            </button>
         </div>

         <div className="flex items-center gap-2 md:gap-4">
            <button onClick={() => setShowReportPreview(true)} className="flex items-center gap-2 bg-emerald-700 hover:bg-emerald-600 text-white px-4 py-2 rounded text-xs md:text-sm font-bold shadow-lg border border-emerald-500 transition-all">
               <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m2.25 0H5.625c-.621 0-1.18-.568-1.12-1.227v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z" />
               </svg>
               {t('btn_view_report')}
            </button>

            <div className="flex items-center gap-2 bg-slate-900 rounded-full p-1 border border-slate-700">
               <button onClick={() => setIsSavageMode(false)} className={`px-3 py-1 rounded-full text-[10px] font-bold ${!isSavageMode ? 'bg-emerald-600 text-white' : 'text-slate-500 hover:text-white'}`}>{t('tab_official')}</button>
               <button onClick={() => setIsSavageMode(true)} className={`px-3 py-1 rounded-full text-[10px] font-bold ${isSavageMode ? 'bg-red-600 text-white' : 'text-slate-500 hover:text-white'}`}>{t('tab_savage')}</button>
            </div>
         </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 md:gap-6">
        <div className="lg:col-span-7 flex flex-col gap-4">
           <div className="relative rounded-xl overflow-hidden border border-slate-700 bg-slate-900 group">
              <div className="absolute top-0 left-0 bg-black/60 text-white text-[10px] px-2 py-1 z-50 font-mono-sci rounded-br border-b border-r border-slate-700">
                  SOURCE_IMG: {result.risks.length} THREATS
              </div>
              <ImageAnnotator 
                imageSrc={imageSrc} 
                risks={currentRisks} 
                onRiskSelect={handleRiskChange} 
                selectedId={activeRisk.id}
                isEditing={isEditing}
                onRegionDrawn={handleRegionDrawn}
              />
              <div className="absolute bottom-4 right-4 flex items-center gap-3 bg-slate-900/90 backdrop-blur border border-slate-600 px-4 py-2 rounded-lg z-40 shadow-xl">
                 <div className="text-right">
                    <div className="text-[10px] text-slate-400 font-mono-sci uppercase">Hygiene Score</div>
                    <div className="text-xl font-bold text-white font-sci-fi">LEVEL {result.hygieneLevel}/5</div>
                 </div>
                 <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-lg border-2 ${result.hygieneLevel >= 4 ? 'border-emerald-500 text-emerald-400' : result.hygieneLevel >= 3 ? 'border-amber-500 text-amber-400' : 'border-red-500 text-red-500 bg-red-900/20'}`}>
                    {result.hygieneLevel}
                 </div>
              </div>
           </div>

           <div className="grid grid-cols-1 gap-4">
              {bioRisks.length > 0 && (
                <div className="bg-slate-900/50 border border-slate-800 rounded-lg p-3 md:p-4">
                   <h3 className="text-xs text-slate-500 font-mono-sci uppercase mb-3 flex items-center gap-2">
                      <span className="w-2 h-2 bg-amber-500 rounded-full"></span> {t('risk_vector')}
                   </h3>
                   <div className="space-y-2 max-h-[300px] overflow-y-auto custom-scrollbar">
                      {bioRisks.map((risk) => (
                         <RiskListItem key={risk.id} risk={risk} index={getRiskIndex(risk)} activeId={activeRisk.id} onClick={handleRiskChange} />
                      ))}
                   </div>
                </div>
              )}

              {safetyRisks.length > 0 && (
                <div className="bg-slate-900/50 border border-slate-800 rounded-lg p-3 md:p-4">
                   <h3 className="text-xs text-slate-500 font-mono-sci uppercase mb-3 flex items-center gap-2">
                      <span className="w-2 h-2 bg-indigo-500 rounded-full"></span> {t('risk_safety')}
                   </h3>
                   <div className="space-y-2 max-h-[300px] overflow-y-auto custom-scrollbar">
                      {safetyRisks.map((risk) => (
                         <RiskListItem key={risk.id} risk={risk} index={getRiskIndex(risk)} activeId={activeRisk.id} onClick={handleRiskChange} />
                      ))}
                   </div>
                </div>
              )}
           </div>
        </div>

        <div id="details-panel" className="lg:col-span-5 flex flex-col h-full gap-4">
            <HygieneVerdictCard hygieneLevel={result.hygieneLevel} isSavage={isSavageMode} />

            {result.groundingChunks && result.groundingChunks.length > 0 && (
                <div className="bg-blue-900/20 border border-blue-500/30 p-4 rounded-xl backdrop-blur-sm animate-fade-in-up">
                    <h3 className="text-xs text-blue-400 font-bold font-mono-sci uppercase mb-3 flex items-center gap-2">
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-4 h-4"><path fillRule="evenodd" d="M12 2.25c-5.385 0-9.75 4.365-9.75 9.75s4.365 9.75 9.75 9.75 9.75-4.365 9.75-9.75S17.385 2.25 12 2.25zm4.28 10.28a.75.75 0 000-1.06l-3-3a.75.75 0 10-1.06 1.06l1.72 1.72H8.25a.75.75 0 000 1.5h5.69l-1.72 1.72a.75.75 0 101.06 1.06l3-3z" clipRule="evenodd" /></svg>
                        {t('card_source')}
                    </h3>
                    <div className="flex flex-wrap gap-2">
                        {result.groundingChunks.map((chunk, i) => (
                             chunk.web?.uri ? (
                                <a 
                                  key={i} 
                                  href={chunk.web.uri} 
                                  target="_blank" 
                                  rel="noopener noreferrer"
                                  className="text-[10px] bg-blue-950/50 hover:bg-blue-800 text-blue-300 border border-blue-800 rounded-full px-3 py-1 truncate max-w-[200px] transition-colors flex items-center gap-1"
                                >
                                    <span className="w-1.5 h-1.5 bg-blue-500 rounded-full shrink-0"></span>
                                    {chunk.web.title || "Source Link"}
                                </a>
