        "disease": "string (Associated Disease/Injury in ${targetLang})",
        "microbiology": "string (Bacteria/Virus names or Physical Risk Type)",
        "statistics": "string (Real world death/case/accident stats in ${targetLang})",
        "description": "string (Full technical analysis in ${targetLang})",
        "solution": "string (Professional solution in ${targetLang})",
        "box_2d": { "ymin": number, "xmin": number, "ymax": number, "xmax": number } (Scale 0-1000),
        "citations": [ { "source": "string", "title": "string", "url": "string" } ]
      }
    ],
    "generalAdvice": "string (Executive summary in ${targetLang})",
    "savageCommentary": "string (Sarcastic/Funny comment in ${targetLang})",
    "hygieneLevel": number (1-5)
  }
  `;

  let lastError: any = null;

  for (const modelId of modelsToTry) {
     try {
         console.log(`🤖 Attempting analysis with model: ${modelId}`);

         const tools = (mode === 'DETAILED') ? [{ googleSearch: {} }] : undefined;
         const maxRetries = 2; // Keep retries low to allow quick fallback

         const response = await retryWithBackoff(async () => {
              const ai = getAIClient();

              // CRITICAL: Disable 'thinkingConfig' for 3.0 Pro if it causes issues, allow default behavior
              const config: any = {
                 tools: tools,
                 // DO NOT SET thinkingConfig manually for 3.0 Pro to avoid conflict
              };

              return await ai.models.generateContent({
                model: modelId,
                contents: {
                    parts: [
                        { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, // Use optimized image
                        { text: `Visual forensic analysis for Vector Control, Hygiene, AND Occupational Safety & Health (OSH).

                                STRICT SCORING RUBRIC (Follow this laws, do not be lenient):
                                - SCORE 1 (CRITICAL): Presence of VECTORS (Rats, Flies, Mosquitoes, Roaches), Sewage/Mold, OR IMMEDIATE SAFETY DANGER (Exposed wiring, Fire Hazard, Chemical Leak, Collapse Risk, Blocked Emergency Exits).
                                - SCORE 2 (BAD): Visible stains, unorganized trash, food waste, OR OSH HAZARDS (Slippery floors, Trip hazards/cables, Blocked walkways, Sharp objects, Unsafe stacking, PPE violations).
                                - SCORE 3 (AVERAGE): General clutter, dusty, messy but no immediate bio-hazard or critical safety danger.
                                - SCORE 4 (GOOD): Tidy, organized, but minor imperfections.
                                - SCORE 5 (EXCELLENT): Hospital/Lab grade sterile and fully compliant with OSH standards.

                                INSTRUCTIONS:
                                1. Scan for VECTORS & HYGIENE: Stains, dust, corners, trash, pests.
                                2. Scan for OSH SAFETY HAZARDS:
                                   - Physical: Slips/Trips (wet floor, cables), blocked exits, uneven surfaces.
                                   - Electrical: Exposed wires, overloaded sockets, damaged equipment.
                                   - Chemical: Unlabeled bottles, improper storage, spills.
                                   - Structural: Cracks, unstable shelving, ceiling damage.
                                   - Ergonomic/Fire: Poorly stacked items, fire risks.
                                3. If you see trash OR trip hazards, MAX SCORE is 2.
                                4. If you see insects/rats OR exposed live wires/fire risks, MAX SCORE is 1.
                                5. Translate output to ${targetLang}.
                                6. LABEL MUST BE HUMAN READABLE. No 'risk_1'. Use 'Rats', 'Exposed Wire', etc.
                                7. Output valid JSON:
                                ${schemaDescription}

                                DO NOT use Markdown blocks. Raw JSON.` }
                    ]
                },
                config: config
            });
         }, maxRetries, 1000); 

         let text = response.text;
         if (!text) throw new Error("AI returned empty response.");

         // Robust JSON Extraction (Find the LAST valid JSON object)
         const jsonMatch = text.match(/\{[\s\S]*\}/);
         if (jsonMatch) {
             text = jsonMatch[0];
         } else {
             text = text.replace(/```json/g, '').replace(/```/g, '').trim();
         }

         let parsedResult: AnalysisResponse;
         try {
             parsedResult = JSON.parse(text) as AnalysisResponse;
         } catch (e) {
             console.error("JSON Parse Error", text);
             throw new Error("Gagal memproses format data AI.");
         }

         const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
         if (groundingChunks) parsedResult.groundingChunks = groundingChunks;

         return parsedResult;

     } catch (error: any) {
         console.warn(`⚠️ Model ${modelId} failed:`, error.message);
         lastError = error;
         // Loop continues to next model...
     }
  }

  throw lastError || new Error("Semua model AI sibuk. Sila cuba sebentar lagi.");
};

/**
 * Manual Region Analysis
 */
export const analyzeManualRegion = async (base64Image: string, mimeType: string, box: BoundingBox, userContext: string, language: string = 'ms'): Promise<RiskDetection> => {

    const langMap: Record<string, string> = {
      'ms': 'Bahasa Melayu',
      'en': 'English',
      'zh': 'Chinese (Simplified)',
      'ta': 'Tamil'
    };
    const targetLang = langMap[language] || 'Bahasa Melayu';

    // PERFORMANCE FIX: Compress the image for Manual Scan too.
    const optimizedImage = await compressImage(base64Image);

    // Explicitly define coordinate system for Gemini
    const prompt = `
    TASK: Region of Interest (ROI) Forensic Analysis.

    STRICT INSTRUCTION:
    1. I have selected a specific region in this image via a bounding box.
    2. BOUNDING BOX COORDINATES: Y[${box.ymin} - ${box.ymax}], X[${box.xmin} - ${box.xmax}] (on a 0-1000 scale).
    3. IGNORE EVERYTHING OUTSIDE THIS BOX.
    4. Focus ONLY on the object/stain/hazard inside these coordinates.

    User Observation/Hint: "${userContext}"

    Analyze the risk for Hygiene, Vectors, OR Occupational Safety (OSH) within this box.
    Target Language: ${targetLang}.
    Label must be readable (e.g. "Lipas", not "risk_id").
    Return JSON matching RiskDetection format.
    `;

    const schema = {
        type: Type.OBJECT,
        properties: {
            id: { type: Type.STRING },
            category: { type: Type.STRING, enum: ["VECTOR", "HYGIENE", "SAFETY"] },
            label: { type: Type.STRING },
            agent: { type: Type.STRING },
            disease: { type: Type.STRING },
            microbiology: { type: Type.STRING },
            statistics: { type: Type.STRING },
            description: { type: Type.STRING },
            solution: { type: Type.STRING },
            box_2d: {
                type: Type.OBJECT,
                properties: {
                  ymin: { type: Type.NUMBER },
                  xmin: { type: Type.NUMBER },
                  ymax: { type: Type.NUMBER },
                  xmax: { type: Type.NUMBER }
                }
            },
            citations: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { id: {type:Type.NUMBER}, source: {type:Type.STRING}, title:{type:Type.STRING}, url:{type:Type.STRING} } } }
        }
    };

    const response = await retryWithBackoff(async () => {
        const ai = getAIClient();
        return await ai.models.generateContent({
            // Keeping Gemini 3.0 Pro as requested, but with smaller image payload
            model: "gemini-3-pro-preview", 
            contents: {
                parts: [
                    { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } },
                    { text: prompt }
                ]
            },
            config: {
                responseMimeType: "application/json",
                responseSchema: schema,
            }
        });
    });

    const text = response.text;
    const result = JSON.parse(text!);
    result.id = `manual-${Date.now()}`;
    result.box_2d = box; 
    return result;
};

