// Module-level variable to track current key index
// RANDOMIZE START: Don't always start at 0 to avoid hammering the first key
let currentKeyIndex = -1; 

// Track keys that recently failed (timestamp of failure)
const failedKeys: Record<string, number> = {}; 
const KEY_COOLDOWN_MS = 60000 * 5; // 5 Minutes cooldown for exhausted keys

// Helper to get ALL available keys from LOCAL STORAGE ONLY
export const getKeyPool = (): string[] => {
  let keys: string[] = [];

  // 1. Get from Multi-Key Storage (User's private local storage)
  const savedKeys = localStorage.getItem('user_gemini_api_keys');
  if (savedKeys) {
    try {
        const parsed = JSON.parse(savedKeys);
        if (Array.isArray(parsed)) keys = [...keys, ...parsed];
    } catch(e) {}
  }

  // 2. Fallback to Single Key Storage (Old format)
  const singleKey = localStorage.getItem('user_gemini_api_key');
  if (singleKey && !keys.includes(singleKey)) {
      keys.push(singleKey);
  }

  // 3. Fallback to Env Var (Local Dev only)
  const envKey = (typeof process !== 'undefined' && process.env) ? process.env.API_KEY : undefined;
  if (envKey && !keys.includes(envKey)) {
      keys.push(envKey);
  }

  // Clean keys (remove empty strings or too short keys)
  return keys.map(k => k.trim()).filter(k => k && k.length > 10);
};

// Reset index when user updates settings
export const resetKeyIndex = () => {
    // Pick a random start index again when keys change
    const pool = getKeyPool();
    if (pool.length > 0) {
        currentKeyIndex = Math.floor(Math.random() * pool.length);
    } else {
        currentKeyIndex = 0;
    }
    // Clear failed keys cache
    for (const k in failedKeys) delete failedKeys[k];
};

// Get current key status for UI
export const getKeyStatus = () => {
    const pool = getKeyPool();
    // Initialize index if not set
    if (currentKeyIndex === -1 && pool.length > 0) {
        currentKeyIndex = Math.floor(Math.random() * pool.length);
    }

    if (pool.length === 0) return { active: false, label: 'NO KEY' };

    // Count how many keys are actually healthy (not in failedKeys)
    const now = Date.now();
    const healthyCount = pool.filter(k => !failedKeys[k] || (now - failedKeys[k] > KEY_COOLDOWN_MS)).length;

    return { 
        active: true, 
        label: `KEY [${currentKeyIndex + 1}/${pool.length}]`, 
        count: pool.length,
        healthy: healthyCount
    };
};

// Helper function to get the AI client securely using Rotation and Health Check
const getAIClient = () => {
  const keys = getKeyPool();
  if (keys.length === 0) {
    throw new Error("Sila masukkan API Key di dalam Tetapan (Settings).");
  }

  // Initialize random start if first run
  if (currentKeyIndex === -1) {
      currentKeyIndex = Math.floor(Math.random() * keys.length);
  }

  // Ensure index is valid
  if (currentKeyIndex >= keys.length) currentKeyIndex = 0;

  // Check if current key is in cooldown
  const now = Date.now();
  let attempts = 0;

  // Try to find a healthy key by rotating until we find one not in failedKeys
  while (failedKeys[keys[currentKeyIndex]] && (now - failedKeys[keys[currentKeyIndex]] < KEY_COOLDOWN_MS)) {
      // If key is bad, move to next
      currentKeyIndex = (currentKeyIndex + 1) % keys.length;
      attempts++;

      // If we've checked all keys and they are ALL bad
      if (attempts >= keys.length) {
          console.warn("⚠️ All keys are in cooldown. Forcing usage of current key and hoping for the best.");
          break;
      }
  }

  const activeKey = keys[currentKeyIndex];
  return new GoogleGenAI({ apiKey: activeKey });
};

// Rotate to next key
const rotateKey = () => {
    const keys = getKeyPool();
    // Mark current key as failed
    const currentKey = keys[currentKeyIndex];
    if (currentKey) {
        console.warn(`❌ Marking Key ${currentKeyIndex + 1} as FAILED/EXHAUSTED.`);
        failedKeys[currentKey] = Date.now();
    }

    if (keys.length > 1) {
        const oldIndex = currentKeyIndex;
        // Find next key that isn't failed (simple loop)
        let foundNew = false;
        for(let i=1; i<keys.length; i++) {
            const nextIdx = (oldIndex + i) % keys.length;
            if (!failedKeys[keys[nextIdx]]) {
                currentKeyIndex = nextIdx;
                foundNew = true;
                break;
            }
        }

        // If all marked failed, just go to next one anyway
        if (!foundNew) {
            currentKeyIndex = (oldIndex + 1) % keys.length;
        }

        console.warn(`🔄 Rotating Key: ${oldIndex + 1} -> ${currentKeyIndex + 1}`);
        return true; // Rotation happened
    }
    return false; // No other keys to rotate to
};

// PERFORMANCE FIX: Reduce Image Size Client-Side before sending to Gemini
// Sending 12MP images to Gemini Pro causes massive latency/timeouts.
const compressImage = (base64Str: string, maxWidth = 1024, quality = 0.7): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = `data:image/jpeg;base64,${base64Str}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let width = img.width;
            let height = img.height;

            if (width > maxWidth) {
                height = Math.round((height * maxWidth) / width);
                width = maxWidth;
            }

            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);

            // Get compressed base64 (remove prefix for API)
            const newDataUrl = canvas.toDataURL('image/jpeg', quality);
            resolve(newDataUrl.split(',')[1]);
        };
        img.onerror = () => {
            // Fallback: return original if compression fails
            resolve(base64Str); 
        };
    });
};

// Retry utility with Key Rotation and Backoff
const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> => {
    try {
        return await fn();
    } catch (error: any) {
        const msg = error.message || "";
        const isQuotaError = msg.includes("429") || msg.includes("503") || msg.includes("quota") || msg.includes("exhausted") || msg.includes("resource");

        // Check specifically for the "limit: 20" image generation error
        const isImageQuotaError = msg.includes("limit: 20") || msg.includes("generate_content_free_tier_requests");

        if (isQuotaError || isImageQuotaError) {
            console.warn(`⚠️ Quota Error on Key ${currentKeyIndex + 1}.`);

            // STRATEGY 1: Try to rotate key FIRST (If user has multiple keys)
            const rotated = rotateKey();

            if (rotated) {
                // IMPORTANT: If we rotated, do NOT wait. Try immediately.
                if (retries > 0) {
                     console.log("🚀 Switching to new key immediately...");
                     await new Promise(resolve => setTimeout(resolve, 100)); 
                     return retryWithBackoff(fn, retries, delay); 
                }
            }

            // STRATEGY 2: If rotation failed, wait
            if (retries > 0) {
                console.warn(`🛑 Rate limit hit. Retrying in ${delay/1000}s...`);
                await new Promise(resolve => setTimeout(resolve, delay));
                return retryWithBackoff(fn, retries - 1, delay * 1.5); 
            }
        }
        throw error;
    }
};

/**
 * Smart Analysis Function with Auto-Fallback
 */
export const analyzeLandscape = async (base64Image: string, mimeType: string, mode: 'FAST' | 'DETAILED' = 'DETAILED', language: string = 'ms'): Promise<AnalysisResponse> => {
  const langMap: Record<string, string> = {
    'ms': 'Bahasa Melayu',
    'en': 'English',
    'zh': 'Chinese (Simplified)',
    'ta': 'Tamil'
  };
  const targetLang = langMap[language] || 'Bahasa Melayu';

  // PERFORMANCE: Compress image first
  const optimizedImage = await compressImage(base64Image);

  // FALLBACK STRATEGY: 
  // 1. Gemini 3.0 Pro Preview (Smarter, but unstable on free tier)
  // 2. Gemini 2.0 Flash (Fastest, very stable, fallback)
  let modelsToTry = ["gemini-3-pro-preview", "gemini-2.0-flash"];

  const schemaDescription = `
  {
    "risks": [
      {
        "id": "string (unique id)",
        "category": "VECTOR | HYGIENE | SAFETY",
        "label": "string (Short Title in ${targetLang}. DO NOT use IDs like 'risk_1'. Use real names e.g. 'Tikus', 'Sampah', 'Wayar Terdedah')",
        "agent": "string (Scientific Name or Hazard Source)",
        "disease": "string (Associated Disease/Injury in ${targetLang})",
        "microbiology": "string (Bacteria/Virus names or Physical Risk Type)",
        "statistics": "string (Real world death/case/accident stats in ${targetLang})",
        "description": "string (Full technical analysis in ${targetLang})",
        "solution": "string (Professional solution in ${targetLang})",
        "box_2d": { "ymin": number, "xmin": number, "ymax": number, "xmax": number } (Scale 0-1000),
        "citations": [ { "source": "string", "title": "string", "url": "string" } ]
      }
    ],
    "generalAdvice": "string (Executive summary in ${targetLang})",
    "savageCommentary": "string (Sarcastic/Funny comment in ${targetLang})",
    "hygieneLevel": number (1-5),
    "safetyLevel": number (1-5)
  }
  `;

  let lastError: any = null;

  for (const modelId of modelsToTry) {
     try {
         console.log(`🤖 Attempting analysis with model: ${modelId}`);

         const tools = (mode === 'DETAILED') ? [{ googleSearch: {} }] : undefined;
         const maxRetries = 2; // Keep retries low to allow quick fallback

         const response = await retryWithBackoff(async () => {
              const ai = getAIClient();

              const config: any = {
                 tools: tools,
              };

              return await ai.models.generateContent({
                model: modelId,
                contents: {
                    parts: [
                        { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, // Use optimized image
                        { text: `Visual forensic analysis for Vector Control, Hygiene, AND Occupational Safety & Health (OSH).

                                STRICT SCORING RUBRIC (Follow this laws, do not be lenient):
                                - SCORE 1 (CRITICAL): Presence of VECTORS (Rats, Flies, Mosquitoes, Roaches), Sewage/Mold, OR IMMEDIATE SAFETY DANGER (Exposed wiring, Fire Hazard, Chemical Leak, Collapse Risk, Blocked Emergency Exits).
                                - SCORE 2 (BAD): Visible stains, unorganized trash, food waste, OR OSH HAZARDS (Slippery floors, Trip hazards/cables, Blocked walkways, Sharp objects, Unsafe stacking, PPE violations).
                                - SCORE 3 (AVERAGE): General clutter, dusty, messy but no immediate bio-hazard or critical safety danger.
                                - SCORE 4 (GOOD): Tidy, organized, but minor imperfections.
                                - SCORE 5 (EXCELLENT): Hospital/Lab grade sterile and fully compliant with OSH standards.

                                INSTRUCTIONS:
                                1. Scan for VECTORS & HYGIENE: Stains, dust, corners, trash, pests. Calculate 'hygieneLevel'.
                                2. Scan for OSH SAFETY HAZARDS:
                                   - Physical: Slips/Trips (wet floor, cables), blocked exits, uneven surfaces.
                                   - Electrical: Exposed wires, overloaded sockets, damaged equipment.
                                   - Chemical: Unlabeled bottles, improper storage, spills.
                                   - Structural: Cracks, unstable shelving, ceiling damage.
                                   - Ergonomic/Fire: Poorly stacked items, fire risks.
                                   Calculate 'safetyLevel'.
                                3. If you see trash OR trip hazards, MAX SCORE is 2.
                                4. If you see insects/rats OR exposed live wires/fire risks, MAX SCORE is 1.
                                5. Translate output to ${targetLang}.
                                6. LABEL MUST BE HUMAN READABLE. No 'risk_1'. Use 'Rats', 'Exposed Wire', etc.
                                7. Output valid JSON:
                                ${schemaDescription}

                                DO NOT use Markdown blocks. Raw JSON.` }
                    ]
                },
                config: config
            });
         }, maxRetries, 1000); 

         let text = response.text;
         if (!text) throw new Error("AI returned empty response.");

         // Robust JSON Extraction (Find the LAST valid JSON object)
         const jsonMatch = text.match(/\{[\s\S]*\}/);
         if (jsonMatch) {
             text = jsonMatch[0];
         } else {
             text = text.replace(/```json/g, '').replace(/```/g, '').trim();
         }

         let parsedResult: AnalysisResponse;
         try {
             parsedResult = JSON.parse(text) as AnalysisResponse;
         } catch (e) {
             console.error("JSON Parse Error", text);
             throw new Error("Gagal memproses format data AI.");
         }

         const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
         if (groundingChunks) parsedResult.groundingChunks = groundingChunks;

         // Ensure safetyLevel exists (for backward compatibility if model misses it)
         if (!parsedResult.safetyLevel) {
             parsedResult.safetyLevel = parsedResult.hygieneLevel;
         }

         return parsedResult;

     } catch (error: any) {
         console.warn(`⚠️ Model ${modelId} failed:`, error.message);
         lastError = error;
         // Loop continues to next model...
     }
  }

  throw lastError || new Error("Semua model AI sibuk. Sila cuba sebentar lagi.");
};

