    const optimizedImage = await compressImage(base64Image);

    // GET DIMENSIONS AND ASPECT RATIO FOR PROPER GENERATION
    const dimensions = await getImageDimensions(base64Image);
    console.log("📐 Detected Image Dimensions:", dimensions);

    // STEP 1: Describe the room layout using Gemini 2.5 Flash (Text Model)
    console.log("🎨 Step 1: Analyzing room geometry with Gemini 2.5...");
    let genPrompt = "";
    let roomDescription = "A standard room layout.";

    try {
        const layoutPrompt = `
        Analyze this image. Describe the room's perspective, architectural layout, window placement, and major furniture geometry in detail.
        Mention if there are people and where they are standing.
        Ignore the dirt, trash, and mess. Focus ONLY on the structure and humans.
        `;

        const descResponse = await retryWithBackoff(async () => {
             const ai = getAIClient();
             return await ai.models.generateContent({
                model: "gemini-2.5-flash",
                contents: {
                    parts: [
                        { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } },
