        if (config.mode === 'RECONSTRUCT') {
            genPrompt += "Style: Modern futuristic sterile white hospital laboratory, blue LED accents, bright daylight. ";
        } else {
            // CLEAN mode
            genPrompt += "Style: Extremely clean version of the same room. Tidy, organized, freshly polished floors. ";
        }

        if (config.humans === 'REMOVE') {
            genPrompt += "No people, empty room. ";
        } else {
            genPrompt += "Keep the people in the exact same positions but wearing clean clothes or safety gear. ";
        }

        if (config.furniture === 'REPLACE') {
            genPrompt += "Replace old furniture with modern white equipment. ";
        } else {
            genPrompt += "Keep existing furniture but make it look new and clean. ";
        }

        genPrompt += "Unreal Engine 5 render, 8k resolution, high key lighting, crisp details, no trash, no dirt.";

    } catch (e) {
        console.warn("Step 1 Analysis Failed, using generic prompt");
        genPrompt = "A clean, modern version of this room, sterile environment, 8k resolution, bright cinematic lighting, same layout.";
    }

    // Define function for external generator (Flux via Pollinations)
    const callExternalGenerator = async () => {
        console.log("✅ Using External Engine: Pollinations.ai (Flux)");
        try {
            const seed = Math.floor(Math.random() * 1000000);
            const simplePrompt = `modern clean room, ${genPrompt.substring(0, 150)}, bright lighting, 8k, photorealistic`;
            // Calculate proportional dimensions maxing at 1280
            let finalW = dimensions.width;
            let finalH = dimensions.height;
            const maxDim = 1280;
            if (finalW > maxDim || finalH > maxDim) {
                if (finalW > finalH) {
                    finalH = Math.round(finalH * (maxDim / finalW));
                    finalW = maxDim;
                } else {
                    finalW = Math.round(finalW * (maxDim / finalH));
                    finalH = maxDim;
                }
            }

            const fallbackUrl = `https://image.pollinations.ai/prompt/${encodeURIComponent(simplePrompt)}?width=${finalW}&height=${finalH}&seed=${seed}&nolog=true&model=flux`;
            await new Promise(r => setTimeout(r, 2500)); // Artificial delay
            return fallbackUrl;
        } catch (error) {
            throw new Error("External Generator Failed.");
        }
    };

    // DECISION TREE BASED ON CONFIG
    if (config.engine === 'EXTERNAL') {
        return await callExternalGenerator();
    }

    // NEW: GEMINI 2.5 FLASH IMAGE (FREE TIER)
    if (config.engine === 'GEMINI_FLASH') {
         console.log("🎨 Using Gemini 2.5 Flash Image...");
         try {
             const ai = getAIClient();
             const response = await retryWithBackoff(async () => {
                 return await ai.models.generateContent({
                     model: 'gemini-2.5-flash-image', // Explicitly use the image model
                     contents: {
                         // Add Aspect Ratio to prompt for Flash model guidance
                         parts: [{ text: `Generate an image: ${genPrompt}. Aspect Ratio: ${dimensions.ratioStr}` }]
                     },
                     // Note: 2.5-flash-image doesn't use 'generateImages' or standard imageConfig yet in SDK
                     // It typically returns inlineData in the response candidates.
                 });
             });

             // Extract image from response parts
             const parts = response.candidates?.[0]?.content?.parts;
             if (parts) {
                 for (const part of parts) {
                     if (part.inlineData) {
                         return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
                     }
                 }
             }
             throw new Error("Gemini Flash did not return valid image data.");

         } catch (e: any) {
             console.warn(`⚠️ Gemini Flash Image Failed: ${e.message}. Falling back to External.`);
             if (config.engine === 'GEMINI_FLASH') {
                 // Fallback to External if specifically requested but failed
                 return await callExternalGenerator();
             }
             throw e;
         }
    }

    // DEFAULT OR GOOGLE MODE (IMAGEN 3)
    console.log("🎨 Step 2: Attempting Google Imagen (Billing Required)...");

    try {
        const maxRetries = 2; 

        // If user selected AUTO, try Google first, then catch and fallback to External
        // If user selected GOOGLE, try Google, catch and throw error (no fallback)

        const imageResponse = await retryWithBackoff(async () => {
             const ai = getAIClient();
             return await ai.models.generateImages({
                // Using Imagen 3.0 Generate (Standard stable model)
                model: "imagen-3.0-generate-001", 
                prompt: genPrompt,
                config: {
                    numberOfImages: 1,
                    aspectRatio: dimensions.ratioStr // DYNAMIC RATIO
                }
            });
        }, maxRetries, 1000);

        const generatedImage = imageResponse.generatedImages?.[0]?.image?.imageBytes;
        if (!generatedImage) throw new Error("No image data received from Imagen.");

        return `data:image/png;base64,${generatedImage}`;

    } catch (e: any) {
        // Handle Failure
        if (config.engine === 'GOOGLE') {
             // If user explicitly wanted Google but it failed, throw error
             throw new Error(`Google Imagen Failed: ${e.message}. Try changing Engine to 'External'.`);
        } else {
             // AUTO mode: Fallback to External Flux if Google fails
             console.warn("⚠️ Google Imagen Failed (Billing Required/Rate Limit). Falling back to External Engine (Flux)...");
             return await callExternalGenerator();
        }
    }
};

