export interface GroundingChunk {
  web?: {
    uri?: string;
    title?: string;
  };
}

// Coordinate structure returned by Gemini (usually 0-1000 scale)
export interface BoundingBox {
  ymin: number;
  xmin: number;
  ymax: number;
  xmax: number;
}

export type RiskCategory = 'VECTOR' | 'HYGIENE' | 'SAFETY';

export interface Citation {
  id: number;
  source: string; // e.g., "CDC", "WHO", "ResearchGate"
  title: string;
  url: string;
}

export interface RiskDetection {
  id: string;
  category: RiskCategory; 
  label: string; 
  agent: string; 
  disease: string; 
  microbiology: string; // New: Specific germs (Bacteria/Virus names)
  statistics: string; // New: Annual death/case stats
  description: string; // Text with (1), (2) markers
  solution: string; 
  box_2d: BoundingBox;
  citations: Citation[]; // List of references
  microscopeVideoUrl?: string; // YouTube link
}

export interface AnalysisResponse {
  risks: RiskDetection[];
  generalAdvice: string; // Official Professional Advice
  savageCommentary?: string; // The "Nightmare Chef" Persona Advice
  groundingChunks?: GroundingChunk[];
  hygieneLevel: number; // 1 (Worst) to 5 (Best) - Focus on VECTORS/CLEANLINESS
  safetyLevel: number; // 1 (Worst) to 5 (Best) - Focus on OSH/HAZARDS
  timestamp?: number; // Added for report generation
}

// NEW: Session interface for multi-image support
export interface AnalysisSession {
  id: string;
  imageSrc: string; // Base64 for preview
  mimeType: string;
  fileName: string;
  status: 'PENDING' | 'ANALYZING' | 'SUCCESS' | 'ERROR';
  result?: AnalysisResponse;
  error?: string;
  simulationImage?: string; // PERSISTENCE: Store generated clean image here
}

export enum AppState {
  IDLE = 'IDLE',
  ANALYZING = 'ANALYZING', // Keep for backward compatibility/Live mode
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

