const App: React.FC = () => {
  const [sessions, setSessions] = useState<AnalysisSession[]>([]);
  const [activeSessionId, setActiveSessionId] = useState<string | null>(null);
  const [isLiveMode, setIsLiveMode] = useState(false);
  const [showAbout, setShowAbout] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [isGalleryExpanded, setIsGalleryExpanded] = useState(true);

  const { language, t } = useLanguage();

  const readFile = (file: File): Promise<{ base64: string, mimeType: string, preview: string }> => {
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const result = e.target?.result as string;
        const base64 = result.split(',')[1];
        const mimeType = result.split(';')[0].split(':')[1];
        resolve({ base64, mimeType, preview: result });
      };
      reader.readAsDataURL(file);
    });
  };

  const handleFilesSelected = async (files: File[]) => {
    const newSessions: AnalysisSession[] = [];
    for (const file of files) {
       const { base64, mimeType, preview } = await readFile(file);
       newSessions.push({
         id: `session-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
         fileName: file.name,
         imageSrc: preview,
         mimeType: mimeType,
         status: 'PENDING'
       });
    }
    setSessions(prev => [...prev, ...newSessions]);
    if (!activeSessionId && newSessions.length > 0) {
        setActiveSessionId(newSessions[0].id);
    }
    setIsGalleryExpanded(true);
  };

  useEffect(() => {
    const processNext = async () => {
        const analyzingCount = sessions.filter(s => s.status === 'ANALYZING').length;
        if (analyzingCount < MAX_CONCURRENT_ANALYSIS) {
            const pendingSession = sessions.find(s => s.status === 'PENDING');
            if (pendingSession) {
                // INCREASED DELAY: 5 seconds delay between requests to avoid rate limits
                await new Promise(resolve => setTimeout(resolve, 5000));
                triggerAnalysis(pendingSession.id);
            }
        }
    };
    processNext();
  }, [sessions]);

  const triggerAnalysis = async (sessionId: string) => {
      setSessions(prev => prev.map(s => s.id === sessionId ? { ...s, status: 'ANALYZING' } : s));

      const session = sessions.find(s => s.id === sessionId);
      if (!session) return;

      try {
          const base64Data = session.imageSrc.split(',')[1];
          // Pass current language to the service
          const result = await analyzeLandscape(base64Data, session.mimeType, 'FAST', language);

          setSessions(prev => prev.map(s => s.id === sessionId ? { 
              ...s, 
              status: 'SUCCESS', 
              result: result 
          } : s));

      } catch (error: any) {
          console.error(`Error processing ${sessionId}:`, error);
          setSessions(prev => prev.map(s => s.id === sessionId ? { 
              ...s, 
              status: 'ERROR', 
              error: error.message || "Gagal menganalisis." 
          } : s));
      }
  };

  // PERSISTENCE HANDLER: Save the simulation image to the session object
  const handleSimulationSave = (sessionId: string, image: string) => {
      setSessions(prev => prev.map(s => s.id === sessionId ? { ...s, simulationImage: image } : s));
  };

  const handleLiveAnalysisCapture = (capturedResult: AnalysisResponse, capturedImageSrc: string) => {
    setIsLiveMode(false);
    const newSession: AnalysisSession = {
        id: `live-${Date.now()}`,
        fileName: 'AR_CAPTURE.jpg',
        imageSrc: capturedImageSrc,
        mimeType: 'image/jpeg',
        status: 'SUCCESS',
        result: capturedResult
    };
    setSessions(prev => [newSession, ...prev]);
    setActiveSessionId(newSession.id);
    setIsGalleryExpanded(true);
  };

  const resetApp = () => {
    setSessions([]);
    setActiveSessionId(null);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleGoHome = () => {
    setIsLiveMode(false);
    setActiveSessionId(null);
    setIsGalleryExpanded(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const getActiveSession = () => sessions.find(s => s.id === activeSessionId);
  const completedCount = sessions.filter(s => s.status === 'SUCCESS').length;

  return (
    <div className="min-h-screen text-slate-200 relative selection:bg-emerald-500 selection:text-black font-sans flex flex-col overflow-x-hidden">
      <BioBackground />
      <AboutSystem isOpen={showAbout} onClose={() => setShowAbout(false)} />
      <SettingsModal isOpen={showSettings} onClose={() => setShowSettings(false)} />

      {isLiveMode && (
        <LiveCameraScanner onCaptureAnalysis={handleLiveAnalysisCapture} onClose={() => setIsLiveMode(false)} />
      )}

      <Header onOpenAbout={() => setShowAbout(true)} onOpenSettings={() => setShowSettings(true)} onGoHome={handleGoHome} />

