import React, { useState, useEffect } from 'react';
import { useLanguage } from '../contexts/LanguageContext';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose }) => {
  const [apiKey, setApiKey] = useState('');
  const [isSaved, setIsSaved] = useState(false);
  const { t } = useLanguage();

  useEffect(() => {
    // Get single key
    const oldKey = localStorage.getItem('user_gemini_api_key');
    if (oldKey) setApiKey(oldKey);
  }, []);

  const handleSave = () => {
    const cleanKey = apiKey.trim();

    if (cleanKey.length > 20) {
      localStorage.setItem('user_gemini_api_key', cleanKey);

      // Clear legacy multi-keys if they exist to avoid confusion
      localStorage.removeItem('user_gemini_api_keys');

      setIsSaved(true);
      setTimeout(() => {
        setIsSaved(false);
        onClose();
      }, 1500);
    } else {
        alert("Sila masukkan API Key yang sah.");
    }
  };

  const handleClear = () => {
    const confirmDelete = window.confirm("Are you sure you want to remove the API Key?");
    if (confirmDelete) {
        localStorage.removeItem('user_gemini_api_key');
        localStorage.removeItem('user_gemini_api_keys'); // Cleanup legacy
        setApiKey('');
        onClose();
    }
  };

  if (!isOpen) return null;

