interface AnalysisResultsProps {
  result: AnalysisResponse;
  imageSrc: string;
  savedSimulationImage?: string; // New prop for persistence
  onSaveSimulation: (image: string) => void; // New callback prop
}

export const AnalysisResults: React.FC<AnalysisResultsProps> = ({ result, imageSrc, savedSimulationImage, onSaveSimulation }) => {
  const [activeRisk, setActiveRisk] = useState<RiskDetection | null>(null);
  const [currentRisks, setCurrentRisks] = useState<RiskDetection[]>(result.risks);
  const [isSavageMode, setIsSavageMode] = useState(false);
  const [showReportPreview, setShowReportPreview] = useState(false);
  const [chatOpen, setChatOpen] = useState(false);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [userQuestion, setUserQuestion] = useState("");
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [manualBox, setManualBox] = useState<BoundingBox | null>(null);
  const [showManualModal, setShowManualModal] = useState(false);
  const [manualContext, setManualContext] = useState("");
  const [isProcessingManual, setIsProcessingManual] = useState(false);
  const [isCleaning, setIsCleaning] = useState(false);
  const [cleanImage, setCleanImage] = useState<string | null>(savedSimulationImage || null);
  const [showCleanModal, setShowCleanModal] = useState(false);
  const [showConfigModal, setShowConfigModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);

  const { language, t } = useLanguage();

  // EFFECT: Update local cleanImage if the savedSimulationImage prop changes (e.g. switching tabs)
  useEffect(() => {
      setCleanImage(savedSimulationImage || null);
  }, [savedSimulationImage]);

  useEffect(() => {
    if (currentRisks && currentRisks.length > 0) {
      if (!activeRisk) setActiveRisk(currentRisks[0]);
    }
  }, [currentRisks]);

  const handleRiskChange = (risk: RiskDetection) => {
    setActiveRisk(risk);
    setChatOpen(false);
    setChatMessages([]);
    if (window.innerWidth < 1024) {
      setTimeout(() => {
        document.getElementById('details-panel')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 100);
    }
  }

  const bioRisks = currentRisks.filter(r => r.category === 'VECTOR' || r.category === 'HYGIENE');
  const safetyRisks = currentRisks.filter(r => r.category === 'SAFETY');

  // Helper to find index across full array for display
  const getRiskIndex = (risk: RiskDetection) => {
     return currentRisks.findIndex(r => r.id === risk.id) + 1;
  };

  const handleRegionDrawn = (box: BoundingBox) => {
    setManualBox(box);
    setShowManualModal(true);
    setIsEditing(false);
  };

  const submitManualAnalysis = async () => {
    if (!manualBox || !manualContext) return;
    setIsProcessingManual(true);
    try {
        const cleanBase64 = imageSrc.split(',')[1] || imageSrc;
        const mimeType = imageSrc.split(';')[0].split(':')[1] || 'image/jpeg';

        // The service now uses Gemini 3.0 Pro with a strict bounding box prompt
        const newRisk = await analyzeManualRegion(cleanBase64, mimeType, manualBox, manualContext, language);

        const updatedRisks = [newRisk, ...currentRisks];
        setCurrentRisks(updatedRisks);
        setActiveRisk(newRisk);
        setShowManualModal(false);
        setManualContext("");
        setManualBox(null);
    } catch (e) {
        alert("Gagal memproses kawasan manual. Sila cuba lagi.");
        console.error(e);
    } finally {
        setIsProcessingManual(false);
    }
  };

  const cancelManualMode = () => {
    setIsEditing(false);
    setShowManualModal(false);
    setManualBox(null);
    setManualContext("");
  };

  const handleOpenSimulation = () => {
      if (cleanImage) {
          setShowCleanModal(true);
      } else {
          setShowConfigModal(true);
      }
  };

  const startSimulation = async (config: SimulationConfig) => {
      setShowConfigModal(false);
      setIsCleaning(true);
      try {
          const base64Data = imageSrc.split(',')[1];
          const mimeType = imageSrc.split(';')[0].split(':')[1] || 'image/jpeg';
          const generatedImage = await generateCleanSimulation(base64Data, mimeType, config);
          setCleanImage(generatedImage);
          // SAVE SIMULATION RESULT TO PARENT STATE
          onSaveSimulation(generatedImage);

          setShowCleanModal(true);
      } catch (error: any) {
          const msg = error.message || "";
          if (msg.includes("AI Refusal") || msg.includes("Safety") || msg.includes("blocked")) {
              alert("SIMULATION FAILED: Safety filters triggered.");
          } else {
              alert(`SIMULATION FAILED: ${msg}`);
          }
      } finally {
          setIsCleaning(false);
      }
