import { useLanguage } from '../contexts/LanguageContext';

const getRiskColorParams = (category: RiskCategory) => {
  switch (category) {
    case 'HYGIENE': return { 
      border: 'border-amber-500', text: 'text-amber-400', bg: 'bg-amber-900/40', 
      shadow: 'shadow-[0_0_15px_rgba(245,158,11,0.3)]', badge: 'bg-amber-500 text-black', icon: '☣' 
    };
    case 'SAFETY': return { 
      border: 'border-indigo-500', text: 'text-indigo-400', bg: 'bg-indigo-900/40', 
      shadow: 'shadow-[0_0_15px_rgba(99,102,241,0.5)]', badge: 'bg-indigo-500 text-white', icon: '⚠️' 
    };
    default: return { 
      border: 'border-red-500', text: 'text-red-400', bg: 'bg-red-900/40', 
      shadow: 'shadow-[0_0_15px_rgba(239,68,68,0.3)]', badge: 'bg-red-600 text-white', icon: '🦟' 
    };
  }
};

// Updated RiskListItem to take an 'index' prop for clean numbering
const RiskListItem: React.FC<{ risk: RiskDetection, index: number, activeId: string | null, onClick: (r: RiskDetection) => void }> = ({ risk, index, activeId, onClick }) => {
  const isActive = activeId === risk.id;
  const params = getRiskColorParams(risk.category);
  const isManual = risk.id.startsWith('manual');

  // Format number to be 01, 02, etc. (Index passed is 1-based usually)
  const displayNum = (index).toString().padStart(2, '0');

  return (
    <button onClick={() => onClick(risk)} className={`no-print relative flex items-center gap-3 md:gap-4 p-2 md:p-4 rounded-lg text-left transition-all duration-300 border group w-full ${isActive ? `${params.bg} ${params.border} ${params.shadow}` : 'bg-slate-950/60 border-slate-800 hover:border-emerald-500/50 hover:bg-slate-900'}`}>
      <div className={`w-8 h-8 md:w-10 md:h-10 rounded flex items-center justify-center font-bold text-xs md:text-sm shrink-0 font-mono-sci relative ${params.badge} shadow-[0_0_10px_currentColor]`}>
        {displayNum}
        {isManual && <span className="absolute -top-1 -right-1 w-3 h-3 bg-white rounded-full animate-ping"></span>}
      </div>
      <div className="overflow-hidden flex-1 min-w-0">
        <div className={`font-sci-fi text-xs md:text-sm font-bold truncate flex items-center gap-2 ${isActive ? 'text-white' : 'text-slate-300 group-hover:text-emerald-400'}`}>
          <span className="truncate">{risk.label}</span>
          {isManual && <span className="text-[9px] bg-slate-700 text-white px-1 rounded border border-slate-500 shrink-0">MANUAL</span>}
        </div>
        <div className="text-[10px] md:text-xs text-slate-500 font-mono-sci italic truncate">{risk.agent}</div>
      </div>
      <div className="text-slate-600 shrink-0"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4 md:w-5 md:h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M8.25 4.5l7.5 7.5-7.5 7.5" /></svg></div>
    </button>
  );
};

// NEW: Dual Score Card
const DualScoreCard: React.FC<{ hygieneLevel: number, safetyLevel: number, isSavage: boolean }> = ({ hygieneLevel, safetyLevel, isSavage }) => {

    // Safety Default if not present
    const safeLevel = safetyLevel || hygieneLevel;

    const getColor = (level: number) => {
        if (level >= 4) return 'text-emerald-400 border-emerald-500';
        if (level === 3) return 'text-yellow-400 border-yellow-500';
        return 'text-red-500 border-red-500';
    };

    return (
        <div className="w-full relative overflow-hidden rounded-xl border border-slate-700 bg-slate-900/80 p-4 md:p-6 shadow-xl mb-4 transition-all duration-500 print:bg-white print:border-black print:text-black">
             <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-10 mix-blend-overlay print:hidden"></div>

             <div className="relative z-10 grid grid-cols-2 gap-4 md:gap-8 divide-x divide-slate-700 print:divide-black">

                 {/* HYGIENE SECTION */}
                 <div className="flex flex-col items-center justify-center text-center">
                     <div className="text-[10px] font-mono-sci uppercase tracking-widest text-slate-400 mb-2 print:text-black">HYGIENE</div>
                     <div className={`w-12 h-12 md:w-16 md:h-16 rounded-full border-4 flex items-center justify-center bg-black/20 backdrop-blur mb-2 print:bg-transparent ${getColor(hygieneLevel)} print:border-black print:text-black`}>
                        <span className="text-xl md:text-3xl font-bold font-sci-fi">{hygieneLevel}</span>
                        <span className="text-[10px] opacity-60 mb-2">/5</span>
                     </div>
                     <div className="text-xs font-bold text-white print:text-black">
                         {hygieneLevel >= 4 ? 'STERILE' : hygieneLevel === 3 ? 'MODERATE' : 'CRITICAL'}
                     </div>
                 </div>

                 {/* SAFETY SECTION */}
                 <div className="flex flex-col items-center justify-center text-center pl-4 md:pl-8">
                     <div className="text-[10px] font-mono-sci uppercase tracking-widest text-slate-400 mb-2 print:text-black">OSH SAFETY</div>
                     <div className={`w-12 h-12 md:w-16 md:h-16 rounded-full border-4 flex items-center justify-center bg-black/20 backdrop-blur mb-2 print:bg-transparent ${getColor(safeLevel)} print:border-black print:text-black`}>
                        <span className="text-xl md:text-3xl font-bold font-sci-fi">{safeLevel}</span>
                        <span className="text-[10px] opacity-60 mb-2">/5</span>
                     </div>
                     <div className="text-xs font-bold text-white print:text-black">
                         {safeLevel >= 4 ? 'SECURE' : safeLevel === 3 ? 'RISKY' : 'DANGEROUS'}
                     </div>
                 </div>

             </div>

             {/* Total Verdict Label */}
             <div className="mt-4 pt-3 border-t border-slate-800 print:border-black text-center">
                 <span className={`text-xs md:text-sm font-sci-fi font-bold uppercase tracking-widest ${Math.min(hygieneLevel, safeLevel) < 3 ? 'text-red-500 animate-pulse print:text-black print:animate-none' : 'text-emerald-400 print:text-black'}`}>
                     {isSavage ? 'HONEST VERDICT: ' : 'STATUS: '} 
                     {Math.min(hygieneLevel, safeLevel) === 1 ? 'IMMEDIATE CLOSURE' : Math.min(hygieneLevel, safeLevel) === 2 ? 'NOTICE ISSUED' : Math.min(hygieneLevel, safeLevel) === 3 ? 'WARNING' : 'COMPLIANT'}
                 </span>
             </div>
        </div>
    );
};

