      : hygieneLevel < 4 ? 'text-orange-500 border-orange-500'
      : 'text-cyan-400 border-cyan-400';

   const moodBg = !isSavage ? 'bg-emerald-900/20' : hygieneLevel < 3 ? 'bg-red-900/20' : 'bg-slate-900';

   if (!isSavage) {
      return (
         <div className="w-14 h-14 md:w-20 md:h-20 rounded-full bg-slate-900 border-2 border-emerald-500 flex items-center justify-center shadow-[0_0_20px_rgba(16,185,129,0.3)] shrink-0 print:border-black print:text-black print:bg-transparent print:shadow-none">
             <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8 md:w-10 md:h-10 text-emerald-400 print:text-black">
               <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12c0 1.268-.63 2.39-1.593 3.068a3.745 3.745 0 01-1.043 3.296 3.745 3.745 0 01-3.296 1.043A3.745 3.745 0 0112 21c-1.268 0-2.39-.63-3.068-1.593a3.746 3.746 0 01-3.296-1.043 3.745 3.745 0 01-1.043-3.296A3.745 3.745 0 013 12c0-1.268.63-2.39 1.593-3.068a3.745 3.745 0 011.043-3.296 3.746 3.746 0 013.296-1.043A3.746 3.746 0 0112 3c1.268 0 2.39.63 3.068 1.593a3.746 3.746 0 013.296 1.043 3.746 3.746 0 011.043 3.296A3.745 3.745 0 0121 12z" />
             </svg>
         </div>
      )
   }

   return (
      <div className={`relative w-14 h-14 md:w-20 md:h-20 rounded-full ${moodBg} border-2 ${moodColor} flex items-center justify-center overflow-hidden shadow-2xl transition-all duration-500 shrink-0 print:border-black print:bg-transparent print:text-black print:shadow-none`}>
          <svg viewBox="0 0 100 100" className="w-full h-full p-2">
             <path d="M20,40 Q20,10 50,10 Q80,10 80,40 L80,50 L20,50 Z" fill="currentColor" opacity="0.8" />
             <path d="M30,50 L70,50 L70,80 Q70,95 50,95 Q30,95 30,80 Z" fill="currentColor" opacity="0.3" />
             {/* Simple SVG paths... */}
             <rect x="40" y="75" width="20" height="10" rx="2" fill="currentColor" />
          </svg>
      </div>
   )
}

