        <div className="bg-slate-900 border border-purple-500 rounded-xl p-6 w-full max-w-lg shadow-[0_0_50px_rgba(168,85,247,0.3)]">
            <h3 className="text-xl font-bold text-white mb-4">Export Features Coming Soon</h3>
            <button onClick={onClose} className="px-5 py-2 rounded text-slate-400 hover:text-white border border-slate-600">CLOSE</button>
        </div>
    </div>
  );
};

interface AnalysisResultsProps {
  result: AnalysisResponse;
  imageSrc: string;
  savedSimulationImage?: string; 
  onSaveSimulation: (image: string) => void;
}

export const AnalysisResults: React.FC<AnalysisResultsProps> = ({ result, imageSrc, savedSimulationImage, onSaveSimulation }) => {
  const [activeRisk, setActiveRisk] = useState<RiskDetection | null>(null);
  const [currentRisks, setCurrentRisks] = useState<RiskDetection[]>(result.risks);
  const [isSavageMode, setIsSavageMode] = useState(false);
  const [showReportPreview, setShowReportPreview] = useState(false);
  const [chatOpen, setChatOpen] = useState(false);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [userQuestion, setUserQuestion] = useState("");
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [manualBox, setManualBox] = useState<BoundingBox | null>(null);
  const [showManualModal, setShowManualModal] = useState(false);
  const [manualContext, setManualContext] = useState("");
  const [isProcessingManual, setIsProcessingManual] = useState(false);
  const [isCleaning, setIsCleaning] = useState(false);
  const [cleanImage, setCleanImage] = useState<string | null>(savedSimulationImage || null);
  const [showCleanModal, setShowCleanModal] = useState(false);
  const [showConfigModal, setShowConfigModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);

  const { language, t } = useLanguage();

  useEffect(() => { setCleanImage(savedSimulationImage || null); }, [savedSimulationImage]);
  useEffect(() => { if (currentRisks && currentRisks.length > 0 && !activeRisk) setActiveRisk(currentRisks[0]); }, [currentRisks]);

  const handleRiskChange = (risk: RiskDetection) => {
    setActiveRisk(risk);
    if (window.innerWidth < 1024) {
      setTimeout(() => document.getElementById('details-panel')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 100);
    }
  }

  const bioRisks = currentRisks.filter(r => r.category === 'VECTOR' || r.category === 'HYGIENE');
  const safetyRisks = currentRisks.filter(r => r.category === 'SAFETY');
  const getRiskIndex = (risk: RiskDetection) => currentRisks.findIndex(r => r.id === risk.id) + 1;

  const handleRegionDrawn = (box: BoundingBox) => {
    setManualBox(box);
    setShowManualModal(true);
    setIsEditing(false);
  };

  const submitManualAnalysis = async () => {
    if (!manualBox || !manualContext) return;
    setIsProcessingManual(true);
    try {
        const cleanBase64 = imageSrc.split(',')[1] || imageSrc;
        const mimeType = imageSrc.split(';')[0].split(':')[1] || 'image/jpeg';
        const newRisk = await analyzeManualRegion(cleanBase64, mimeType, manualBox, manualContext, language);
        setCurrentRisks([newRisk, ...currentRisks]);
        setActiveRisk(newRisk);
        setShowManualModal(false);
        setManualContext("");
        setManualBox(null);
    } catch (e) {
        alert("Gagal memproses.");
    } finally {
        setIsProcessingManual(false);
    }
  };

  const cancelManualMode = () => {
    setIsEditing(false);
    setShowManualModal(false);
    setManualBox(null);
    setManualContext("");
  };

  const handleOpenSimulation = () => {
      cleanImage ? setShowCleanModal(true) : setShowConfigModal(true);
  };

  const startSimulation = async (config: SimulationConfig) => {
      setShowConfigModal(false);
      setIsCleaning(true);
      try {
          const base64Data = imageSrc.split(',')[1];
          const mimeType = imageSrc.split(';')[0].split(':')[1] || 'image/jpeg';
          const generatedImage = await generateCleanSimulation(base64Data, mimeType, config);
          setCleanImage(generatedImage);
          onSaveSimulation(generatedImage);
          setShowCleanModal(true);
      } catch (error: any) {
          alert(`Simulasi Gagal: ${error.message}`);
      } finally {
          setIsCleaning(false);
      }
  };

  const handleAskAI = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userQuestion.trim() || !activeRisk) return;
    const newMsg: ChatMessage = { role: 'user', text: userQuestion };
    setChatMessages(prev => [...prev, newMsg]);
    setUserQuestion("");
    setIsChatLoading(true);
    try {
      const response = await askRiskFollowUp(activeRisk, newMsg.text, language);
      setChatMessages(prev => [...prev, { role: 'model', text: response }]);
    } catch (error) {
      setChatMessages(prev => [...prev, { role: 'model', text: "Error contacting AI." }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const handlePrint = () => {
      window.print();
  };

  const generateYoutubeLink = (risk: RiskDetection) => {
     const query = encodeURIComponent(`microscope view ${risk.agent} ${risk.label}`);
     return `https://www.youtube.com/results?search_query=${query}`;
  };

  if (showReportPreview) {
    return (
      /* 
       * REPORT VIEWER CONTAINER (A4 Simulation)
       * Designed to look like a Document Reader (Dark Background, White Paper)
       */
      <div id="printable-report-container" className="fixed inset-0 z-[200] bg-slate-900/95 backdrop-blur-sm overflow-y-auto flex flex-col items-center">

         {/* --- STICKY CONTROL BAR (NO PRINT) --- */}
         <div className="no-print-ui sticky top-0 z-50 w-full bg-slate-900 text-white p-4 shadow-xl flex justify-between items-center border-b border-slate-700">
            <h2 className="font-bold text-lg flex items-center gap-2">
               <span className="text-emerald-500">📄</span> {t('btn_view_report')}
            </h2>
            <div className="flex gap-3">
               <button onClick={() => setShowReportPreview(false)} className="px-4 py-2 rounded border border-slate-600 hover:bg-slate-800 transition text-sm">
                  KEMBALI
               </button>
               {/* PRIMARY PRINT BUTTON */}
               <button onClick={handlePrint} className="bg-emerald-600 hover:bg-emerald-500 px-6 py-2 rounded font-bold shadow-lg flex items-center gap-2 text-white animate-pulse hover:animate-none transition-all hover:scale-105">
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                     <path strokeLinecap="round" strokeLinejoin="round" d="M6.72 13.829c-.24.03-.48.062-.72.096m.72-.096a42.415 42.415 0 0110.56 0m-10.56 0L6.34 18m10.94-4.171c.24.03.48.062.72.096m-.72-.096L17.66 18m0 0l.229 2.523a1.125 1.125 0 01-1.12 1.227H7.231c-.662 0-1.18-.568-1.12-1.227L6.34 18m11.318 0h1.091A2.25 2.25 0 0021 15.75V9.456c0-1.081-.768-2.015-1.837-2.175a48.055 48.055 0 00-1.913-.247M6.34 18H5.25A2.25 2.25 0 013 15.75V9.456c0-1.081.768-2.015 1.837-2.175a48.041 48.041 0 011.913-.247m10.5 0a48.536 48.536 0 00-10.5 0m10.5 0V3.375c0-.621-.504-1.125-1.125-1.125h-8.25c-.621 0-1.125.504-1.125 1.125v3.659M18 10.5h.008v.008H18V10.5zm-3 0h.008v.008H15V10.5z" />
                  </svg>
                  PRINT / SIMPAN PDF
               </button>
            </div>
         </div>

         {/* --- A4 PAPER (PRINTABLE AREA) --- */}
         {/* Removed all dark mode classes. Used pure white/black for print clarity. */}
         <div id="printable-report" className="w-full max-w-[210mm] bg-white min-h-[297mm] shadow-2xl my-8 p-12 text-black box-border relative">

            {/* Report Header */}
            <div className="border-b-4 border-black pb-6 mb-8 flex justify-between items-start">
               <div>
                  <h1 className="text-4xl font-extrabold text-black tracking-tight uppercase mb-2">VECTORGUARD.AI</h1>
                  <p className="text-sm font-bold text-gray-600 font-mono tracking-widest uppercase">BIO-DEFENSE INTELLIGENCE UNIT</p>
                  <p className="text-sm text-gray-500 mt-1">Report Generated: {new Date().toLocaleDateString()}</p>
               </div>
               <div className="text-right">
                  {/* Scores - High Contrast for Print */}
                  <div className="flex gap-4">
                      <div className="border-2 border-black px-4 py-2 rounded text-center min-w-[100px]">
                         <span className="block text-[10px] uppercase font-bold tracking-wider">Hygiene</span>
                         <span className="block text-3xl font-bold">{result.hygieneLevel}/5</span>
                      </div>
                      <div className="bg-black text-white px-4 py-2 rounded text-center min-w-[100px] border-2 border-black print:text-black print:bg-transparent print:border-black">
                         <span className="block text-[10px] uppercase font-bold tracking-wider">Safety</span>
                         <span className="block text-3xl font-bold">{result.safetyLevel || result.hygieneLevel}/5</span>
                      </div>
                  </div>
               </div>
            </div>

            {/* Main Evidence Image */}
            <div className="mb-8 p-1 border-2 border-black rounded bg-white">
               <img src={imageSrc} alt="Evidence" className="w-full h-auto max-h-[400px] object-contain mx-auto print:max-h-[8cm]" />
            </div>

            {/* General Advice - High Contrast Box */}
            <div className="mb-8 avoid-break border-2 border-black p-6 rounded-lg bg-white">
               <h3 className="text-lg font-bold text-black uppercase border-b-2 border-black pb-2 mb-4 inline-block">EXECUTIVE SUMMARY</h3>
               <p className="text-black text-justify leading-relaxed text-sm font-serif">
                  {result.generalAdvice}
               </p>
            </div>

            {/* Detailed Risks - High Contrast Cards */}
            <div className="mb-8">
               <h3 className="text-lg font-bold text-black uppercase border-b-2 border-black pb-2 mb-6 inline-block">DETAILED RISK ANALYSIS</h3>
               <div className="space-y-6">
                  {currentRisks.map((risk, index) => (
                     <div key={risk.id} className="break-inside-avoid border-2 border-black rounded-lg overflow-hidden page-break-inside-avoid print-border bg-white mb-6 shadow-none">

                        {/* Card Header - Black Bar */}
                        <div className="bg-black text-white px-4 py-2 border-b-2 border-black flex justify-between items-center print:bg-gray-200 print:text-black">
                           <div className="font-bold flex items-center gap-2">
                              <span className="bg-white text-black w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold border border-black">{index + 1}</span>
                              <span className="uppercase tracking-wide">{risk.label}</span>
                           </div>
                           <span className="text-xs font-bold px-2 py-1 bg-white text-black rounded border border-black uppercase">
                              {risk.category}
                           </span>
                        </div>

                        {/* Card Body - Grid Layout */}
                        <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-4 text-sm font-sans text-black">

                           <div className="col-span-2 md:col-span-1 border-b border-gray-300 pb-2">
                              <p className="text-[10px] uppercase font-bold text-gray-600 mb-1">Identified Agent:</p>
                              <p className="font-bold italic">{risk.agent}</p>
                           </div>

                           <div className="col-span-2 md:col-span-1 border-b border-gray-300 pb-2">
                              <p className="text-[10px] uppercase font-bold text-gray-600 mb-1">Potential Disease/Risk:</p>
                              <p className="font-semibold">{risk.disease}</p>
                           </div>

                           <div className="col-span-2 bg-gray-50 p-3 rounded border border-gray-200 print:bg-white print:border-black print:border-dashed">
                              <p className="text-[10px] uppercase font-bold text-gray-600 mb-1">Analysis:</p>
                              <p className="text-justify leading-relaxed">{risk.description}</p>
                           </div>

                           {/* Micro & Stats Row */}
                           <div className="col-span-2 md:col-span-1">
                              <p className="text-[10px] uppercase font-bold text-gray-600 mb-1">Microbiology:</p>
                              <p className="text-sm">{risk.microbiology}</p>
                           </div>
                           <div className="col-span-2 md:col-span-1">
                              <p className="text-[10px] uppercase font-bold text-gray-600 mb-1">Statistics:</p>
                              <p className="text-sm">{risk.statistics}</p>
                           </div>

                           {/* Recommendation Row */}
                           <div className="col-span-2 border-t-2 border-black pt-3 mt-2">
                              <p className="text-[10px] uppercase font-bold text-black mb-1">Recommended Action:</p>
                              <p className="font-bold">{risk.solution}</p>
                           </div>
                        </div>
                     </div>
                  ))}
               </div>
            </div>

            <div className="border-t-4 border-black pt-6 mt-12 text-center text-xs font-bold uppercase tracking-widest">
               <p>End of Report • Generated by VectorGuard AI System</p>
            </div>
         </div>
      </div>
    );
  }

  // MANUAL TARGETING MODAL
  if (showManualModal) {
     return (
        <div className="fixed inset-0 z-[200] bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-slate-900 border border-emerald-500 rounded-xl p-6 w-full max-w-sm shadow-2xl animate-fade-in-up">
                <h3 className="text-lg font-sci-fi font-bold text-white mb-4 flex items-center gap-2">
                    <span className="text-emerald-400">🎯 MANUAL TARGETING</span>
                </h3>
                <div className="mb-4">
                    <label className="text-xs text-slate-400 block mb-2 font-mono-sci">WHAT ARE WE LOOKING AT?</label>
                    <textarea 
                        value={manualContext}
                        onChange={(e) => setManualContext(e.target.value)}
                        placeholder="e.g. Look at the dark spot in the corner..."
                        rows={3}
                        className="w-full bg-slate-950 border border-slate-700 rounded p-3 text-white text-sm focus:border-emerald-500 outline-none"
                    />
                </div>
                <div className="flex gap-2">
                    <button onClick={cancelManualMode} disabled={isProcessingManual} className="flex-1 py-2 bg-slate-800 text-slate-300 rounded hover:bg-slate-700 transition">
                        CANCEL
                    </button>
                    <button 
                        onClick={submitManualAnalysis} 
                        disabled={!manualContext.trim() || isProcessingManual}
                        className="flex-1 py-2 bg-emerald-600 text-white rounded font-bold hover:bg-emerald-500 transition shadow-[0_0_15px_rgba(16,185,129,0.4)] disabled:opacity-50 flex items-center justify-center gap-2"
                    >
                        {isProcessingManual ? (
                            <>
                                <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                                SCANNING...
                            </>
                        ) : (
                            "ANALYZE REGION"
                        )}
                    </button>
                </div>
            </div>
        </div>
     )
  }

  if (!activeRisk) return null;

  return (
    <div className="animate-fade-in pb-20 no-print">
      <SimulationConfigModal 
        isOpen={showConfigModal} 
        onClose={() => setShowConfigModal(false)}
        onStart={startSimulation}
      />
      <SimulationResultModal
        isOpen={showCleanModal}
        onClose={() => setShowCleanModal(false)}
        originalImage={imageSrc}
        generatedImage={cleanImage || ""}
      />
      <ExternalExportModal
        isOpen={showExportModal}
        onClose={() => setShowExportModal(false)}
        imageSrc={imageSrc}
      />
      {/* ... (Rest of AnalysisResults render remains same) ... */}
      <div className="flex flex-wrap gap-3 justify-between items-center mb-4 md:mb-6 no-print">
         <div className="flex gap-2">
            <button 
                onClick={() => setIsEditing(!isEditing)}
                className={`flex items-center gap-2 px-3 py-1.5 md:px-4 md:py-2 rounded text-xs md:text-sm font-bold uppercase tracking-wider transition-all border
                    ${isEditing 
                        ? 'bg-red-600 text-white border-red-500 shadow-[0_0_15px_red] animate-pulse' 
                        : 'bg-slate-800 text-slate-300 border-slate-600 hover:border-emerald-500 hover:text-emerald-400'}
                `}
            >
                {isEditing ? '🔴 TARGETING ACTIVE' : `🎯 ${t('btn_manual_scan')}`}
            </button>

            <button
                onClick={handleOpenSimulation}
                disabled={isCleaning}
                className={`flex items-center gap-2 px-3 py-1.5 md:px-4 md:py-2 rounded text-xs md:text-sm font-bold uppercase tracking-wider transition-all border border-cyan-500/50 hover:bg-cyan-900/30 text-cyan-400 hover:shadow-[0_0_15px_rgba(34,211,238,0.4)] disabled:opacity-50`}
            >
                {isCleaning ? (
                    <span className="flex items-center gap-2 animate-pulse">
                        SIMULATING...
                    </span>
                ) : (
                    <>✨ {t('btn_simulation')}</>
                )}
            </button>

            <button
                onClick={() => setShowExportModal(true)}
                className="flex items-center gap-2 px-3 py-1.5 md:px-4 md:py-2 rounded text-xs md:text-sm font-bold uppercase tracking-wider transition-all border border-purple-500/50 hover:bg-purple-900/30 text-purple-400 hover:shadow-[0_0_15px_rgba(168,85,247,0.4)]"
            >
                🚀 {t('btn_export')}
            </button>
         </div>

         <div className="flex items-center gap-2 md:gap-4">
            <button onClick={() => setShowReportPreview(true)} className="flex items-center gap-2 bg-emerald-700 hover:bg-emerald-600 text-white px-4 py-2 rounded text-xs md:text-sm font-bold shadow-lg border border-emerald-500 transition-all">
               <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m2.25 0H5.625c-.621 0-1.18-.568-1.12-1.227v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z" />
               </svg>
               {t('btn_view_report')}
            </button>

            <div className="flex items-center gap-2 bg-slate-900 rounded-full p-1 border border-slate-700">
               <button onClick={() => setIsSavageMode(false)} className={`px-3 py-1 rounded-full text-[10px] font-bold ${!isSavageMode ? 'bg-emerald-600 text-white' : 'text-slate-500 hover:text-white'}`}>{t('tab_official')}</button>
               <button onClick={() => setIsSavageMode(true)} className={`px-3 py-1 rounded-full text-[10px] font-bold ${isSavageMode ? 'bg-red-600 text-white' : 'text-slate-500 hover:text-white'}`}>{t('tab_savage')}</button>
            </div>
         </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 md:gap-6">
        <div className="lg:col-span-7 flex flex-col gap-4">
           <div className="relative rounded-xl overflow-hidden border border-slate-700 bg-slate-900 group">
              <div className="absolute top-0 left-0 bg-black/60 text-white text-[10px] px-2 py-1 z-50 font-mono-sci rounded-br border-b border-r border-slate-700">
                  SOURCE_IMG: {result.risks.length} THREATS
              </div>
              <ImageAnnotator 
                imageSrc={imageSrc} 
                risks={currentRisks} 
                onRiskSelect={handleRiskChange} 
                selectedId={activeRisk.id}
                isEditing={isEditing}
                onRegionDrawn={handleRegionDrawn}
              />
              {/* UPDATED OVERLAY TO SHOW BOTH SCORES */}
              <div className="absolute bottom-4 right-4 flex items-center gap-2 bg-slate-900/90 backdrop-blur border border-slate-600 px-3 py-2 rounded-lg z-40 shadow-xl">
                 <div className="flex flex-col items-end">
                    <div className="flex items-center gap-2 mb-1">
                        <span className="text-[9px] text-slate-400 font-mono-sci uppercase">HYGIENE</span>
                        <div className={`w-6 h-6 rounded-full flex items-center justify-center font-bold text-xs border ${result.hygieneLevel >= 4 ? 'border-emerald-500 text-emerald-400' : 'border-red-500 text-red-500'}`}>
                            {result.hygieneLevel}
                        </div>
                    </div>
                    <div className="flex items-center gap-2">
                        <span className="text-[9px] text-slate-400 font-mono-sci uppercase">SAFETY</span>
