// PERFORMANCE FIX: Reduce Image Size Client-Side before sending to Gemini
const compressImage = (base64Str: string, maxWidth = 1024, quality = 0.7): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = `data:image/jpeg;base64,${base64Str}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let width = img.width;
            let height = img.height;

            if (width > maxWidth) {
                height = Math.round((height * maxWidth) / width);
                width = maxWidth;
            }

            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);

            // Get compressed base64 (remove prefix for API)
            const newDataUrl = canvas.toDataURL('image/jpeg', quality);
            resolve(newDataUrl.split(',')[1]);
        };
        img.onerror = () => {
            // Fallback: return original if compression fails
            resolve(base64Str); 
        };
    });
};

// HELPER: Get Image Aspect Ratio Data
const getImageDimensions = (base64Str: string): Promise<{width: number, height: number, ratioStr: string}> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = `data:image/jpeg;base64,${base64Str}`;
        img.onload = () => {
            const w = img.width;
            const h = img.height;
            const r = w / h;

            // Determine Closest Standard Aspect Ratio for Google Imagen
            let aspect = "1:1";
            if (r >= 1.7) aspect = "16:9";      // Landscape Wide
            else if (r >= 1.2) aspect = "4:3";  // Landscape Standard
            else if (r <= 0.6) aspect = "9:16"; // Portrait Tall
            else if (r <= 0.85) aspect = "3:4"; // Portrait Standard

            resolve({ width: w, height: h, ratioStr: aspect });
        };
        img.onerror = () => resolve({ width: 1024, height: 1024, ratioStr: "1:1" });
    });
};

// Retry utility (Simplified: Just backoff, no rotation)
const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> => {
    try {
        return await fn();
    } catch (error: any) {
        const msg = error.message || "";
        const isQuotaError = msg.includes("429") || msg.includes("503") || msg.includes("quota") || msg.includes("exhausted") || msg.includes("resource");

        if (isQuotaError) {
            console.warn(`⚠️ Quota Error. Retrying in ${delay/1000}s...`);
            if (retries > 0) {
                await new Promise(resolve => setTimeout(resolve, delay));
                return retryWithBackoff(fn, retries - 1, delay * 2); // Exponential backoff
            }
        }
        throw error;
    }
};

