                    </div>
                    <div className="mt-4 pt-4 border-t border-slate-800">
                        {chatMessages.length > 0 && (<div className="mb-3 max-h-[150px] overflow-y-auto custom-scrollbar bg-black/40 rounded p-2 text-xs space-y-2">{chatMessages.map((msg, idx) => (<div key={idx} className={`${msg.role === 'user' ? 'text-right text-emerald-300' : 'text-left text-slate-300'}`}><span className="font-bold">{msg.role === 'user' ? 'YOU: ' : 'AI: '}</span>{msg.text}</div>))}<div ref={chatEndRef}></div></div>)}
                        <form onSubmit={handleAskAI} className="relative"><input type="text" value={userQuestion} onChange={(e) => setUserQuestion(e.target.value)} placeholder={t('chat_placeholder')} disabled={isChatLoading} className="w-full bg-slate-950 border border-slate-700 rounded-full py-3 px-5 pr-12 text-sm text-white focus:border-emerald-500 outline-none" /><button type="submit" disabled={isChatLoading || !userQuestion.trim()} className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-emerald-600 rounded-full text-white">➤</button></form>
                    </div>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export interface GroundingChunk {
  web?: {
    uri?: string;
    title?: string;
  };
}

// Coordinate structure returned by Gemini (usually 0-1000 scale)
export interface BoundingBox {
  ymin: number;
  xmin: number;
  ymax: number;
  xmax: number;
}

export type RiskCategory = 'VECTOR' | 'HYGIENE' | 'SAFETY';

export interface Citation {
  id: number;
  source: string; // e.g., "CDC", "WHO", "ResearchGate"
  title: string;
  url: string;
}

export interface RiskDetection {
  id: string;
  category: RiskCategory; 
  label: string; 
  agent: string; 
  disease: string; 
  microbiology: string; // New: Specific germs (Bacteria/Virus names)
  statistics: string; // New: Annual death/case stats
  description: string; // Text with (1), (2) markers
  solution: string; 
  box_2d: BoundingBox;
  citations: Citation[]; // List of references
  microscopeVideoUrl?: string; // YouTube link
}

export interface AnalysisResponse {
  risks: RiskDetection[];
  generalAdvice: string; // Official Professional Advice
  savageCommentary?: string; // The "Nightmare Chef" Persona Advice
  groundingChunks?: GroundingChunk[];
  hygieneLevel: number; // 1 (Worst) to 5 (Best) - Focus on VECTORS/CLEANLINESS
  safetyLevel: number; // 1 (Worst) to 5 (Best) - Focus on OSH/HAZARDS
  timestamp?: number; // Added for report generation

  // New for World Class Features
  predictedOutbreakChance?: number; // 0-100%
  legalSection?: string; // e.g., "Seksyen 8 Akta 154"
}

// NEW: Session interface for multi-image support
export interface AnalysisSession {
  id: string;
  imageSrc: string; // Base64 for preview
  mimeType: string;
  fileName: string;
  status: 'PENDING' | 'ANALYZING' | 'SUCCESS' | 'ERROR';
  result?: AnalysisResponse;
  error?: string;
  simulationImage?: string; // PERSISTENCE: Store generated clean image here
}

export enum AppState {
  IDLE = 'IDLE',
  ANALYZING = 'ANALYZING', // Keep for backward compatibility/Live mode
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

// NEW: MOH Data Types
export interface DengueData {
  date: string;
  cases: number;
  state: string;
}

export interface EpidemicTrend {
  weeks: string[];
  cases: number[];
