const compressImage = (base64Str: string, maxWidth = 1024, quality = 0.7): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = `data:image/jpeg;base64,${base64Str}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let width = img.width;
            let height = img.height;
            if (width > maxWidth) {
                height = Math.round((height * maxWidth) / width);
                width = maxWidth;
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            resolve(canvas.toDataURL('image/jpeg', quality).split(',')[1]);
        };
        img.onerror = () => resolve(base64Str); 
    });
};

// Retry utility
const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> => {
    try {
        return await fn();
    } catch (error: any) {
        const msg = error.message || "";
        const isQuotaError = msg.includes("429") || msg.includes("503");
        if (isQuotaError && retries > 0) {
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(fn, retries - 1, delay * 2);
        }
        throw error;
    }
};

/**
 * Smart Analysis Function
 */
export const analyzeLandscape = async (base64Image: string, mimeType: string, mode: 'FAST' | 'DETAILED' = 'DETAILED', language: string = 'ms'): Promise<AnalysisResponse> => {
  const langMap: Record<string, string> = { 'ms': 'Bahasa Melayu', 'en': 'English', 'zh': 'Chinese', 'ta': 'Tamil' };
  const targetLang = langMap[language] || 'Bahasa Melayu';
  const optimizedImage = await compressImage(base64Image);
  const modelsToTry = ["gemini-3-pro-preview", "gemini-2.5-flash"];

  const schemaDescription = `
  {
    "risks": [
      {
        "id": "string", "category": "VECTOR | HYGIENE | SAFETY", "label": "string", "agent": "string",
        "disease": "string", "microbiology": "string", "statistics": "string", "description": "string",
        "solution": "string", "box_2d": { "ymin": number, "xmin": number, "ymax": number, "xmax": number },
        "citations": []
      }
    ],
    "generalAdvice": "string", "savageCommentary": "string", "hygieneLevel": number, "safetyLevel": number,
    "predictedOutbreakChance": number (0-100), "legalSection": "string"
  }
  `;

  let lastError: any = null;

  for (const modelId of modelsToTry) {
     try {
         const tools = (mode === 'DETAILED') ? [{ googleSearch: {} }] : undefined;
         const response = await retryWithBackoff(async () => {
              const ai = getAIClient();
              return await ai.models.generateContent({
                model: modelId,
                contents: {
                    parts: [
                        { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, 
                        { text: `Visual forensic analysis for Vector Control & Safety.
                                ROLE: ACT AS A SENIOR HEALTH INSPECTOR (PPKP KANAN).
                                Language: ${targetLang}.

                                SCORING:
                                1 (CRITICAL): Rats/Roaches/Danger.
                                5 (EXCELLENT): Lab Sterile.

                                REQUIREMENTS:
                                1. 'generalAdvice': Must be a DETAILED, PROFESSIONAL EXECUTIVE REPORT (minimum 300 words). 
                                   Format it with clear headers using uppercase labels like [PENEMUAN UTAMA], [ANCAMAN KESIHATAN], [ARAHAN TINDAKAN].
                                   - Explain the biological threats in detail (organ impact, disease transmission).
                                   - Provide a numbered step-by-step mandatory action plan for the owner.
                                   - Mention specific legal implications (fines/jail) under Malaysia's Akta 154 (APSPP 1975).

                                2. 'risks': Provide detailed technical descriptions.
                                3. 'savageCommentary': Short, extremely harsh criticism.

                                NEW REQUIREMENT:
                                - Estimate 'predictedOutbreakChance' (0-100) based on filth level.
                                - Suggest 'legalSection' based on Malaysian Laws (Akta 154/Akta 342) if score < 3.

                                Output JSON: ${schemaDescription}` }
                    ]
                },
                config: { tools: tools }
            });
         });

         let text = response.text;
         if (!text) throw new Error("Empty response");
         text = text.replace(/```json/g, '').replace(/```/g, '');
         const jsonStartIndex = text.indexOf('{');
         const jsonEndIndex = text.lastIndexOf('}');
         if (jsonStartIndex !== -1 && jsonEndIndex !== -1) text = text.substring(jsonStartIndex, jsonEndIndex + 1);

         const parsedResult = JSON.parse(text) as AnalysisResponse;
         const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
         if (groundingChunks) parsedResult.groundingChunks = groundingChunks;
         if (parsedResult.safetyLevel === undefined) parsedResult.safetyLevel = parsedResult.hygieneLevel;

         return parsedResult;

     } catch (error: any) {
         lastError = error;
     }
  }
  throw lastError || new Error("AI Busy.");
};

export const analyzeManualRegion = async (base64Image: string, mimeType: string, box: BoundingBox, userContext: string, language: string = 'ms'): Promise<RiskDetection> => {
    // Simplified for brevity, same logic as before but uses compressed image
    const optimizedImage = await compressImage(base64Image);
    const langMap: Record<string, string> = { 'ms': 'Bahasa Melayu', 'en': 'English', 'zh': 'Chinese', 'ta': 'Tamil' };
    const targetLang = langMap[language] || 'Bahasa Melayu';

    const prompt = `Region Analysis [${box.ymin}-${box.ymax}, ${box.xmin}-${box.xmax}]. Hint: "${userContext}". Output JSON RiskDetection. Lang: ${targetLang}`;

    const schema = {
        type: Type.OBJECT,
        properties: {
            id: { type: Type.STRING },
            category: { type: Type.STRING, enum: ["VECTOR", "HYGIENE", "SAFETY"] },
            label: { type: Type.STRING },
            agent: { type: Type.STRING },
            disease: { type: Type.STRING },
            microbiology: { type: Type.STRING },
            statistics: { type: Type.STRING },
            description: { type: Type.STRING },
            solution: { type: Type.STRING },
            box_2d: { type: Type.OBJECT, properties: { ymin: {type:Type.NUMBER}, xmin: {type:Type.NUMBER}, ymax: {type:Type.NUMBER}, xmax: {type:Type.NUMBER} } },
            citations: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { id: {type:Type.NUMBER}, source: {type:Type.STRING}, title:{type:Type.STRING}, url:{type:Type.STRING} } } }
        }
    };

    const response = await retryWithBackoff(async () => {
        const ai = getAIClient();
        return await ai.models.generateContent({
            model: "gemini-3-pro-preview", 
            contents: { parts: [{ inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, { text: prompt }] },
            config: { responseMimeType: "application/json", responseSchema: schema }
        });
    });

    const result = JSON.parse(response.text!);
    result.id = `manual-${Date.now()}`;
    result.box_2d = box; 
    return result;
};

