export const generateCleanSimulation = async (base64Image: string, mimeType: string, config: SimulationConfig): Promise<string> => {
    const optimizedImage = await compressImage(base64Image);

    // STEP 1: Geometric & Semantic Analysis (Gemini 2.5 Flash)
    console.log("🎨 Step 1: Semantic Mapping...");

    let sceneDescription = "A room.";
    try {
        const analysisPrompt = `
        Analyze this image for an AI image reconstruction task.
        1. Describe the EXACT camera angle and room layout (e.g., 'Wide shot, corridor curving left, window on right').
        2. List KEY objects that define the structure (e.g., 'Concrete pillars, tiled floor, wooden door').
        3. Describe any PEOPLE: Their position, pose, and clothing type (e.g., 'Man in blue shirt standing on left').
        4. Describe the LIGHTING source.

        Keep it factual. Ignore the dirt/trash.
        `;

        const descResponse = await retryWithBackoff(async () => {
             const ai = getAIClient();
             return await ai.models.generateContent({
                model: "gemini-2.5-flash",
                contents: { parts: [{ inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, { text: analysisPrompt }] }
            });
        });
        sceneDescription = descResponse.text || sceneDescription;
    } catch (e) {
        console.warn("Scene analysis failed, using generic.");
    }

    // STEP 2: Construct the "Medical Grade" Prompt
    let finalPrompt = `Photorealistic image of ${sceneDescription}. `;

    // Mode Logic
    if (config.mode === 'SANITIZE_ONLY') {
        finalPrompt += "Keep all existing furniture and wall textures exactly as they are, but remove all trash, dirt, stains, and clutter. Make surfaces look freshly wiped and polished. ";
    } else if (config.mode === 'UPGRADE_FURNITURE') {
        finalPrompt += "Keep the room structure (walls, windows) exactly the same. REPLACE old/broken furniture with brand new, modern, clean versions in the exact same positions. Fix broken tiles or walls. ";
    } else {
        // Full Reconstruction
        finalPrompt += "TRANSFORM this into a high-tech Bio-Safety Level 4 Laboratory. Replace all surfaces with sterile white antimicrobial panels and stainless steel. Future medical aesthetic. ";
    }

    // Human Logic
    if (config.humans === 'KEEP_PROTECTED') {
        finalPrompt += "KEEP the people in the image in their EXACT positions and poses. CHANGE their clothes to professional clean protective gear (lab coats or safety vests). They must look professional. ";
    } else {
        finalPrompt += "REMOVE all people. The room should be completely empty and devoid of life. ";
    }

    // Lighting Logic
    if (config.lighting === 'CLINICAL_BLUE') {
        finalPrompt += "Lighting: Cool white clinical LED strips, slightly blue tint, no shadows. ";
    } else if (config.lighting === 'WARM') {
        finalPrompt += "Lighting: Bright natural sunlight, warm inviting atmosphere. ";
    } else {
        finalPrompt += "Lighting: Bright, neutral, high-visibility safety lighting. ";
    }

    finalPrompt += "Quality: 8k resolution, Unreal Engine 5 render, sharp focus, hyper-realistic, no blur, no distortion.";

    console.log("GENERATED PROMPT:", finalPrompt);

    // STEP 3: Generate Image (Prefer Flux via Pollinations for complex scene retention)
    try {
        const seed = Math.floor(Math.random() * 999999);
        const encodedPrompt = encodeURIComponent(finalPrompt);
        const width = 1280;
        const height = 720; 

        const url = `https://image.pollinations.ai/prompt/${encodedPrompt}?width=${width}&height=${height}&seed=${seed}&model=flux&nolog=true`;

        await new Promise(r => setTimeout(r, 2000));
        return url;
    } catch (error) {
        throw new Error("Gagal menjana simulasi.");
    }
};

