// REAL DATA PREDICTION CHART
const PredictionChart: React.FC<{ hygiene: number }> = ({ hygiene }) => {
    const [trendData, setTrendData] = useState<EpidemicTrend | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const loadData = async () => {
            try {
                const data = await fetchNationalDengueTrend();
                setTrendData(data);
            } catch (e) {
                console.error("Data fetch error", e);
            } finally {
                setLoading(false);
            }
        };
        loadData();
    }, []);

    if (loading || !trendData) {
        return <div className="p-4 bg-slate-900 border border-slate-800 rounded-lg animate-pulse h-32 flex items-center justify-center text-slate-500 text-xs">MENYAMBUNG KE PANGKALAN DATA MOH...</div>;
    }

    const maxCase = Math.max(...trendData.cases);
    const advice = getOutbreakStatus(hygiene, trendData.trend);

    return (
        <div className="bg-slate-900/80 border border-emerald-900/50 p-5 rounded-lg mt-4 backdrop-blur shadow-xl relative overflow-hidden group">
            {/* Live Indicator */}
            <div className="absolute top-3 right-3 flex items-center gap-2">
                <span className="relative flex h-2 w-2">
                  <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                  <span className="relative inline-flex rounded-full h-2 w-2 bg-red-500"></span>
                </span>
                <span className="text-[10px] font-mono-sci text-red-400 tracking-wider">LIVE DATA: KKM/MOH</span>
            </div>

            <h4 className="text-xs font-bold text-emerald-400 uppercase mb-6 flex items-center gap-2 font-sci-fi">
                📊 INTELLIGENCE: TREND DENGGI NASIONAL
            </h4>

            <div className="flex items-end gap-2 h-40 w-full px-2">
                {trendData.cases.map((val, i) => {
                    const heightPercent = (val / maxCase) * 80;
                    return (
                        <div key={i} className="flex-1 flex flex-col items-center gap-2 group/bar">
                            <span className="text-[9px] text-white font-mono-sci opacity-0 group-hover/bar:opacity-100 transition-opacity absolute -mt-4 bg-black px-1 rounded">{val}</span>
                            <div className="w-full bg-slate-800/50 rounded-t relative overflow-hidden flex flex-col justify-end border-b border-slate-700" style={{ height: '100%' }}>
                                 <div 
                                    className={`w-full transition-all duration-1000 ${trendData.trend === 'RISING' ? 'bg-gradient-to-t from-red-900 to-red-500' : 'bg-gradient-to-t from-emerald-900 to-emerald-500'}`}
                                    style={{ height: `${heightPercent}%` }}
                                 ></div>
                            </div>
                            <span className="text-[9px] text-slate-500 font-mono-sci uppercase">{trendData.weeks[i]}</span>
                        </div>
                    );
                })}
            </div>

            <div className={`mt-4 p-3 rounded border ${hygiene < 3 ? 'bg-red-950/30 border-red-500/30' : 'bg-emerald-950/30 border-emerald-500/30'}`}>
                 <p className="text-xs text-white italic font-serif leading-relaxed">
                    "{advice}"
                </p>
            </div>
        </div>
    )
}

