export const AnalysisResults: React.FC<AnalysisResultsProps> = ({ result, imageSrc, savedSimulationImage, onSaveSimulation }) => {
  const [activeRisk, setActiveRisk] = useState<RiskDetection | null>(null);
  const [currentRisks, setCurrentRisks] = useState<RiskDetection[]>(result.risks);
  const [isSavageMode, setIsSavageMode] = useState(false);
  const [showReportPreview, setShowReportPreview] = useState(false);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [userQuestion, setUserQuestion] = useState("");
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [manualBox, setManualBox] = useState<BoundingBox | null>(null);
  const [showManualModal, setShowManualModal] = useState(false);
  const [manualContext, setManualContext] = useState("");
  const [isProcessingManual, setIsProcessingManual] = useState(false);
  const [isCleaning, setIsCleaning] = useState(false);
  const [cleanImage, setCleanImage] = useState<string | null>(savedSimulationImage || null);
  const [showCleanModal, setShowCleanModal] = useState(false);
  const [showConfigModal, setShowConfigModal] = useState(false);
  const [showLegalModal, setShowLegalModal] = useState(false); // New Legal Modal

  const { language, t } = useLanguage();

  useEffect(() => { setCleanImage(savedSimulationImage || null); }, [savedSimulationImage]);
  useEffect(() => { if (currentRisks && currentRisks.length > 0 && !activeRisk) setActiveRisk(currentRisks[0]); }, [currentRisks]);

  const handleRiskChange = (risk: RiskDetection) => {
    setActiveRisk(risk);
    if (window.innerWidth < 1024) setTimeout(() => document.getElementById('details-panel')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 100);
  }

  const bioRisks = currentRisks.filter(r => r.category === 'VECTOR' || r.category === 'HYGIENE');
  const safetyRisks = currentRisks.filter(r => r.category === 'SAFETY');
  const getRiskIndex = (risk: RiskDetection) => currentRisks.findIndex(r => r.id === risk.id) + 1;

  const handleRegionDrawn = (box: BoundingBox) => {
    setManualBox(box);
    setShowManualModal(true);
    setIsEditing(false);
  };

  const submitManualAnalysis = async () => {
    if (!manualBox || !manualContext) return;
    setIsProcessingManual(true);
    try {
        const cleanBase64 = imageSrc.split(',')[1] || imageSrc;
        const mimeType = imageSrc.split(';')[0].split(':')[1] || 'image/jpeg';
        const newRisk = await analyzeManualRegion(cleanBase64, mimeType, manualBox, manualContext, language);
        setCurrentRisks([newRisk, ...currentRisks]);
        setActiveRisk(newRisk);
        setShowManualModal(false);
        setManualContext("");
        setManualBox(null);
    } catch (e) {
        alert("Gagal memproses.");
    } finally {
        setIsProcessingManual(false);
    }
  };

  const cancelManualMode = () => { setIsEditing(false); setShowManualModal(false); setManualBox(null); setManualContext(""); };
  const handleOpenSimulation = () => { cleanImage ? setShowCleanModal(true) : setShowConfigModal(true); };

  const startSimulation = async (config: any) => {
      setShowConfigModal(false);
      setIsCleaning(true);
      try {
          const base64Data = imageSrc.split(',')[1];
          const mimeType = imageSrc.split(';')[0].split(':')[1] || 'image/jpeg';
          const generatedImage = await generateCleanSimulation(base64Data, mimeType, config);
          setCleanImage(generatedImage);
          onSaveSimulation(generatedImage);
          setShowCleanModal(true);
      } catch (error: any) {
          alert(`Simulasi Gagal: ${error.message}`);
      } finally {
          setIsCleaning(false);
      }
  };

  const handleAskAI = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userQuestion.trim() || !activeRisk) return;
    const newMsg: ChatMessage = { role: 'user', text: userQuestion };
    setChatMessages(prev => [...prev, newMsg]);
    setUserQuestion("");
    setIsChatLoading(true);
    try {
      const response = await askRiskFollowUp(activeRisk, newMsg.text, language);
      setChatMessages(prev => [...prev, { role: 'model', text: response }]);
    } catch (error) {
      setChatMessages(prev => [...prev, { role: 'model', text: "Error contacting AI." }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const handlePrint = () => window.print();
  const generateYoutubeLink = (risk: RiskDetection) => `https://www.youtube.com/results?search_query=${encodeURIComponent(`microscope view ${risk.agent} ${risk.label}`)}`;

  // PROFESSIONAL REPORT VIEW - STRICT WHITE BACKGROUND GLOBAL OVERRIDE
  if (showReportPreview) {
    const refNo = `KKM/PKP/2025/${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`;
    const today = new Date().toLocaleDateString('ms-MY', { day: 'numeric', month: 'long', year: 'numeric' });

    return (
      <div id="printable-report-container" className="fixed inset-0 z-[200] bg-white text-black overflow-y-auto flex flex-col items-center min-h-screen w-full">

         {/* UI Header (Hidden on Print) - LIGHT THEME */}
         <div className="no-print-ui sticky top-0 z-50 w-full bg-white text-black p-4 shadow-md flex justify-between items-center border-b border-gray-200">
            <h2 className="font-bold text-lg flex items-center gap-2"><span className="text-emerald-600">📄</span> {t('btn_view_report')}</h2>
            <div className="flex gap-3">
               <button onClick={() => setShowReportPreview(false)} className="px-4 py-2 rounded border border-gray-400 hover:bg-gray-100 transition text-sm font-bold text-black">TUTUP</button>
               <button onClick={handlePrint} className="bg-emerald-600 hover:bg-emerald-500 px-6 py-2 rounded font-bold shadow-lg text-white flex items-center gap-2">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4"><path strokeLinecap="round" strokeLinejoin="round" d="M6.72 13.829c-.24.03-.48.062-.72.096m.72-.096a42.415 42.415 0 0110.56 0m-10.56 0L6.34 18m10.94-4.171c.24.03.48.062.72.096m-.72-.096L17.66 18m0 0l.229 2.523a1.125 1.125 0 01-1.12 1.227H7.231c-.662 0-1.18-.568-1.12-1.227L6.34 18m11.318 0h1.091A2.25 2.25 0 0021 15.75V9.456c0-1.081-.768-2.015-1.837-2.175a48.055 48.055 0 00-1.913-.247M6.34 18H5.25A2.25 2.25 0 013 15.75V9.456c0-1.081.768-2.015 1.837-2.175a48.041 48.041 0 001.913-.247m10.5 0a48.536 48.536 0 00-10.5 0m10.5 0V3.375c0-.621-.504-1.125-1.125-1.125h-8.25c-.621 0-1.125.504-1.125 1.125v3.659M18 10.5h.008v.008H18V10.5zm-3 0h.008v.008H15V10.5z" /></svg>
                 CETAK / SIMPAN PDF
               </button>
            </div>
         </div>

         {/* A4 Paper Container - STRICT WHITE BG & BLACK TEXT */}
         <div id="printable-report" className="w-full max-w-[210mm] bg-white min-h-screen shadow-2xl my-8 p-12 text-black box-border relative print:p-0 print:m-0 print:shadow-none print:w-full font-serif border border-gray-200 print:border-none">

            {/* OFFICIAL LETTERHEAD */}
            <div className="flex items-center justify-between border-b-2 border-black pb-4 mb-6">
                <img src="https://upload.wikimedia.org/wikipedia/commons/2/26/Coat_of_arms_of_Malaysia.svg" className="h-28 w-auto" alt="Jata Negara" />
                <div className="text-right font-sans">
                    <h1 className="text-xl font-bold uppercase tracking-wider text-black">KEMENTERIAN KESIHATAN MALAYSIA</h1>
                    <p className="text-sm text-black">Pejabat Kesihatan Daerah (Simulasi)</p>
                    <p className="text-xs mt-1 text-black">Laporan Pemeriksaan Sanitasi & Kawalan Vektor</p>
                </div>
            </div>

            {/* REFERENCE & DATE */}
            <div className="flex justify-between text-sm mb-6 text-black">
                <div>
                   <p><span className="font-bold">Rujukan:</span> {refNo}</p>
                   <p><span className="font-bold">Tarikh:</span> {today}</p>
                </div>
                <div className="text-right">
                   <p className="uppercase font-bold border border-black px-2 inline-block">SULIT & PERSENDIRIAN</p>
                </div>
            </div>

            {/* RECIPIENT */}
            <div className="mb-6 text-sm text-black">
                <p>Kepada:</p>
                <p>Pemilik / Penghuni / Pemegang Lesen,</p>
                <p className="mt-1">Tuan/Puan,</p>
            </div>

            {/* TITLE */}
            <div className="mb-6 text-black">
                <h2 className="text-lg font-bold underline uppercase text-center font-sans">NOTIS PEMERIKSAAN DAN ARAHAN PEMBERSIHAN PREMIS</h2>
                <p className="text-xs text-center italic mt-1">(Seksyen 8, Akta Pemusnahan Serangga Pembawa Penyakit 1975)</p>
            </div>

            {/* CONTENT START */}
            <p className="text-sm text-justify mb-4 leading-relaxed text-black">
               Pemeriksaan yang telah dijalankan pada tarikh di atas mendapati premis tuan/puan berada dalam keadaan yang boleh membiakkan serangga pembawa penyakit atau mendatangkan kacauganggu awam. Berikut adalah perincian penemuan:
            </p>

            {/* EVIDENCE IMAGE */}
            <div className="mb-6 border border-black p-1 flex justify-center avoid-break">
               <img src={imageSrc} className="max-h-[250px] object-contain" alt="Bukti Premis" />
            </div>

            {/* SCORES TABLE - CLEAN WHITE */}
            <div className="mb-6 avoid-break">
                <h3 className="font-bold text-sm mb-2 uppercase underline text-black">1. RINGKASAN PEMARKAHAN</h3>
                <table className="w-full border-collapse border border-black text-sm text-black">
                   <thead>
                      <tr>
                         <th className="border border-black p-2 text-left w-1/3 text-black">Kategori</th>
                         <th className="border border-black p-2 text-center w-1/3 text-black">Skor (1-5)</th>
                         <th className="border border-black p-2 text-center w-1/3 text-black">Status</th>
                      </tr>
                   </thead>
                   <tbody>
                      <tr>
                         <td className="border border-black p-2 font-bold">Kebersihan (Hygiene)</td>
                         <td className="border border-black p-2 text-center font-bold">{result.hygieneLevel}/5</td>
                         <td className="border border-black p-2 text-center">
                            {result.hygieneLevel < 3 
                              ? <span className="text-red-600 font-bold">GAGAL (KRITIKAL)</span> 
                              : result.hygieneLevel === 3 
                                ? 'PERLU PENAMBAHBAIKAN' 
                                : 'MEMUASKAN'
                            }
                         </td>
                      </tr>
                      <tr>
                         <td className="border border-black p-2 font-bold">Keselamatan (Safety)</td>
                         <td className="border border-black p-2 text-center font-bold">{result.safetyLevel || result.hygieneLevel}/5</td>
                         <td className="border border-black p-2 text-center">
                            {result.safetyLevel < 3 ? 'BERISIKO' : 'TERKAWAL'}
                         </td>
                      </tr>
                   </tbody>
                </table>
            </div>

            {/* DETAILED FINDINGS - JUSTIFIED TEXT */}
            <div className="mb-6 avoid-break">
                <h3 className="font-bold text-sm mb-2 uppercase underline text-black">2. ULASAN PEGAWAI PEMERIKSA</h3>
                <div className="text-justify text-sm leading-relaxed whitespace-pre-wrap border-l-2 border-black pl-4 text-black">
                    {result.generalAdvice}
                </div>
            </div>

            {/* SPECIFIC VIOLATIONS - EMPHASIS ONLY ON LABELS */}
            <div className="mb-6 avoid-break">
                <h3 className="font-bold text-sm mb-2 uppercase underline text-black">3. SENARAI KESALAHAN SPESIFIK</h3>
                <ul className="list-decimal pl-5 text-sm space-y-3 text-black">
                   {currentRisks.map((risk, i) => (
                      <li key={i} className="pl-2">
                         <span className="font-bold text-red-700 uppercase">{risk.label}</span>
                         <span className="text-xs uppercase ml-2 px-1 border border-black rounded text-black font-sans">{risk.category}</span>
                         <div className="mt-1">
                            <span className="font-bold text-xs">Punca/Ejen:</span> <span className="italic">{risk.agent}</span>
                         </div>
                         <div className="mt-1">
                            <span className="font-bold text-xs">Arahan:</span> {risk.solution}
                         </div>
                      </li>
                   ))}
                </ul>
            </div>

            {/* LEGAL SECTION - BOLD WARNING */}
            <div className="mb-10 avoid-break border-t border-b border-black py-4 text-black">
               <h3 className="font-bold text-sm mb-2 uppercase underline">4. IMPLIKASI PERUNDANGAN</h3>
               <p className="text-sm text-justify">
                  Sila ambil perhatian bahawa kegagalan mematuhi arahan ini adalah satu kesalahan di bawah <strong>{result.legalSection || "Seksyen 8, Akta Pemusnahan Serangga Pembawa Penyakit 1975"}</strong>.
               </p>
               <p className="text-sm text-justify mt-2 font-bold">
                  AMARAN: Jika disabitkan kesalahan, tuan/puan boleh didenda tidak melebihi RM10,000.00 atau dipenjarakan selama tempoh tidak melebihi 2 tahun atau kedua-duanya sekali.
               </p>
            </div>

            {/* SIGNATURES */}
            <div className="grid grid-cols-2 gap-12 mt-8 avoid-break text-black">
               <div className="text-center">
                  <div className="h-24"></div> {/* Space for signature */}
                  <div className="border-t border-black w-3/4 mx-auto mb-2"></div>
                  <p className="font-bold text-sm uppercase">Tandatangan Pegawai</p>
                  <p className="text-xs">PKAK MAIL (PPKP U29)</p>
               </div>
               <div className="text-center">
                  <div className="h-24"></div>
                  <div className="border-t border-black w-3/4 mx-auto mb-2"></div>
                  <p className="font-bold text-sm uppercase">Tandatangan Penerima</p>
                  <p className="text-xs">Nama: ...........................................</p>
                  <p className="text-xs">No. KP: ........................................</p>
               </div>
            </div>

            <div className="text-center text-[10px] mt-12 pt-4 font-sans text-black">
               Cetakan Komputer. Tandatangan tidak diperlukan untuk notis awalan digital. Dijana oleh VectorGuard AI System.
            </div>

         </div>
      </div>
    );
  }

  // MANUAL TARGETING MODAL
  if (showManualModal) {
     return (
        <div className="fixed inset-0 z-[200] bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-slate-900 border border-emerald-500 rounded-xl p-6 w-full max-w-sm shadow-2xl animate-fade-in-up">
                <h3 className="text-lg font-sci-fi font-bold text-white mb-4"><span className="text-emerald-400">🎯 MANUAL TARGETING</span></h3>
                <textarea value={manualContext} onChange={(e) => setManualContext(e.target.value)} placeholder="e.g. Look at the dark spot..." rows={3} className="w-full bg-slate-950 border border-slate-700 rounded p-3 text-white text-sm outline-none mb-4" />
                <div className="flex gap-2">
                    <button onClick={cancelManualMode} disabled={isProcessingManual} className="flex-1 py-2 bg-slate-800 text-slate-300 rounded">CANCEL</button>
                    <button onClick={submitManualAnalysis} disabled={!manualContext.trim() || isProcessingManual} className="flex-1 py-2 bg-emerald-600 text-white rounded font-bold">{isProcessingManual ? "SCANNING..." : "ANALYZE"}</button>
                </div>
            </div>
        </div>
     )
  }

  if (!activeRisk) return null;

  return (
    <div className="animate-fade-in pb-20 no-print">
      <SimulationConfigModal isOpen={showConfigModal} onClose={() => setShowConfigModal(false)} onStart={startSimulation} />
      <SimulationResultModal isOpen={showCleanModal} onClose={() => setShowCleanModal(false)} originalImage={imageSrc} generatedImage={cleanImage || ""} />
      <LegalNoticeModal isOpen={showLegalModal} onClose={() => setShowLegalModal(false)} result={result} />

      <div className="flex flex-wrap gap-3 justify-between items-center mb-4 md:mb-6 no-print">
         <div className="flex gap-2">
            <button onClick={() => setIsEditing(!isEditing)} className={`flex items-center gap-2 px-3 py-1.5 md:px-4 md:py-2 rounded text-xs md:text-sm font-bold uppercase tracking-wider transition-all border ${isEditing ? 'bg-red-600 text-white border-red-500 animate-pulse' : 'bg-slate-800 text-slate-300 border-slate-600'}`}>
                {isEditing ? '🔴 TARGETING' : `🎯 ${t('btn_manual_scan')}`}
            </button>
            <button onClick={handleOpenSimulation} disabled={isCleaning} className={`flex items-center gap-2 px-3 py-1.5 md:px-4 md:py-2 rounded text-xs md:text-sm font-bold uppercase tracking-wider transition-all border border-cyan-500/50 hover:bg-cyan-900/30 text-cyan-400 disabled:opacity-50`}>
                {isCleaning ? <span className="animate-pulse">SIMULATING...</span> : <>✨ {t('btn_simulation')}</>}
            </button>
            {/* NEW LEGAL BUTTON */}
            {(result.hygieneLevel < 3) && (
                <button onClick={() => setShowLegalModal(true)} className="flex items-center gap-2 px-3 py-1.5 md:px-4 md:py-2 rounded text-xs md:text-sm font-bold uppercase tracking-wider transition-all border border-red-500/50 hover:bg-red-900/30 text-red-400">
                    📜 JANA NOTIS
                </button>
            )}
         </div>
         <div className="flex items-center gap-2 md:gap-4">
            <button onClick={() => setShowReportPreview(true)} className="flex items-center gap-2 bg-emerald-700 hover:bg-emerald-600 text-white px-4 py-2 rounded text-xs md:text-sm font-bold shadow-lg border border-emerald-500 transition-all">
               📄 {t('btn_view_report')}
            </button>
            <div className="flex items-center gap-2 bg-slate-900 rounded-full p-1 border border-slate-700">
               <button onClick={() => setIsSavageMode(false)} className={`px-3 py-1 rounded-full text-[10px] font-bold ${!isSavageMode ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}>{t('tab_official')}</button>
               <button onClick={() => setIsSavageMode(true)} className={`px-3 py-1 rounded-full text-[10px] font-bold ${isSavageMode ? 'bg-red-600 text-white' : 'text-slate-500'}`}>{t('tab_savage')}</button>
            </div>
         </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 md:gap-6">
        <div className="lg:col-span-7 flex flex-col gap-4">
           <div className="relative rounded-xl overflow-hidden border border-slate-700 bg-slate-900 group">
              <ImageAnnotator imageSrc={imageSrc} risks={currentRisks} onRiskSelect={handleRiskChange} selectedId={activeRisk.id} isEditing={isEditing} onRegionDrawn={handleRegionDrawn} />
              <div className="absolute bottom-4 right-4 flex items-center gap-2 bg-slate-900/90 backdrop-blur border border-slate-600 px-3 py-2 rounded-lg z-40 shadow-xl">
                 <div className="flex flex-col items-end">
                    <div className="flex items-center gap-2 mb-1">
                        <span className="text-[9px] text-slate-400 font-mono-sci uppercase">HYGIENE</span>
                        <div className={`w-6 h-6 rounded-full flex items-center justify-center font-bold text-xs border ${result.hygieneLevel >= 4 ? 'border-emerald-500 text-emerald-400' : 'border-red-500 text-red-500'}`}>{result.hygieneLevel}</div>
                    </div>
                    <div className="flex items-center gap-2">
                        <span className="text-[9px] text-slate-400 font-mono-sci uppercase">SAFETY</span>
                        <div className={`w-6 h-6 rounded-full flex items-center justify-center font-bold text-xs border ${result.safetyLevel >= 4 ? 'border-blue-500 text-blue-400' : 'border-orange-500 text-orange-500'}`}>{result.safetyLevel || result.hygieneLevel}</div>
                    </div>
                 </div>
              </div>
           </div>

           {/* Prediction Chart Area - CONNECTED TO REAL DATA */}
           <PredictionChart hygiene={result.hygieneLevel} />

           <div className="grid grid-cols-1 gap-4">
              {bioRisks.length > 0 && (
                <div className="bg-slate-900/50 border border-slate-800 rounded-lg p-3 md:p-4">
                   <h3 className="text-xs text-slate-500 font-mono-sci uppercase mb-3 flex items-center gap-2"><span className="w-2 h-2 bg-amber-500 rounded-full"></span> {t('risk_vector')}</h3>
                   <div className="space-y-2 max-h-[300px] overflow-y-auto custom-scrollbar">
                      {bioRisks.map((risk) => <RiskListItem key={risk.id} risk={risk} index={getRiskIndex(risk)} activeId={activeRisk.id} onClick={handleRiskChange} />)}
                   </div>
                </div>
              )}
              {safetyRisks.length > 0 && (
                <div className="bg-slate-900/50 border border-slate-800 rounded-lg p-3 md:p-4">
                   <h3 className="text-xs text-slate-500 font-mono-sci uppercase mb-3 flex items-center gap-2"><span className="w-2 h-2 bg-indigo-500 rounded-full"></span> {t('risk_safety')}</h3>
                   <div className="space-y-2 max-h-[300px] overflow-y-auto custom-scrollbar">
                      {safetyRisks.map((risk) => <RiskListItem key={risk.id} risk={risk} index={getRiskIndex(risk)} activeId={activeRisk.id} onClick={handleRiskChange} />)}
                   </div>
                </div>
              )}
           </div>
        </div>

        <div id="details-panel" className="lg:col-span-5 flex flex-col h-full gap-4">
            <DualScoreCard hygieneLevel={result.hygieneLevel} safetyLevel={result.safetyLevel} isSavage={isSavageMode} />
            <div className={`relative flex-1 bg-slate-900/90 border border-slate-700 rounded-xl p-6 md:p-8 backdrop-blur-md shadow-2xl overflow-hidden flex flex-col transition-all duration-500`}>
                <div className="relative z-10 flex-1 flex flex-col">
                    <div className="mb-6 md:mb-8 border-b border-slate-700/50 pb-6">
                        <div className="flex items-center gap-3 mb-3">
                            <span className={`px-2 py-0.5 rounded text-[10px] md:text-xs font-bold font-mono-sci uppercase tracking-widest ${activeRisk.category === 'HYGIENE' ? 'bg-amber-500 text-black' : activeRisk.category === 'SAFETY' ? 'bg-indigo-500 text-white' : 'bg-red-600 text-white'}`}>{activeRisk.category} THREAT</span>
                            <span className="text-slate-500 text-[10px] md:text-xs font-mono-sci">#{getRiskIndex(activeRisk).toString().padStart(2, '0')}</span>
                        </div>
                        <h2 className="text-2xl md:text-3xl lg:text-4xl font-sci-fi font-bold text-white mb-2 leading-tight break-words">{activeRisk.label}</h2>
                        <div className="mt-2"><h3 className="text-slate-400 text-[10px] md:text-xs font-mono-sci tracking-widest uppercase mb-1">Identified Agent</h3><p className="text-lg md:text-xl lg:text-2xl text-emerald-400 font-mono-sci italic break-words leading-tight">{activeRisk.agent}</p></div>
                    </div>
                    <div className="flex-1 overflow-y-auto custom-scrollbar space-y-6 md:space-y-8 pr-2">
                        <div><h4 className="text-emerald-500 font-bold text-xs font-sci-fi uppercase mb-2 flex items-center gap-2">ANALYSIS</h4><p className="text-slate-300 text-sm md:text-base leading-relaxed font-light">{activeRisk.description}</p></div>
                        <div className={`p-4 md:p-5 rounded-lg border relative overflow-hidden transition-colors duration-500 ${isSavageMode ? 'bg-red-900/10 border-red-500/30' : 'bg-emerald-900/10 border-emerald-500/30'}`}>
                             <h4 className={`font-bold text-xs font-sci-fi uppercase mb-3 flex items-center gap-2 ${isSavageMode ? 'text-red-400' : 'text-emerald-400'}`}>{isSavageMode ? t('card_savage_verdict') : t('card_recommendation')}</h4>
                             <div className="text-sm md:text-base text-slate-200 leading-relaxed italic">{isSavageMode ? `"${result.savageCommentary || 'Disaster.'}"` : activeRisk.solution}</div>
                        </div>
