const getRiskColorParams = (category: RiskCategory) => {
  switch (category) {
    case 'HYGIENE': return { 
      border: 'border-amber-500', text: 'text-amber-400', bg: 'bg-amber-900/40', 
      shadow: 'shadow-[0_0_15px_rgba(245,158,11,0.3)]', badge: 'bg-amber-500 text-black', icon: '☣' 
