    case 'SAFETY': return { 
      border: 'border-indigo-500', text: 'text-indigo-400', bg: 'bg-indigo-900/40', 
      shadow: 'shadow-[0_0_15px_rgba(99,102,241,0.5)]', badge: 'bg-indigo-500 text-white', icon: '⚠️' 
    };
