  }
};

const formatTextToHtml = (text: string) => {
    if (!text) return "";
    let formatted = text
        .replace(/\*\*(.*?)\*\*/g, '<b>$1</b>') // Bold
        .replace(/\n/g, '<br/>'); // Newlines
    return formatted;
};

