                          <span className={`text-[8px] px-1 rounded border ${result.sensitivityUsed === 'EXTREME' ? 'border-red-500 text-red-400' : result.sensitivityUsed === 'HIGH' ? 'border-orange-500 text-orange-400' : 'border-slate-500 text-slate-400'}`}>
