const SimulationResultModal: React.FC<{ isOpen: boolean, onClose: () => void, originalImage: string, generatedImage: string }> = ({ isOpen, onClose, originalImage, generatedImage }) => {
  const [sliderPos, setSliderPos] = useState(50);
  const containerRef = useRef<HTMLDivElement>(null);
  const isDragging = useRef(false);

  const handleMove = (clientX: number) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
    setSliderPos(Math.max(0, Math.min(100, (x / rect.width) * 100)));
  };

  const onStart = (clientX: number) => { isDragging.current = true; handleMove(clientX); };
  const onEnd = () => { isDragging.current = false; };
  const onMove = (clientX: number) => { if (isDragging.current) handleMove(clientX); };

  useEffect(() => {
      const handleUp = () => isDragging.current = false;
      document.addEventListener('mouseup', handleUp);
      document.addEventListener('touchend', handleUp);
      return () => { document.removeEventListener('mouseup', handleUp); document.removeEventListener('touchend', handleUp); };
  }, []);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[180] bg-black/95 backdrop-blur-md flex items-center justify-center p-4 no-print">
        <div className="bg-slate-900 border border-cyan-500 rounded-xl w-full max-w-5xl h-[85vh] flex flex-col overflow-hidden">
             <div className="p-4 border-b border-slate-700 flex justify-between items-center bg-slate-950">
                 <h3 className="text-lg font-sci-fi font-bold text-cyan-400">✨ SIMULATION COMPLETE</h3>
                 <button onClick={onClose} className="text-white">✕</button>
             </div>
             <div className="flex-1 relative bg-black/50 overflow-hidden flex items-center justify-center p-4">
                 <div 
                    ref={containerRef}
                    className="relative w-full h-full max-h-full aspect-video border border-slate-700 rounded overflow-hidden cursor-ew-resize"
                    onMouseDown={(e) => onStart(e.clientX)}
                    onTouchStart={(e) => onStart(e.touches[0].clientX)}
                    onMouseMove={(e) => onMove(e.clientX)}
                    onTouchMove={(e) => onMove(e.touches[0].clientX)}
                 >
                    <img src={generatedImage} className="absolute inset-0 w-full h-full object-contain bg-slate-900" />
                    <div className="absolute inset-0 bg-slate-900 overflow-hidden" style={{ clipPath: `inset(0 ${100 - sliderPos}% 0 0)` }}>
                        <img src={originalImage} className="absolute inset-0 w-full h-full object-contain" />
                    </div>
                    <div className="absolute top-0 bottom-0 w-1 bg-white cursor-ew-resize z-20 shadow-[0_0_10px_black]" style={{ left: `${sliderPos}%` }}>
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 w-8 h-8 bg-white rounded-full flex items-center justify-center shadow-lg border-2 border-cyan-500">↔</div>
                    </div>
                 </div>
             </div>
        </div>
    </div>
  );
};

// UPDATED REAL DATA PREDICTION CHART (VERTICAL HISTOGRAM)
const PredictionChart: React.FC<{ hygiene: number }> = ({ hygiene }) => {
    const [trendData, setTrendData] = useState<EpidemicTrend | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const loadData = async () => {
            try {
                const data = await fetchNationalDengueTrend();
                setTrendData(data);
            } catch (e) {
                console.error("Data fetch error", e);
            } finally {
                setLoading(false);
            }
        };
        loadData();
    }, []);

    if (loading || !trendData) {
        return <div className="p-4 bg-slate-900 border border-slate-800 rounded-lg animate-pulse h-48 flex items-center justify-center text-slate-500 text-xs">MENYAMBUNG KE PANGKALAN DATA MOH...</div>;
    }

    const maxCase = Math.max(...trendData.cases);
    // Add slightly more to max for visual headroom
    const chartMax = Math.ceil(maxCase * 1.1);
    const advice = getOutbreakStatus(hygiene, trendData.trend);

    return (
        <div className="bg-slate-900/80 border border-emerald-900/50 p-5 rounded-lg mt-4 backdrop-blur shadow-xl relative overflow-hidden group">
            {/* Live Indicator */}
            <div className="absolute top-3 right-3 flex items-center gap-2">
                <span className="relative flex h-2 w-2">
                  <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                  <span className="relative inline-flex rounded-full h-2 w-2 bg-red-500"></span>
                </span>
                <span className="text-[10px] font-mono-sci text-red-400 tracking-wider">LIVE DATA: KKM/MOH</span>
            </div>

            <h4 className="text-xs font-bold text-emerald-400 uppercase mb-4 flex items-center gap-2 font-sci-fi">
                📊 INTELLIGENCE: TREND DENGGI NASIONAL
            </h4>

            <div className="h-48 w-full flex items-end gap-2 md:gap-4 px-2 pt-6 pb-0 border-b border-l border-slate-700 relative">

                {/* Y-Axis Grid Lines (Optional visual guide) */}
                <div className="absolute inset-0 pointer-events-none flex flex-col justify-between pl-0 pb-0 opacity-20 z-0">
                    <div className="border-t border-slate-400 w-full h-0"></div>
                    <div className="border-t border-slate-400 w-full h-0"></div>
                    <div className="border-t border-slate-400 w-full h-0"></div>
                    <div className="border-t border-slate-400 w-full h-0"></div>
                </div>

                {trendData.cases.map((val, i) => {
                    const heightPercent = (val / chartMax) * 100;
                    return (
                        <div key={i} className="flex-1 flex flex-col justify-end h-full z-10 relative group/bar">

                            {/* Visible Number Label */}
                            <div className="w-full text-center mb-1 transition-transform duration-300 group-hover/bar:-translate-y-1">
                                <span className="bg-slate-950/80 text-white text-[9px] md:text-[10px] font-bold px-1.5 py-0.5 rounded border border-slate-700 font-mono-sci">
                                    {val}
                                </span>
                            </div>

                            {/* The Bar */}
                            <div 
                                className={`w-full rounded-t-sm transition-all duration-1000 ease-out border-t border-x border-white/10 ${
                                    trendData.trend === 'RISING' 
                                    ? 'bg-gradient-to-t from-red-900/80 to-red-500' 
                                    : 'bg-gradient-to-t from-emerald-900/80 to-emerald-500'
                                }`}
                                style={{ height: `${heightPercent}%` }}
                            >
                                {/* Shine effect */}
                                <div className="w-full h-[1px] bg-white/30"></div>
                            </div>

                            {/* X-Axis Label */}
                            <div className="absolute -bottom-6 left-0 right-0 text-center">
                                <span className="text-[9px] text-slate-400 font-mono-sci uppercase">{trendData.weeks[i]}</span>
                            </div>
                        </div>
                    );
                })}
            </div>

            <div className={`mt-8 p-3 rounded border flex items-start gap-3 ${hygiene < 3 ? 'bg-red-950/30 border-red-500/30' : 'bg-emerald-950/30 border-emerald-500/30'}`}>
                <div className="mt-0.5 text-lg">💡</div>
                <p className="text-xs text-slate-200 italic font-serif leading-relaxed">
                    "{advice}"
                </p>
