                  >
                    STANDARD
                  </button>
                  <button 
                    onClick={() => setSensitivity('HIGH')}
                    className={`text-xs font-bold py-2 rounded transition-all ${sensitivity === 'HIGH' ? 'bg-orange-600 text-white shadow-lg' : 'bg-slate-800 text-slate-500 hover:bg-slate-700'}`}
                  >
                    HIGH
                  </button>
                  <button 
                    onClick={() => setSensitivity('EXTREME')}
                    className={`text-xs font-bold py-2 rounded transition-all ${sensitivity === 'EXTREME' ? 'bg-red-600 text-white shadow-lg animate-pulse' : 'bg-slate-800 text-slate-500 hover:bg-slate-700'}`}
                  >
                    EXTREME
                  </button>
               </div>
               <p className="text-[10px] text-slate-500 mt-2 italic">
