};

const compressImage = (base64Str: string, maxWidth = 1024, quality = 0.7): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = `data:image/jpeg;base64,${base64Str}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let width = img.width;
            let height = img.height;
            if (width > maxWidth) {
                height = Math.round((height * maxWidth) / width);
                width = maxWidth;
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            resolve(canvas.toDataURL('image/jpeg', quality).split(',')[1]);
        };
        img.onerror = () => resolve(base64Str); 
    });
};

// Retry utility
const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> => {
    try {
        return await fn();
    } catch (error: any) {
        const msg = error.message || "";
        const isQuotaError = msg.includes("429") || msg.includes("503");
        if (isQuotaError && retries > 0) {
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(fn, retries - 1, delay * 2);
        }
        throw error;
    }
};

/**
 * Smart Analysis Function
 * UPDATED: Includes Sensitivity Level for OSH strictness AND new KKM Mode
 */
export const analyzeLandscape = async (base64Image: string, mimeType: string, mode: 'FAST' | 'DETAILED' = 'DETAILED', language: string = 'ms', sensitivity: SensitivityLevel = 'STANDARD', analysisMode: AnalysisMode = 'VECTOR_CONTROL'): Promise<AnalysisResponse> => {
  const langMap: Record<string, string> = { 'ms': 'Bahasa Melayu', 'en': 'English', 'zh': 'Chinese', 'ta': 'Tamil' };
  const targetLang = langMap[language] || 'Bahasa Melayu';
  const optimizedImage = await compressImage(base64Image);

  // PRIMARY MODEL SWAPPED TO FLASH FOR UNLIMITED GENERATIONS
  const modelsToTry = ["gemini-2.5-flash", "gemini-3-pro-preview"];

  let systemInstruction = "";
  let schemaDescription = "";

  if (analysisMode === 'KKM_FOOD_STANDARD') {
      // PROMPT KHAS UNTUK STANDARD KKM (Berdasarkan imej borang)
      systemInstruction = `
        ROLE: PEGAWAI KESIHATAN PERSEKITARAN (PPKP) - AUDIT PREMIS MAKANAN.
        TASK: Lakukan pemeriksaan ketat berdasarkan format "BORANG PEMERIKSAAN PREMIS MAKANAN (KKM)".
        LANGUAGE: ${targetLang} (Formal Government Tone).

        CRITERIA (Based on KKM Format):
        A. KAWALAN PROSES (26m): Suhu masakan (>70C), Peti sejuk (<4C), Cross-contamination.
        B. BANGUNAN (7m): Lantai, dinding, siling, pencahayaan, pengudaraan.
        C. PENGENDALI MAKANAN (13m): Suntikan Tifoid, Pakaian (Apron/Topi), Kuku pendek, Tiada aksesori.
        D. PERALATAN (8m): Bersih, berfungsi, bukan kayu (papan pemotong).
        E. BEKALAN AIR (5m): Sumber air selamat.
        F. PERPARITAN (3m): Grease trap (perangkap minyak), aliran lancar.
        G. KEMUDAHAN SANITASI (6m): Tandas bersih, sabun, tisu.
        H. SAMPAH (2m): Tong bertutup, beg plastik.
        I. MAKHLUK PEROSAK (3m): Tiada lipas/tikus/lalat.
        J. PEMBERSIHAN (2m): Jadual pembersihan.
        K. PENGANGKUTAN (1m): Kenderaan bersih.
        L. DOKUMEN (1m): Notis/Lesen.
        M. RISIKO LAIN (10m): Isu kritikal lain.

        SCORING LOGIC:
        Start with 100 points. DEDUCT points (Demerit) for every violation visible in the image.

        OUTPUT JSON:
        - Return 'kkmReport' object details.
        - Also return standard 'risks' array for visual bounding boxes of violations.
      `;

      schemaDescription = `
      {
        "kkmReport": {
            "grade": "A | B | C | D | TUTUP",
            "totalScore": number,
            "totalDemerit": number,
            "sections": [
                { "code": "A", "title": "KAWALAN PROSES", "totalPoints": 26, "demeritReceived": number, "violations": ["string"] },
                { "code": "B", "title": "BANGUNAN", "totalPoints": 7, "demeritReceived": number, "violations": ["string"] },
                { "code": "C", "title": "PENGENDALI MAKANAN", "totalPoints": 13, "demeritReceived": number, "violations": ["string"] },
                { "code": "D", "title": "PERALATAN & PERKAKAS", "totalPoints": 8, "demeritReceived": number, "violations": ["string"] },
                { "code": "F", "title": "PERPARITAN & PERPAIPAN", "totalPoints": 3, "demeritReceived": number, "violations": ["string"] },
                { "code": "G", "title": "KEMUDAHAN SANITASI", "totalPoints": 6, "demeritReceived": number, "violations": ["string"] },
                { "code": "I", "title": "KAWALAN MAKHLUK PEROSAK", "totalPoints": 3, "demeritReceived": number, "violations": ["string"] }
            ],
            "summary": "string (executive summary)",
            "recommendation": "string (official order)"
        },
        "risks": [ ...standard risk structure... ],
        "hygieneLevel": number, "safetyLevel": number, "mode": "KKM_FOOD_STANDARD"
      }
      `;
  } else {
      // STANDARD VECTOR CONTROL PROMPT
      let sensitivityPrompt = "";
      if (sensitivity === 'STANDARD') {
          sensitivityPrompt = "Focus on OBVIOUS biological vectors (rats, flies, mosquitoes) and MAJOR safety hazards.";
      } else if (sensitivity === 'HIGH') {
          sensitivityPrompt = "Be STRICT. Flag minor hygiene issues. Identify OCCUPATIONAL SAFETY (OSH) risks.";
      } else if (sensitivity === 'EXTREME') {
          sensitivityPrompt = "ZERO TOLERANCE MODE. Forensic audit. Flag EVERYTHING.";
      }

      systemInstruction = `
        ROLE: SENIOR HEALTH & SAFETY INSPECTOR.
        TASK: Conduct a forensic vector and safety inspection.
        SENSITIVITY: ${sensitivity} - ${sensitivityPrompt}
        LANGUAGE: ${targetLang}.
        OUTPUT: JSON with risks, hygieneLevel, safetyLevel.
        mode: "VECTOR_CONTROL"
      `;

      schemaDescription = `Standard AnalysisResponse JSON structure`;
  }

  let lastError: any = null;

  for (const modelId of modelsToTry) {
     try {
         const response = await retryWithBackoff(async () => {
              const ai = getAIClient();
              return await ai.models.generateContent({
                model: modelId,
                contents: {
                    parts: [
                        { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, 
                        { text: `${systemInstruction} \n\n Output JSON Schema: ${schemaDescription}` }
                    ]
                }
            });
         });

         let text = response.text;
         if (!text) throw new Error("Empty response");
         text = text.replace(/```json/g, '').replace(/```/g, '');
         const jsonStartIndex = text.indexOf('{');
         const jsonEndIndex = text.lastIndexOf('}');
         if (jsonStartIndex !== -1 && jsonEndIndex !== -1) text = text.substring(jsonStartIndex, jsonEndIndex + 1);

         const parsedResult = JSON.parse(text) as AnalysisResponse;
         const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
         if (groundingChunks) parsedResult.groundingChunks = groundingChunks;
         if (parsedResult.safetyLevel === undefined) parsedResult.safetyLevel = parsedResult.hygieneLevel;

         parsedResult.sensitivityUsed = sensitivity;
         parsedResult.mode = analysisMode; // Ensure mode is passed back

         return parsedResult;

     } catch (error: any) {
         lastError = error;
         console.warn(`Model ${modelId} failed, trying next...`, error);
     }
  }
  throw lastError || new Error("AI Busy. Please try again.");
};

export const analyzeManualRegion = async (base64Image: string, mimeType: string, box: BoundingBox, userContext: string, language: string = 'ms'): Promise<RiskDetection> => {
    const optimizedImage = await compressImage(base64Image);
    const langMap: Record<string, string> = { 'ms': 'Bahasa Melayu', 'en': 'English', 'zh': 'Chinese', 'ta': 'Tamil' };
    const targetLang = langMap[language] || 'Bahasa Melayu';

    const prompt = `Region Analysis [${box.ymin}-${box.ymax}, ${box.xmin}-${box.xmax}]. Hint: "${userContext}". Output JSON RiskDetection. Lang: ${targetLang}. Ensure 'microbiology' field has a specific germ name for microscope searches.`;

    const schema = {
        type: Type.OBJECT,
        properties: {
            id: { type: Type.STRING },
            category: { type: Type.STRING, enum: ["VECTOR", "HYGIENE", "SAFETY"] },
            label: { type: Type.STRING },
            agent: { type: Type.STRING },
            disease: { type: Type.STRING },
            microbiology: { type: Type.STRING },
            statistics: { type: Type.STRING },
            description: { type: Type.STRING },
            solution: { type: Type.STRING },
            box_2d: { type: Type.OBJECT, properties: { ymin: {type:Type.NUMBER}, xmin: {type:Type.NUMBER}, ymax: {type:Type.NUMBER}, xmax: {type:Type.NUMBER} } },
            citations: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { id: {type:Type.NUMBER}, source: {type:Type.STRING}, title:{type:Type.STRING}, url:{type:Type.STRING} } } }
        }
    };

    const response = await retryWithBackoff(async () => {
        const ai = getAIClient();
        return await ai.models.generateContent({
            model: "gemini-2.5-flash", // Used Flash here too for speed
            contents: { parts: [{ inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, { text: prompt }] },
            config: { responseMimeType: "application/json", responseSchema: schema }
        });
    });

    const result = JSON.parse(response.text!);
    result.id = `manual-${Date.now()}`;
    result.box_2d = box; 
    return result;
};

export const generateCleanSimulation = async (base64Image: string, mimeType: string, config: SimulationConfig): Promise<string> => {
    const optimizedImage = await compressImage(base64Image);

    let sceneDescription = "A room.";
    try {
        const analysisPrompt = `Describe the camera angle, room layout, and key objects. Keep it factual. Ignore dirt.`;

        const descResponse = await retryWithBackoff(async () => {
             const ai = getAIClient();
             return await ai.models.generateContent({
                model: "gemini-2.5-flash",
                contents: { parts: [{ inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, { text: analysisPrompt }] }
            });
        });
        sceneDescription = descResponse.text || sceneDescription;
    } catch (e) {
        console.warn("Scene analysis failed.");
    }

    let finalPrompt = `Photorealistic image of ${sceneDescription}. `;

    if (config.mode === 'SANITIZE_ONLY') {
        finalPrompt += "Keep furniture/walls exact. Remove all trash/dirt/stains. Make surfaces polished. ";
    } else if (config.mode === 'UPGRADE_FURNITURE') {
        finalPrompt += "Keep walls/windows. Replace furniture with modern clean versions. ";
    } else {
        finalPrompt += "Transform into sterile high-tech Bio-Safety Level 4 Laboratory. White panels, stainless steel. ";
    }

    if (config.humans === 'KEEP_PROTECTED') {
        finalPrompt += "Keep people in exact positions but wear professional Hazmat/Lab coats. ";
    } else {
        finalPrompt += "Remove all people. Empty room. ";
    }

    if (config.lighting === 'CLINICAL_BLUE') finalPrompt += "Clinical cool LED lighting. ";
    else if (config.lighting === 'WARM') finalPrompt += "Warm natural sunlight. ";
    else finalPrompt += "Bright neutral lighting. ";

    finalPrompt += "8k resolution, Unreal Engine 5 render, hyper-realistic, sharp focus.";

    try {
        const seed = Math.floor(Math.random() * 999999);
        const encodedPrompt = encodeURIComponent(finalPrompt);
        const url = `https://image.pollinations.ai/prompt/${encodedPrompt}?width=1280&height=720&seed=${seed}&model=flux&nolog=true`;
        await new Promise(r => setTimeout(r, 2000));
        return url;
    } catch (error) {
        throw new Error("Gagal menjana simulasi.");
    }
};

