const LoadingDisplay: React.FC<{mode: AnalysisMode}> = ({mode}) => {
  const [progress, setProgress] = useState(0);
  const [logText, setLogText] = useState("INITIALIZING CORE...");

  useEffect(() => {
    const interval = setInterval(() => {
      setProgress((prev) => {
        if (prev >= 99) return 99;
        let increment = 0;
        if (prev < 30) increment = Math.random() * 3.5;
        else if (prev < 70) increment = Math.random() * 0.8;
        else increment = Math.random() * 1.5;
        return Math.min(prev + increment, 99.9);
      });
    }, 150);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
      if (mode === 'KKM_FOOD_STANDARD') {
          if (progress < 25) setLogText("LOADING KKM CHECKLIST (BORANG KUALITI)...");
          else if (progress < 50) setLogText("CHECKING FOOD HANDLERS & TYPHOID...");
          else if (progress < 75) setLogText("CALCULATING DEMERIT POINTS...");
          else setLogText("GENERATING GRADE & REPORT...");
      } else {
          if (progress < 25) setLogText("ESTABLISHING SECURE UPLINK...");
          else if (progress < 50) setLogText("DECODING BIO-SIGNATURES...");
          else if (progress < 75) setLogText("DETECTING VECTOR PATHOGENS...");
          else if (progress < 90) setLogText("CROSS-REFERENCING SAFETY DB...");
          else setLogText("SYNTHESIZING FINAL REPORT...");
      }
  }, [progress, mode]);

  return (
    <div className="bg-slate-900/90 border border-emerald-500/30 p-8 md:p-12 rounded-xl text-center min-h-[450px] flex flex-col items-center justify-center relative overflow-hidden backdrop-blur-xl shadow-[0_0_50px_rgba(0,0,0,0.5)]">
