<content><![CDATA[// components/ImageAnnotator.tsx
import React, { useState, useEffect } from 'react';
import { RiskDetection, RiskType } from '../types';
import { useGeminiService } from '../services/geminiService';
import { Rect } from 'react-zoom-pan-pinch';

interface ImageAnnotatorProps {
  imageUrl: string;
  risks: RiskDetection[];
  onRiskChange: (id: string, newRiskType: RiskType) => void;
  onRemoveRisk: (id: string) => void;
  selectedRiskId: string | null;
  onSelectRisk: (id: string | null) => void;
}

const ImageAnnotator: React.FC<ImageAnnotatorProps> = ({
  imageUrl,
  risks,
  onRiskChange,
  onRemoveRisk,
  selectedRiskId,
  onSelectRisk,
}) => {
  const [imageSize, setImageSize] = useState<{ width: number; height: number }>({ width: 0, height: 0 });
  const [imageLoaded, setImageLoaded] = useState(false);

  useEffect(() => {
    const img = new Image();
    img.src = imageUrl;
    img.onload = () => {
      setImageSize({ width: img.width, height: img.height });
      setImageLoaded(true);
    };
  }, [imageUrl]);

  if (!imageLoaded) {
    return <div>Loading image...</div>;
  }

  const handleRiskClick = (riskId: string) => {
    onSelectRisk(riskId === selectedRiskId ? null : riskId);
  };

  const calculateRect = (risk: RiskDetection): Rect => {
    const { x, y, width, height } = risk.boundingBox;
    return {
      x: x * imageSize.width,
      y: y * imageSize.height,
      width: width * imageSize.width,
      height: height * imageSize.height,
    };
  };

  return (
    <div style={{ position: 'relative', width: '100%', maxWidth: '100%' }}>
      <img
        src={imageUrl}
        alt="Annotated"
        style={{ width: '100%', height: 'auto', display: 'block' }}
      />
      {risks.map((risk) => {
        if (!risk.boundingBox) return null; // Skip if no bounding box

        const rect = calculateRect(risk);
        const isSelected = risk.id === selectedRiskId;

        return (
          <div
            key={risk.id}
            style={{
              position: 'absolute',
              left: rect.x,
              top: rect.y,
              width: rect.width,
              height: rect.height,
              border: isSelected ? '2px solid blue' : '2px dashed red',
              background: 'rgba(255, 0, 0, 0.2)',
              cursor: 'pointer',
            }}
            onClick={() => handleRiskClick(risk.id)}
          >
            {/* Risk Label or additional info can be added here */}
            {risk.id?.startsWith('manual') && (
              <span style={{ position: 'absolute', top: '-15px', left: '0', backgroundColor: 'white' }}>
                Manual Risk
              </span>
            )}
          </div>
        );
      })}
    </div>
  );
};

export default ImageAnnotator;
]]></content>
</xml>
```


**Implementing Robustness Checks**

