import React, { useState, useRef, useEffect } from 'react';
import { RiskDetection, BoundingBox } from '../types';

interface ImageAnnotatorProps {
  imageSrc: string;
  risks: RiskDetection[];
  onRiskSelect: (risk: RiskDetection) => void;
  selectedId?: string | null;
  isEditing?: boolean;
  onRegionDrawn?: (box: BoundingBox) => void;
}

const ImageAnnotator: React.FC<ImageAnnotatorProps> = ({ 
  imageSrc, 
  risks, 
  onRiskSelect, 
  selectedId: propSelectedId,
  isEditing = false,
  onRegionDrawn
}) => {
  const [internalSelectedId, setInternalSelectedId] = useState<string | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Drawing State
  const [isDrawing, setIsDrawing] = useState(false);
  const [startPos, setStartPos] = useState<{x: number, y: number} | null>(null);
  const [currentBox, setCurrentBox] = useState<BoundingBox | null>(null);

  useEffect(() => {
    if (propSelectedId !== undefined) {
      setInternalSelectedId(propSelectedId);
    }
  }, [propSelectedId]);

  const getStyle = (box: BoundingBox) => ({
    top: `${box.ymin / 10}%`,
    left: `${box.xmin / 10}%`,
    width: `${(box.xmax - box.xmin) / 10}%`,
    height: `${(box.ymax - box.ymin) / 10}%`,
  });

  const handleBoxClick = (e: React.MouseEvent, risk: RiskDetection) => {
    if (isEditing) return; 
    e.preventDefault();
    e.stopPropagation();
    setInternalSelectedId(risk.id);
    onRiskSelect(risk);
  };

  const activeId = propSelectedId !== undefined ? propSelectedId : internalSelectedId;

  // Manual Drawing Logic
  const getCoords = (e: React.MouseEvent | React.TouchEvent) => {
    if (!containerRef.current) return { x: 0, y: 0 };
    const rect = containerRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY;

    const x = ((clientX - rect.left) / rect.width) * 1000;
    const y = ((clientY - rect.top) / rect.height) * 1000;
    return { x, y };
  };

  const handleMouseDown = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isEditing) return;
    setIsDrawing(true);
    const coords = getCoords(e);
    setStartPos(coords);
    setCurrentBox({ ymin: coords.y, xmin: coords.x, ymax: coords.y, xmax: coords.x });
  };

  const handleMouseMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDrawing || !startPos || !isEditing) return;
    const current = getCoords(e);

    const ymin = Math.min(startPos.y, current.y);
    const xmin = Math.min(startPos.x, current.x);
    const ymax = Math.max(startPos.y, current.y);
    const xmax = Math.max(startPos.x, current.x);

    setCurrentBox({ ymin, xmin, ymax, xmax });
  };

  const handleMouseUp = () => {
    if (!isDrawing || !currentBox || !isEditing) return;
    setIsDrawing(false);
    if ((currentBox.xmax - currentBox.xmin) > 20 && (currentBox.ymax - currentBox.ymin) > 20) {
        onRegionDrawn?.(currentBox);
    }
    setStartPos(null);
    setCurrentBox(null);
  };

  return (
    <div 
      className={`relative w-full rounded bg-black group shadow-2xl border border-slate-800 ${isEditing ? 'cursor-crosshair touch-none' : 'cursor-default touch-pan-y'}`} 
      ref={containerRef}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      onTouchStart={handleMouseDown}
      onTouchMove={handleMouseMove}
      onTouchEnd={handleMouseUp}
    >
      <div className="overflow-hidden rounded relative">
          <img src={imageSrc} alt="Analyzed" className="w-full h-auto object-contain block select-none opacity-90 relative z-10" />
          <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent pointer-events-none z-20"></div>
          <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-10 pointer-events-none mix-blend-overlay z-20"></div>
      </div>

      {isEditing && (
         <div className="absolute top-2 left-2 z-50 bg-red-600/90 text-white text-xs font-mono-sci px-2 py-1 rounded animate-pulse pointer-events-none border border-red-400 shadow-[0_0_10px_red]">
            TARGETING MODE // DRAG TO SELECT
         </div>
      )}

      {currentBox && isEditing && (
        <div style={getStyle(currentBox)} className="absolute z-50 border-2 border-dashed border-emerald-400 bg-emerald-500/20 shadow-[0_0_15px_rgba(52,211,153,0.5)] pointer-events-none">
           <div className="absolute top-0 right-0 -mt-5 text-[10px] text-emerald-400 font-mono-sci">ACQUIRING...</div>
        </div>
      )}

      {/* Existing Risks */}
      <div className="absolute inset-0 z-40 pointer-events-none">
        {risks.map((risk, index) => {
          // GUARD CLAUSE: IF BOX DATA IS MISSING, SKIP TO PREVENT CRASH
          if (!risk.box_2d || typeof risk.box_2d.xmin !== 'number') return null;

          const isSelected = activeId === risk.id;
          const isManual = risk.id?.startsWith('manual');

          // --- SMART POSITIONING LOGIC ---
          // Determine where the box is relative to the canvas
          const xCenter = (risk.box_2d.xmin + risk.box_2d.xmax) / 2;
          const yCenter = (risk.box_2d.ymin + risk.box_2d.ymax) / 2;

          // Flip Logic: If box is on the right (>500), label goes LEFT. Else RIGHT.
          const labelOnLeft = xCenter > 500;

          // Vertical Flip: If box is very low (>800), push label UP.
          const labelPushUp = yCenter > 800;

          return (
            <div key={risk.id} 
              className={`absolute pointer-events-auto transition-all duration-300
                ${isEditing ? 'opacity-30 pointer-events-none' : 'opacity-100 cursor-pointer'} 
                ${isSelected ? 'z-[60]' : 'z-[40]'}
              `}
              style={getStyle(risk.box_2d)}
              onClick={(e) => handleBoxClick(e, risk)} 
            >
                {/* 1. Box Border */}
                <div className={`absolute inset-0 border-2 opacity-80 ${isSelected ? 'border-white animate-pulse' : 'border-red-500'} ${isManual ? 'border-dashed' : ''}`}></div>

                {/* 2. Corners */}
                <div className={`absolute -top-1 -left-1 w-2 h-2 border-t-2 border-l-2 ${isSelected ? 'border-white' : 'border-red-500'}`}></div>
                <div className={`absolute -bottom-1 -right-1 w-2 h-2 border-b-2 border-r-2 ${isSelected ? 'border-white' : 'border-red-500'}`}></div>

                {/* 3. Smart Callout Label */}
                {!isEditing && (
                    <div className={`absolute flex items-center
                        ${labelOnLeft ? 'flex-row-reverse right-full mr-1' : 'flex-row left-full ml-1'}
                        ${labelPushUp ? 'bottom-0' : 'top-0'}
                    `}>
                        {/* Connecting Line */}
                        <div className={`w-4 h-[2px] bg-red-500 ${labelOnLeft ? 'origin-right' : 'origin-left'}`}></div>

                        {/* The Label Body */}
                        <div 
                            className={`
                                bg-white border border-red-600 px-2 py-1 shadow-lg
                                flex flex-col items-start min-w-[100px] max-w-[150px]
                                ${isSelected ? 'scale-110' : 'scale-100'}
                            `}
                        >
                            <span className="text-[8px] font-black uppercase tracking-widest text-red-600 border-b border-red-200 w-full pb-0.5 mb-0.5 leading-none">
                                #{index + 1} DETECTED
                            </span>
                            <span className="text-[10px] font-bold text-black uppercase leading-tight break-words w-full">
                                {risk.label}
                            </span>
                        </div>
                    </div>
                )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

