          sensitivityPrompt = "Be STRICT. Flag minor hygiene issues. Identify OCCUPATIONAL SAFETY (OSH) risks.";
      } else if (sensitivity === 'EXTREME') {
          sensitivityPrompt = "ZERO TOLERANCE MODE. Forensic audit. Flag EVERYTHING.";
      }

      systemInstruction = `
        ROLE: SENIOR HEALTH & SAFETY INSPECTOR.
        TASK: Conduct a forensic vector and safety inspection.
        SENSITIVITY: ${sensitivity} - ${sensitivityPrompt}
        LANGUAGE: ${targetLang}.
