                }
            });
         });

         let text = response.text;
         if (!text) throw new Error("Empty response");
         text = text.replace(/```json/g, '').replace(/```/g, '');
         const jsonStartIndex = text.indexOf('{');
         const jsonEndIndex = text.lastIndexOf('}');
         if (jsonStartIndex !== -1 && jsonEndIndex !== -1) text = text.substring(jsonStartIndex, jsonEndIndex + 1);

         const parsedResult = JSON.parse(text) as AnalysisResponse;

         // --- FIX 1: Ensure IDs exist and Boxes are valid ---
         if (parsedResult.risks) {
            // Filter out risks without valid box data to avoid crashes
            parsedResult.risks = parsedResult.risks.filter(r => r && r.box_2d && typeof r.box_2d.xmin === 'number');

