export const fetchLatestIDengueStats = async (): Promise<iDengueData> => {
  const ai = getAIClient();
  const prompt = `Cari statistik terkini denggi di Malaysia dari laman web idengue.mysa.gov.my atau KKM. 
  Dapatkan: 
  1. Jumlah kes terkumpul tahun ini.
  2. Jumlah kematian terkumpul.
  3. Bilangan hotspot aktif.
  4. Negeri dengan kes tertinggi.
  Kembalikan dalam format JSON.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview', // Pro is used for complex tasks like grounding
    contents: prompt,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          cumulativeCases: { type: Type.NUMBER },
          cumulativeDeaths: { type: Type.NUMBER },
          activeHotspots: { type: Type.NUMBER },
          topState: { type: Type.STRING },
          lastUpdated: { type: Type.STRING }
        },
        required: ["cumulativeCases", "cumulativeDeaths", "activeHotspots", "topState"]
      }
    }
  });

  const data = JSON.parse(response.text || "{}");
  return {
    ...data,
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((c: any) => ({
      title: c.web?.title || "iDengue Source",
      url: c.web?.uri || "https://idengue.mysa.gov.my/"
    })) || []
  };
};

const compressImage = (base64Str: string, maxWidth = 1024, quality = 0.7): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = `data:image/jpeg;base64,${base64Str}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let width = img.width;
            let height = img.height;
            if (width > maxWidth) {
                height = Math.round((height * maxWidth) / width);
                width = maxWidth;
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            resolve(canvas.toDataURL('image/jpeg', quality).split(',')[1]);
        };
        img.onerror = () => resolve(base64Str); 
    });
};

const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> => {
    try {
        return await fn();
    } catch (error: any) {
        const msg = error.message || "";
        const isQuotaError = msg.includes("429") || msg.includes("503");
        if (isQuotaError && retries > 0) {
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(fn, retries - 1, delay * 2);
        }
        throw error;
    }
};

export const analyzeLandscape = async (base64Image: string, mimeType: string, mode: 'FAST' | 'DETAILED' = 'DETAILED', language: string = 'ms', sensitivity: SensitivityLevel = 'STANDARD', analysisMode: AnalysisMode = 'VECTOR_CONTROL'): Promise<AnalysisResponse> => {
  const langMap: Record<string, string> = { 'ms': 'Bahasa Melayu', 'en': 'English', 'zh': 'Chinese', 'ta': 'Tamil' };
  const targetLang = langMap[language] || 'Bahasa Melayu';
  const optimizedImage = await compressImage(base64Image);

  // Updated to use supported Gemini 3 and 2.5 series model names
  const modelsToTry = ["gemini-3-flash-preview", "gemini-3-pro-preview"];

  let systemInstruction = "";
  let schemaDescription = "";

  if (analysisMode === 'KKM_FOOD_STANDARD') {
      systemInstruction = `
        ROLE: PEGAWAI KESIHATAN PERSEKITARAN (PPKP) - AUDIT PREMIS MAKANAN.
        TASK: Lakukan pemeriksaan ketat berdasarkan format "BORANG PEMERIKSAAN PREMIS MAKANAN (KKM) K-PPKM-01/03".
        LANGUAGE: ${targetLang} (Formal Government Tone).
        CRITERIA (A-M): A (Kawalan Proses), B (Bangunan), C (Pengendali), D (Peralatan), E (Bekalan Air), F (Perparitan), G (Sanitasi), H (Sampah), I (Vektor), J (Pembersihan), K (Pengangkutan), L (Dokumen), M (Risiko Lain).
      `;

      schemaDescription = `JSON with kkmReport (sections A-M), risks, hygieneLevel, safetyLevel.`;
  } else {
      let sensitivityPrompt = "";
      if (sensitivity === 'STANDARD') sensitivityPrompt = "Focus on OBVIOUS biological vectors and MAJOR safety hazards.";
      else if (sensitivity === 'HIGH') sensitivityPrompt = "Be STRICT. Flag minor hygiene issues and OSH risks.";
      else if (sensitivity === 'EXTREME') sensitivityPrompt = "ZERO TOLERANCE MODE. Forensic audit. Flag EVERYTHING.";

      systemInstruction = `
        ROLE: SENIOR HEALTH & SAFETY INSPECTOR.
        TASK: Conduct a forensic vector and safety inspection.
        SENSITIVITY: ${sensitivity} - ${sensitivityPrompt}
        LANGUAGE: ${targetLang}.
        OUTPUT: JSON with risks, hygieneLevel, safetyLevel, mode: "VECTOR_CONTROL".
      `;

      schemaDescription = `Standard AnalysisResponse JSON structure.`;
  }

  let lastError: any = null;

  for (const modelId of modelsToTry) {
     try {
         const response = await retryWithBackoff(async () => {
              const ai = getAIClient();
              return await ai.models.generateContent({
                model: modelId,
                contents: {
                    parts: [
                        { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, 
                        { text: `${systemInstruction} \n\n Output JSON Schema: ${schemaDescription}` }
                    ]
                },
                config: {
                    responseMimeType: "application/json"
                }
            });
         });

         let text = response.text || "{}";
         // Defensive stripping of markdown in case the model returns it despite the mimeType config
         text = text.replace(/```json/g, '').replace(/```/g, '');
         const parsedResult = JSON.parse(text) as AnalysisResponse;

         if (parsedResult.risks) {
            parsedResult.risks = parsedResult.risks.filter(r => r && r.box_2d && typeof r.box_2d.xmin === 'number');
            parsedResult.risks.forEach((r, idx) => {
                if (!r.id) r.id = `gen-${Date.now()}-${idx}`;
            });
         } else {
            parsedResult.risks = [];
         }

         if (analysisMode === 'KKM_FOOD_STANDARD' && parsedResult.kkmReport) {
             let calculatedDemerit = 0;
             parsedResult.kkmReport.sections.forEach(sec => {
                 if (sec.demeritReceived > sec.totalPoints) sec.demeritReceived = sec.totalPoints;
                 calculatedDemerit += sec.demeritReceived;
             });
             const finalScore = Math.max(0, 100 - calculatedDemerit);
             parsedResult.kkmReport.totalDemerit = calculatedDemerit;
             parsedResult.kkmReport.totalScore = finalScore;
             if (finalScore >= 86) parsedResult.kkmReport.grade = 'A';
             else if (finalScore >= 71) parsedResult.kkmReport.grade = 'B';
             else if (finalScore >= 51) parsedResult.kkmReport.grade = 'C';
             else parsedResult.kkmReport.grade = 'D';
         }

         parsedResult.sensitivityUsed = sensitivity;
         parsedResult.mode = analysisMode; 

         return parsedResult;

     } catch (error: any) {
         lastError = error;
     }
  }
  throw lastError || new Error("AI Busy.");
};

export const analyzeManualRegion = async (base64Image: string, mimeType: string, box: BoundingBox, userContext: string, language: string = 'ms'): Promise<RiskDetection> => {
    const optimizedImage = await compressImage(base64Image);
    const ai = getAIClient();
    const prompt = `Region Analysis [${box.ymin}-${box.ymax}, ${box.xmin}-${box.xmax}]. Hint: "${userContext}". Output JSON RiskDetection.`;
    const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview", 
        contents: { parts: [{ inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, { text: prompt }] },
        config: { responseMimeType: "application/json" }
    });
    const result = JSON.parse(response.text!);
    result.id = `manual-${Date.now()}`;
    result.box_2d = box; 
    return result;
};

