               <div className="grid grid-cols-2 gap-2">
                  <button 
                    onClick={() => setAnalysisMode('VECTOR_CONTROL')}
                    className={`text-xs font-bold py-3 rounded transition-all flex items-center justify-center gap-2 ${analysisMode === 'VECTOR_CONTROL' ? 'bg-emerald-600 text-white shadow-lg' : 'bg-slate-800 text-slate-500 hover:bg-slate-700'}`}
                  >
                    <span className="text-lg">🦟</span> KAWALAN VEKTOR
                  </button>
                  <button 
                    onClick={() => setAnalysisMode('KKM_FOOD_STANDARD')}
                    className={`text-xs font-bold py-3 rounded transition-all flex items-center justify-center gap-2 ${analysisMode === 'KKM_FOOD_STANDARD' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-800 text-slate-500 hover:bg-slate-700'}`}
                  >
                    <span className="text-lg">📋</span> STANDARD KKM
                  </button>
               </div>
               <p className="text-[10px] text-slate-500 mt-2 italic text-center">
                  {analysisMode === 'VECTOR_CONTROL' ? "Mengesan nyamuk, lalat, tikus & tempat pembiakan." : "Pemeriksaan premis makanan mengikut format KKM (Borang Kualiti Makanan)."}
               </p>
            </div>

            {analysisMode === 'VECTOR_CONTROL' && (
              <div className="max-w-md mx-auto mb-8 bg-slate-900/50 p-3 rounded-xl border border-slate-700/50">
                <label className="text-[10px] text-slate-400 font-mono-sci uppercase tracking-widest block mb-2">AI SENSITIVITY (OSH & SAFETY)</label>
                <div className="grid grid-cols-3 gap-2">
                    <button 
                      onClick={() => setSensitivity('STANDARD')}
