const compressImage = (base64Str: string, maxWidth = 1024, quality = 0.7): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = `data:image/jpeg;base64,${base64Str}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let width = img.width;
            let height = img.height;
            if (width > maxWidth) {
                height = Math.round((height * maxWidth) / width);
                width = maxWidth;
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            resolve(canvas.toDataURL('image/jpeg', quality).split(',')[1]);
        };
        img.onerror = () => resolve(base64Str); 
    });
};

const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> => {
    try {
        return await fn();
    } catch (error: any) {
        const msg = error.message || "";
        const isQuotaError = msg.includes("429") || msg.includes("503");
        if (isQuotaError && retries > 0) {
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(fn, retries - 1, delay * 2);
        }
        throw error;
    }
};

export const analyzeLandscape = async (base64Image: string, mimeType: string, mode: 'FAST' | 'DETAILED' = 'DETAILED', language: string = 'ms', sensitivity: SensitivityLevel = 'STANDARD', analysisMode: AnalysisMode = 'VECTOR_CONTROL'): Promise<AnalysisResponse> => {
  const langMap: Record<string, string> = { 'ms': 'Bahasa Melayu', 'en': 'English', 'zh': 'Chinese', 'ta': 'Tamil' };
  const targetLang = langMap[language] || 'Bahasa Melayu';
  const optimizedImage = await compressImage(base64Image);

  const modelsToTry = ["gemini-3-flash-preview", "gemini-3-pro-preview"];

  let systemInstruction = "";
  let schemaDescription = "AnalysisResponse JSON structure containing risks array, hygieneLevel (1-5), safetyLevel (1-5), generalAdvice, and savageCommentary.";

  if (analysisMode === 'KKM_FOOD_STANDARD') {
      systemInstruction = `
      ROLE: PEGAWAI KESIHATAN PERSEKITARAN (PPKP) - SENIOR AUDITOR.
      TASK: Audit Premis Makanan berdasarkan Borang K-PPKM-01/03.
      SENSITIVITY: ${sensitivity}. Jika 'EXTREME', cari sekecil-kecil habuk, sisa makanan, atau lalat.

      INSTRUCTIONS:
      1. Scan imej dengan teliti untuk: 
         - Lantai/Dinding/Siling yang kotor, berminyak, atau retak.
         - Makanan di atas lantai atau terdedah.
         - Tanda kehadiran makhluk perosak (najis tikus, lipas, lalat).
         - Pengurusan sampah yang lemah (tong sampah terbuka/melimpah).
         - Saluran longkang tersumbat atau berbau.
      2. Berikan Gred (A, B, C, D, atau TUTUP) berdasarkan jumlah demerit.
      3. Kira markah demerit dengan TEGAS. Setiap kesalahan kebersihan adalah kritikal.
      4. Language: ${targetLang}.
      `;
  } else {
      systemInstruction = `
      ROLE: SENIOR BIOLOGICAL DEFENSE & VECTOR CONTROL INSPECTOR.
      TASK: Forensic-level vector breeding site detection.
      SENSITIVITY: ${sensitivity}. Jika 'EXTREME', anda mesti mengesan walaupun air bertakung sekecil tutup botol.

      INSTRUCTIONS:
      1. Kenal pasti SEMUA tempat berisiko pembiakan vektor (Nyamuk Aedes, Lalat, Tikus).
      2. Cari: 
         - Longgokan sampah/barang terpakai (breeding sites).
         - Air bertakung (stagnant water) dalam tayar, bekas, atau longkang.
         - Rumput panjang/semak samun.
         - Struktur bangunan yang rosak yang boleh menjadi sarang.
      3. Berikan analisis mikrobiologi bagi setiap risiko (Contoh: Denggi, Leptospirosis, Kolera).
      4. Language: ${targetLang}.
      `;
  }

  let lastError: any = null;
  for (const modelId of modelsToTry) {
     try {
         const response = await retryWithBackoff(async () => {
              const ai = getAIClient();
              return await ai.models.generateContent({
                model: modelId,
                contents: {
                    parts: [
                        { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, 
                        { text: `${systemInstruction} \n\n WAJIB Output JSON mengikut skema: ${schemaDescription}` }
                    ]
                },
                config: { 
                  responseMimeType: "application/json",
                  thinkingConfig: { thinkingBudget: mode === 'DETAILED' ? 4096 : 0 }
                }
            });
         });

         let text = response.text || "{}";
         text = text.replace(/```json/g, '').replace(/```/g, '');
         const parsedResult = JSON.parse(text) as AnalysisResponse;

         if (parsedResult.risks) {
            parsedResult.risks = parsedResult.risks.filter(r => r && r.box_2d && typeof r.box_2d.xmin === 'number');
            parsedResult.risks.forEach((r, idx) => {
                if (!r.id) r.id = `gen-${Date.now()}-${idx}`;
            });
         } else {
            parsedResult.risks = [];
         }

         parsedResult.sensitivityUsed = sensitivity;
         parsedResult.mode = analysisMode; 
         return parsedResult;
     } catch (error: any) {
         lastError = error;
     }
  }
  throw lastError || new Error("AI Busy.");
};

export const analyzeManualRegion = async (base64Image: string, mimeType: string, box: BoundingBox, userContext: string, language: string = 'ms'): Promise<RiskDetection> => {
    const optimizedImage = await compressImage(base64Image);
    const ai = getAIClient();
    const prompt = `Region Analysis [${box.ymin}-${box.ymax}, ${box.xmin}-${box.xmax}]. 
    Konteks Pengguna: "${userContext}". 
    Lakukan analisis forensik mendalam pada kawasan ini. Cari sebarang kuman, sampah, atau vektor. 
    Output JSON RiskDetection sahaja.`;

    const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview", 
        contents: { parts: [{ inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, { text: prompt }] },
        config: { responseMimeType: "application/json" }
    });
    const result = JSON.parse(response.text!);
    result.id = `manual-${Date.now()}`;
    result.box_2d = box; 
    return result;
};

