};

export const askRiskFollowUp = async (risk: RiskDetection, question: string, language: string = 'ms'): Promise<string> => {
    const ai = getAIClient();
    const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview", 
        contents: `Context: Risk "${risk.label}" (Agent: ${risk.agent}). Microbiology: ${risk.microbiology}. Question: "${question}". Berikan jawapan profesional dalam Bahasa: ${language}.`,
    });
    return response.text || "Tiada jawapan.";
};

