  const ai = getAIClient();
  const prompt = `EKSTRAK DATA RASMI DENGGI MALAYSIA. 
  Rujuk portal idengue.mysa.gov.my. 
  Sila cari data bagi MINGGU EPIDEMIOLOGI (ME) TERKINI.
  Dapatkan: 
  1. No Minggu Epidemiologi (Contoh: ME 48/2024).
  2. Jumlah kes kumulatif (Tahun setakat ini).
  3. Jumlah kematian kumulatif.
  4. Bilangan hotspot aktif di seluruh negara.
  5. Negeri dengan kes tertinggi.
  MAKLUMAT MESTI TEPAT SEPERTI JADUAL DI idengue.mysa.gov.my. Output JSON sahaja.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          cumulativeCases: { type: Type.NUMBER },
          cumulativeDeaths: { type: Type.NUMBER },
          activeHotspots: { type: Type.NUMBER },
          topState: { type: Type.STRING },
          lastUpdated: { type: Type.STRING },
          epidemiologicalWeek: { type: Type.STRING }
        },
        required: ["cumulativeCases", "cumulativeDeaths", "activeHotspots", "topState", "epidemiologicalWeek"]
      }
