const compressImage = (base64Str: string, maxWidth = 1024, quality = 0.7): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = `data:image/jpeg;base64,${base64Str}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let width = img.width;
            let height = img.height;
            if (width > maxWidth) {
                height = Math.round((height * maxWidth) / width);
                width = maxWidth;
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            resolve(canvas.toDataURL('image/jpeg', quality).split(',')[1]);
        };
        img.onerror = () => resolve(base64Str); 
    });
};

const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> => {
    try {
        return await fn();
    } catch (error: any) {
        const msg = error.message || "";
        const isQuotaError = msg.includes("429") || msg.includes("503");
        if (isQuotaError && retries > 0) {
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(fn, retries - 1, delay * 2);
        }
        throw error;
    }
};

export const analyzeLandscape = async (base64Image: string, mimeType: string, mode: 'FAST' | 'DETAILED' = 'DETAILED', language: string = 'ms', sensitivity: SensitivityLevel = 'STANDARD', analysisMode: AnalysisMode = 'VECTOR_CONTROL'): Promise<AnalysisResponse> => {
  const langMap: Record<string, string> = { 'ms': 'Bahasa Melayu', 'en': 'English', 'zh': 'Chinese', 'ta': 'Tamil' };
  const targetLang = langMap[language] || 'Bahasa Melayu';
  const optimizedImage = await compressImage(base64Image);

  // PRIMARY MODEL: Gemini 3.0 Pro for maximum intelligence and sensitivity.
  const modelsToTry = ["gemini-3-pro-preview", "gemini-3-flash-preview"];

  let systemInstruction = "";
  let schemaDescription = "AnalysisResponse JSON structure containing risks array, hygieneLevel (1-5), safetyLevel (1-5), generalAdvice, and savageCommentary.";

  const forensicVigilance = sensitivity === 'EXTREME' 
    ? "VIGILANCE: HYPER-SENSITIVE FORENSICS. You are an EXTREMELY STRICT inspector. Do NOT miss even a single speck of dust, a tiny drop of water, or a single ant. If the room is not 100% sterile like a surgical room, you MUST find and tag the risks. NO MERCY."
    : sensitivity === 'HIGH'
    ? "VIGILANCE: HIGH DETAIL. Look for subtle filth, faint staining, garbage, or signs of hidden pests behind objects. Be detailed."
    : "VIGILANCE: STANDARD. Identify clear and visible threats like trash piles and stagnant water.";

  if (analysisMode === 'KKM_FOOD_STANDARD') {
      systemInstruction = `
      ROLE: PEGAWAI KESIHATAN PERSEKITARAN (PPKP) - ELITE AUDITOR.
      TASK: Audit Premis Makanan (Borang K-PPKM-01/03).
      ${forensicVigilance}

      INSTRUCTIONS:
      1. CRITICAL SCAN: 
         - Lantai (berdaki, berlendir, sampah sarap, sisa makanan).
         - Dinding/Siling (kulat, habuk, sawang, cat mengelupas).
         - Makanan (terdedah, atas lantai, silang pencemaran, lalat hinggap).
         - Pest (lalat, lipas, tikus - cari najis atau tanda gigitan).
         - Sampah (tong terbuka, berair, melimpah, sisa bertaburan).
         - Saluran Longkang (sumbat, berlemak, sisa makanan dalam sinki).
      2. SCORING: Be strictly professional. High demerit for cross-contamination or active pest presence.
      3. Language: ${targetLang}. Output JSON only.
      `;
  } else {
      systemInstruction = `
      ROLE: SENIOR BIOLOGICAL DEFENSE & VECTOR CONTROL INSPECTOR.
      TASK: Forensic vector breeding site detection.
      ${forensicVigilance}

      INSTRUCTIONS:
      1. DETECT BREEDING SITES: 
         - Stagnant water (bekas kecil, tayar, longkang, daun kering, pasu bunga, dispenser air).
         - Bulk waste (longgokan perabot, tayar, botol, plastik - potential rat/roach homes).
         - Overgrowth (semak samun, rumput panjang yang menyembunyikan sampah).
         - Structural flaws (lubang dinding, siling bocor, longkang pecah).
      2. BIOLOGICAL ANALYSIS: Associate each risk with pathogens (Denggi, Leptospirosis, Zika, Typhoid).
      3. Language: ${targetLang}. Output JSON only.
      `;
  }

  let lastError: any = null;
  for (const modelId of modelsToTry) {
     try {
         const response = await retryWithBackoff(async () => {
              const ai = getAIClient();
              return await ai.models.generateContent({
                model: modelId,
                contents: {
                    parts: [
                        { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, 
                        { text: `${systemInstruction} \n\n WAJIB Output JSON mengikut skema: ${schemaDescription}` }
                    ]
                },
                config: { 
                  responseMimeType: "application/json",
                  thinkingConfig: { thinkingBudget: mode === 'DETAILED' ? 8192 : 0 } // Increased thinking budget for Pro
                }
            });
         });

         let text = response.text || "{}";
         text = text.replace(/```json/g, '').replace(/```/g, '');
         const parsedResult = JSON.parse(text) as AnalysisResponse;

         if (parsedResult.risks) {
            parsedResult.risks = parsedResult.risks.filter(r => r && r.box_2d && typeof r.box_2d.xmin === 'number');
            parsedResult.risks.forEach((r, idx) => {
                if (!r.id) r.id = `gen-${Date.now()}-${idx}`;
            });
         } else {
            parsedResult.risks = [];
         }

         parsedResult.sensitivityUsed = sensitivity;
         parsedResult.mode = analysisMode; 
         return parsedResult;
     } catch (error: any) {
         lastError = error;
     }
  }
  throw lastError || new Error("AI Busy.");
};

export const analyzeManualRegion = async (base64Image: string, mimeType: string, box: BoundingBox, userContext: string, language: string = 'ms'): Promise<RiskDetection> => {
