          else if (progress < 55) setLogText("AUDITING KKM HYGIENE STANDARDS...");
          else if (progress < 75) setLogText("DETECTING PEST VECTORS (FLY/ROACH)...");
          else if (progress < 90) setLogText("CALCULATING DEMERIT & GRADE...");
          else setLogText("FINALIZING PRO-LEVEL REPORT...");
      } else {
          if (progress < 15) setLogText("ENGAGING GEMINI 3.0 PRO ENGINE...");
          else if (progress < 35) setLogText("DEEP FORENSIC LANDSCAPE SCAN...");
          else if (progress < 55) setLogText("ISOLATING BIO-SIGNATURES...");
          else if (progress < 75) setLogText("MAPPING RISK COORDINATES...");
          else if (progress < 90) setLogText("SIMULATING OUTBREAK CHANCE...");
          else setLogText("SYNTHESIZING VECTOR REPORT...");
      }
  }, [progress, mode]);

  return (
    <div className="bg-slate-900/90 border border-emerald-500/30 p-8 md:p-12 rounded-xl text-center min-h-[450px] flex flex-col items-center justify-center relative overflow-hidden backdrop-blur-xl shadow-[0_0_50px_rgba(0,0,0,0.5)]">
