const compressImage = (base64Str: string, maxWidth = 1024, quality = 0.7): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = `data:image/jpeg;base64,${base64Str}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let width = img.width;
            let height = img.height;
            if (width > maxWidth) {
                height = Math.round((height * maxWidth) / width);
                width = maxWidth;
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            resolve(canvas.toDataURL('image/jpeg', quality).split(',')[1]);
        };
        img.onerror = () => resolve(base64Str); 
    });
};

const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> => {
    try {
        return await fn();
    } catch (error: any) {
        const msg = error.message || "";
        const isQuotaError = msg.includes("429") || msg.includes("503");
        if (isQuotaError && retries > 0) {
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(fn, retries - 1, delay * 2);
        }
        throw error;
    }
};

export const analyzeLandscape = async (base64Image: string, mimeType: string, mode: 'FAST' | 'DETAILED' = 'DETAILED', language: string = 'ms', sensitivity: SensitivityLevel = 'STANDARD', analysisMode: AnalysisMode = 'VECTOR_CONTROL'): Promise<AnalysisResponse> => {
  const langMap: Record<string, string> = { 'ms': 'Bahasa Melayu', 'en': 'English', 'zh': 'Chinese', 'ta': 'Tamil' };
  const targetLang = langMap[language] || 'Bahasa Melayu';
  const optimizedImage = await compressImage(base64Image);

  // UPGRADE: Force Gemini 3.0 Pro for logic.
  const modelsToTry = ["gemini-3-pro-preview"];

  // IMPORTANT: Explicitly requesting box_2d to maintain the segmentation feature the user likes.
  let schemaDescription = "AnalysisResponse JSON structure containing risks array (EACH RISK MUST HAVE 'box_2d' coordinates [ymin, xmin, ymax, xmax] on a 0-1000 scale), hygieneLevel (1-5), safetyLevel (1-5), generalAdvice, and savageCommentary.";

  // AUDIT FIX: THE "HOARDER" PROTOCOL
  // Previous prompts were too lenient on "personal belongings". 
  // New logic: "If it's messy, it's a vector home."

  const forensicVigilance = sensitivity === 'EXTREME' 
    ? "VIGILANCE LEVEL: MAXIMUM (ZERO TOLERANCE). Treat this image like a crime scene. Any pile of clothes, stacked boxes, unorganized plastic bags, or dense clutter MUST be flagged as 'Potential Pest Harborage'. Do NOT assume it is just 'messy'. It is a BIOHAZARD. If you see dirt, call it filth."
    : sensitivity === 'HIGH'
    ? "VIGILANCE LEVEL: HIGH. Clutter is a risk. Look for hidden corners, piles of objects, and signs of neglect."
    : "VIGILANCE LEVEL: STANDARD. Identify clear trash, stagnant water, and obvious hygiene violations.";

  const basePrompt = `
    TASK: Perform a forensic Vector Control & Hygiene Audit on this image.
    ${forensicVigilance}

    CRITICAL INTERPRETATION RULES (DO NOT IGNORE):
    1. CLUTTER = RISK: A pile of newspapers, clothes, or boxes is NOT just 'mess'. It is a 'Rat/Roach Harborage' (Tempat Pembiakan Lipas/Tikus). Flag it.
    2. STAINS = BIOHAZARD: Dark spots on walls/floors are not just 'dirt'. Treat them as 'Grease/Mold/Droppings'.
    3. WATER = DENGUE: Any container (cup, bottle, tray) capable of holding water must be flagged, even if dry now.
    4. NO 'CLEAN' BIAS: Do not default to "Clean". Unless the room looks like a hospital sterile room, find the flaws.

    IMPORTANT SEGMENTATION RULE:
    For EVERY risk identified, you MUST provide a bounding box ('box_2d') with coordinates [ymin, xmin, ymax, xmax] scaled to 1000. 
  `;

  let systemInstruction = "";

  if (analysisMode === 'KKM_FOOD_STANDARD') {
      systemInstruction = `
      ROLE: SENIOR PEGAWAI KESIHATAN PERSEKITARAN (PPKP) - AUDIT PREMIS MAKANAN (TEGAS).
      ${basePrompt}

      SPECIFIC KKM CHECKS:
      - Lantai: Licin, berdaki, sisa makanan? (Demerit!)
      - Dinding: Kesan minyak, cat tanggal?
      - Peralatan: Kotor, berkarat?
      - Pengendali: Pakaian kotor, tiada apron/topi (jika ada manusia)?
      - Vektor: Lalat, Lipas, Tikus (Wajib lapor jika nampak walau seekor).

      SCORING: Be strict. 1 (Teruk) to 5 (Sangat Bersih).
      Language: ${targetLang}. Output JSON only.
      `;
  } else {
      systemInstruction = `
      ROLE: SENIOR BIOLOGICAL DEFENSE INSPECTOR (HOARDING & VECTOR SPECIALIST).
      ${basePrompt}

      SPECIFIC VECTOR CHECKS:
      - Hoarding/Longgokan: Flag ALL piles of items as 'Tempat Perlindungan Vektor'.
      - Bekas Air: Flag ALL potential water holding containers.
      - Struktural: Lubang, retak, gelap (tempat nyamuk).

      SCORING: If clutter exists, Hygiene Level CANNOT be 5. Maximum 3.
      Language: ${targetLang}. Output JSON only.
      `;
  }

  let lastError: any = null;
  for (const modelId of modelsToTry) {
     try {
         const response = await retryWithBackoff(async () => {
              const ai = getAIClient();
              return await ai.models.generateContent({
                model: modelId,
                contents: {
                    parts: [
                        { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, 
                        { text: `${systemInstruction} \n\n WAJIB Output JSON mengikut skema: ${schemaDescription}` }
                    ]
                },
                config: { 
                  responseMimeType: "application/json",
                  thinkingConfig: { thinkingBudget: 16000 } // MAX OUT THINKING BUDGET for "Deep Audit"
                }
            });
         });

         let text = response.text || "{}";
         text = text.replace(/```json/g, '').replace(/```/g, '');
         const parsedResult = JSON.parse(text) as AnalysisResponse;

         // Ensure segmentation boxes are valid
         if (parsedResult.risks) {
            parsedResult.risks = parsedResult.risks.filter(r => r && r.box_2d && typeof r.box_2d.xmin === 'number');
            parsedResult.risks.forEach((r, idx) => {
                if (!r.id) r.id = `gen-${Date.now()}-${idx}`;
                if (!r.box_2d) r.box_2d = { ymin: 0, xmin: 0, ymax: 1000, xmax: 1000 };
            });
         } else {
            parsedResult.risks = [];
         }

         parsedResult.sensitivityUsed = sensitivity;
         parsedResult.mode = analysisMode; 
         return parsedResult;
     } catch (error: any) {
         lastError = error;
     }
  }
  throw lastError || new Error("AI Busy.");
};

