  if (analysisMode === 'KKM_FOOD_STANDARD') {
      systemInstruction = `
      ROLE: SENIOR PEGAWAI KESIHATAN PERSEKITARAN (PPKP) - AUDIT KETAT.
      ${gridScanProtocol}
      ${forensicVigilance}

      TARGETS:
      - Siling (Sawang/Bocor)
      - Dinding (Kesan Minyak/Retak)
      - Lantai (Licin/Sisa Makanan)
      - Peralatan (Karat/Kotor)
      - Pengendali Makanan (Etika Pakaian)
      - Vektor (Lipas/Lalat/Tikus) - WAJIB CARI.

      OUTPUT: JSON Only. Language: ${targetLang}.
      `;
  } else {
      systemInstruction = `
      ROLE: SENIOR BIOLOGICAL DEFENSE INSPECTOR (VECTOR CONTROL).
      ${gridScanProtocol}
      ${forensicVigilance}

      TARGETS:
      - Aedes Breeding (Air bertakung walau setitik).
      - Rodent Harborage (Timbunan barang/kotak/baju).
      - Cockroach Nests (Celah gelap/kotor).
      - Structural Defects (Lubang/Retak).

      OUTPUT: JSON Only. Language: ${targetLang}.
      `;
  }

  let lastError: any = null;

  try {
      const response = await retryWithBackoff(async () => {
          const ai = getAIClient();
          return await ai.models.generateContent({
            model: modelId,
            contents: {
                parts: [
                    { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, 
                    { text: `${systemInstruction} \n\n WAJIB Output JSON mengikut skema: ${schemaDescription}` }
                ]
            },
            config: { 
              responseMimeType: "application/json",
              // CRITICAL: Maximizing thinking budget to 32,000 to force "Deep Scanning" behavior.
              // This will significantly increase latency (closer to the requested 1-3 mins) but ensure thoroughness.
              thinkingConfig: { thinkingBudget: 32000 } 
            }
        });
      });

      let text = response.text || "{}";
      text = text.replace(/```json/g, '').replace(/```/g, '');
      const parsedResult = JSON.parse(text) as AnalysisResponse;

      // Ensure segmentation boxes are valid
      if (parsedResult.risks) {
        parsedResult.risks = parsedResult.risks.filter(r => r && r.box_2d && typeof r.box_2d.xmin === 'number');
        parsedResult.risks.forEach((r, idx) => {
            if (!r.id) r.id = `gen-${Date.now()}-${idx}`;
            if (!r.box_2d) r.box_2d = { ymin: 0, xmin: 0, ymax: 1000, xmax: 1000 };
        });
      } else {
        parsedResult.risks = [];
      }

      parsedResult.sensitivityUsed = sensitivity;
      parsedResult.mode = analysisMode; 
      return parsedResult;
  } catch (error: any) {
      console.error("Analysis Error:", error);
      throw new Error("Sistem terlalu sibuk atau gagal. Sila cuba lagi (Deep Scan Error).");
  }
};

export const analyzeManualRegion = async (base64Image: string, mimeType: string, box: BoundingBox, userContext: string, language: string = 'ms'): Promise<RiskDetection> => {
    const optimizedImage = await compressImage(base64Image);
    const ai = getAIClient();
    const prompt = `Region Analysis [${box.ymin}-${box.ymax}, ${box.xmin}-${box.xmax}]. 
    User Context: "${userContext}". 
    Perform extreme forensic analysis on this specific region using GEMINI 3.0 PRO. Detect even the smallest speck of filth or biological hazard. 
    Output JSON RiskDetection only.`;

    const response = await ai.models.generateContent({
        model: "gemini-3-pro-preview", 
        contents: { parts: [{ inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, { text: prompt }] },
        config: { responseMimeType: "application/json" }
    });
    const result = JSON.parse(response.text!);
    result.id = `manual-${Date.now()}`;
    result.box_2d = box; 
    return result;
};

export const generateCleanSimulation = async (base64Image: string, mimeType: string, config: SimulationConfig): Promise<string> => {
