const LoadingDisplay: React.FC<{mode: AnalysisMode}> = ({mode}) => {
  const [progress, setProgress] = useState(0);
  const [logText, setLogText] = useState("INITIALIZING DEEP FORENSIC CORE...");

  useEffect(() => {
    // Slower progress bar to match the 32k token thinking time (approx 45s - 90s)
    const interval = setInterval(() => {
      setProgress((prev) => {
        if (prev >= 98) return 98; // Hold at 98 until complete
        let increment = 0;
        if (prev < 20) increment = Math.random() * 0.5; // Slow start
        else if (prev < 50) increment = Math.random() * 0.2; // Deep thinking phase (very slow)
        else if (prev < 80) increment = Math.random() * 0.1; // Grid analysis
        else increment = Math.random() * 0.05; // Final synthesis
        return Math.min(prev + increment, 98.9);
      });
    }, 100);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
      if (mode === 'KKM_FOOD_STANDARD') {
          if (progress < 10) setLogText("ENGAGING GEMINI 3.0 PRO (MAX POWER)...");
          else if (progress < 30) setLogText("DIVIDING IMAGE INTO 4x4 GRIDS...");
          else if (progress < 50) setLogText("SECTOR SCAN: SEARCHING FOR MICRO-FILTH...");
          else if (progress < 70) setLogText("CROSS-REFERENCING KKM HYGIENE ACT...");
          else if (progress < 90) setLogText("CALCULATING DEMERIT POINTS...");
          else setLogText("FINALIZING AUDIT REPORT...");
      } else {
          if (progress < 10) setLogText("ENGAGING GEMINI 3.0 PRO (MAX POWER)...");
          else if (progress < 30) setLogText("DIVIDING IMAGE INTO 4x4 GRIDS...");
          else if (progress < 50) setLogText("DEEP SCAN: ANALYZING SHADOWS & CLUTTER...");
          else if (progress < 70) setLogText("ISOLATING POTENTIAL BREEDING SITES...");
          else if (progress < 90) setLogText("MAPPING VECTOR TRAJECTORIES...");
          else setLogText("SYNTHESIZING FORENSIC DATA...");
      }
  }, [progress, mode]);

  return (
    <div className="bg-slate-900/90 border border-emerald-500/30 p-8 md:p-12 rounded-xl text-center min-h-[450px] flex flex-col items-center justify-center relative overflow-hidden backdrop-blur-xl shadow-[0_0_50px_rgba(0,0,0,0.5)]">
