// UPGRADE: Increased resolution limit to 1600px. 
// Old value (1024) caused small details (droppings/insects) to blur out in wide shots.
const compressImage = (base64Str: string, maxWidth = 1600, quality = 0.85): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = `data:image/jpeg;base64,${base64Str}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let width = img.width;
            let height = img.height;
            if (width > maxWidth) {
                height = Math.round((height * maxWidth) / width);
                width = maxWidth;
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            resolve(canvas.toDataURL('image/jpeg', quality).split(',')[1]);
        };
        img.onerror = () => resolve(base64Str); 
    });
};

const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 2, delay = 2000): Promise<T> => {
    try {
        return await fn();
    } catch (error: any) {
        const msg = error.message || "";
        const isQuotaError = msg.includes("429") || msg.includes("503") || msg.includes("overloaded");
        if (isQuotaError && retries > 0) {
            console.log(`AI Busy, Retrying in ${delay}ms...`);
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(fn, retries - 1, delay * 2);
        }
        throw error;
    }
};

export const analyzeLandscape = async (base64Image: string, mimeType: string, mode: 'FAST' | 'DETAILED' = 'DETAILED', language: string = 'ms', sensitivity: SensitivityLevel = 'STANDARD', analysisMode: AnalysisMode = 'VECTOR_CONTROL'): Promise<AnalysisResponse> => {
  const langMap: Record<string, string> = { 'ms': 'Bahasa Melayu', 'en': 'English', 'zh': 'Chinese', 'ta': 'Tamil' };
  const targetLang = langMap[language] || 'Bahasa Melayu';
  const optimizedImage = await compressImage(base64Image);

  const modelId = "gemini-3-pro-preview";

  let schemaDescription = "AnalysisResponse JSON structure containing risks array (EACH RISK MUST HAVE 'box_2d' coordinates [ymin, xmin, ymax, xmax] on a 0-1000 scale), hygieneLevel (1-5), safetyLevel (1-5), generalAdvice, and savageCommentary.";

  // RE-ENGINEERED "SAVAGE" PROMPT
  // The AI was previously too lenient on "Hoarding". We now explicitly define "Mess" as a "Risk".

  let sensitivityPrompt = "";
  if (sensitivity === 'STANDARD') {
      sensitivityPrompt = "VIGILANCE: STANDARD. Identify obvious trash, standing water, and pests.";
  } else if (sensitivity === 'HIGH') {
      sensitivityPrompt = "VIGILANCE: HIGH. Flag clutter, unorganized items, and shadows under furniture.";
  } else if (sensitivity === 'EXTREME') {
      sensitivityPrompt = `VIGILANCE: MAXIMAL (ENFORCEMENT MODE). 
      CRITICAL RULE: "Clutter" (Sepah) is NOT harmless. It is "Vector Harborage" (Tempat Pembiakan).
      If a room is messy, YOU MUST FLAG IT. 
      If boxes/clothes are piled up, THAT IS A RISK.
      Do not return 'No Risk' if the room is messy.`;
  }

  const gridScanProtocol = `
    SCANNING PROTOCOL:
    1. Scan for "Clutter Density". If > 10% of floor is covered in items, FLAG AS RISK: "Potential Rodent Harborage".
    2. Scan for "Micro-Spots". Small dark spots on walls/floors = Roach Droppings.
    3. Scan for "Water". Any cup/bowl/container = Aedes Breeding Risk.

    NEGATIVE BIAS INSTRUCTION:
    You are a strict Health Inspector. You are LOOKING for reasons to fail this premise.
    Do not be polite. "Messy" = "Dirty".
  `;

  let systemInstruction = "";

  if (analysisMode === 'KKM_FOOD_STANDARD') {
      systemInstruction = `
        ROLE: SENIOR PEGAWAI KESIHATAN PERSEKITARAN (PPKP) - AUDIT MAKANAN.
        TASK: Conduct a forensic KKM hygiene audit.
        SENSITIVITY: ${sensitivityPrompt}
        ${gridScanProtocol}

        TARGETS:
        - Food Handling (Etika Pakaian, Kuku)
        - Cross Contamination (Sisa Makanan, Minyak)
        - Structural (Lantai Licin, Dinding Kotor)
        - Vectors (Lalat, Lipas, Tikus)

        OUTPUT: JSON Only. Language: ${targetLang}.
      `;
  } else {
      systemInstruction = `
        ROLE: SENIOR BIOLOGICAL DEFENSE INSPECTOR (VECTOR CONTROL).
        TASK: Conduct a forensic vector and safety inspection.
        SENSITIVITY: ${sensitivityPrompt}
        ${gridScanProtocol}

        TARGETS:
        - Aedes Breeding (Air bertakung, Bekas potensi)
        - Rodent/Roach Harborage (Sepah, Timbunan, Gelap)
        - Structural Defects (Retak, Lubang)

        OUTPUT: JSON Only. Language: ${targetLang}.
      `;
  }

  let lastError: any = null;

  try {
      const response = await retryWithBackoff(async () => {
          const ai = getAIClient();
          return await ai.models.generateContent({
            model: modelId,
            contents: {
                parts: [
                    { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, 
                    { text: `${systemInstruction} \n\n WAJIB Output JSON mengikut skema: ${schemaDescription}` }
                ]
            },
            config: { 
              responseMimeType: "application/json",
              // Maintain High Budget but shifted logic to "Find Faults"
              thinkingConfig: { thinkingBudget: 32000 } 
            }
        });
      });

      let text = response.text || "{}";
      text = text.replace(/```json/g, '').replace(/```/g, '');
      const parsedResult = JSON.parse(text) as AnalysisResponse;

      // SAFETY NET: If AI returns empty risks but the prompt was EXTREME, force a re-evaluation or generic clutter risk?
      // Better: Ensure the AI *always* generates risks if hygiene is low.
      // Logic: If hygiene < 3 but risks array is empty, the AI hallucinated "Safety".
      if (parsedResult.hygieneLevel < 3 && parsedResult.risks.length === 0) {
          // Manually inject a general risk if the AI admits it's dirty but fails to box it.
          parsedResult.risks.push({
             id: 'fallback-risk-1',
             category: 'HYGIENE',
             label: 'PERSEKITARAN TIDAK TERURUS',
             agent: 'General Filth',
             disease: 'Pelbagai Penyakit',
             microbiology: 'Bacteria/Fungi',
             statistics: 'High Risk',
             description: 'Keadaan bilik yang berserabut dan tidak terurus mengundang kehadiran vektor.',
             solution: 'Lakukan pembersihan menyeluruh segera.',
             citations: [],
             box_2d: { ymin: 100, xmin: 100, ymax: 900, xmax: 900 } // General box
          });
      }

      if (parsedResult.risks) {
        parsedResult.risks = parsedResult.risks.filter(r => r && r.box_2d && typeof r.box_2d.xmin === 'number');
        parsedResult.risks.forEach((r, idx) => {
            if (!r.id) r.id = `gen-${Date.now()}-${idx}`;
            if (!r.box_2d) r.box_2d = { ymin: 0, xmin: 0, ymax: 1000, xmax: 1000 };
        });
      } else {
        parsedResult.risks = [];
      }

      parsedResult.sensitivityUsed = sensitivity;
      parsedResult.mode = analysisMode; 
      return parsedResult;
  } catch (error: any) {
      console.error("Analysis Error:", error);
      throw new Error("Sistem terlalu sibuk atau gagal. Sila cuba lagi (Deep Scan Error).");
  }
};

