    const prompt = `Region Analysis [${box.ymin}-${box.ymax}, ${box.xmin}-${box.xmax}]. 
    User Context: "${userContext}". 
    Perform extreme forensic analysis on this specific region using GEMINI 3.0 PRO. Detect even the smallest speck of filth or biological hazard. 
    Output JSON RiskDetection only.`;

    const response = await ai.models.generateContent({
        model: "gemini-3-pro-preview", 
        contents: { parts: [{ inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, { text: prompt }] },
        config: { responseMimeType: "application/json" }
