const compressImage = (base64Str: string, maxWidth = 1600, quality = 0.85): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = `data:image/jpeg;base64,${base64Str}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let width = img.width;
            let height = img.height;
            if (width > maxWidth) {
                height = Math.round((height * maxWidth) / width);
                width = maxWidth;
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            resolve(canvas.toDataURL('image/jpeg', quality).split(',')[1]);
        };
        img.onerror = () => resolve(base64Str); 
    });
};

const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 2, delay = 2000): Promise<T> => {
    try {
        return await fn();
    } catch (error: any) {
        const msg = error.message || "";
        const isQuotaError = msg.includes("429") || msg.includes("503") || msg.includes("overloaded");
        if (isQuotaError && retries > 0) {
            console.log(`AI Busy, Retrying in ${delay}ms...`);
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(fn, retries - 1, delay * 2);
        }
        throw error;
    }
};

export const analyzeLandscape = async (base64Image: string, mimeType: string, mode: 'FAST' | 'DETAILED' = 'DETAILED', language: string = 'ms', sensitivity: SensitivityLevel = 'STANDARD', analysisMode: AnalysisMode = 'VECTOR_CONTROL'): Promise<AnalysisResponse> => {
  const langMap: Record<string, string> = { 'ms': 'Bahasa Melayu', 'en': 'English', 'zh': 'Chinese', 'ta': 'Tamil' };
  const targetLang = langMap[language] || 'Bahasa Melayu';
  const optimizedImage = await compressImage(base64Image);

  const modelId = "gemini-3-pro-preview";

  let schemaDescription = "AnalysisResponse JSON structure containing risks array (EACH RISK MUST HAVE 'box_2d' coordinates [ymin, xmin, ymax, xmax] on a 0-1000 scale), hygieneLevel (1-5), safetyLevel (1-5), generalAdvice, and savageCommentary.";

  const forensicVigilance = sensitivity === 'EXTREME' 
    ? "VIGILANCE: MAXIMUM (ZERO TOLERANCE). Treat this as a Bio-Safety Level 4 audit. Any organic matter, clutter, or disorganization is a CRITICAL FAILURE."
    : sensitivity === 'HIGH'
    ? "VIGILANCE: HIGH. Look for hidden risks, shadows, and corners. Clutter is a major violation."
    : "VIGILANCE: STANDARD. Identify clear health hazards.";

  // STRENGTHENED PROMPT: NO SCORE WITHOUT EVIDENCE
  const coreInstruction = `
    RULE 1: IF HYGIENE SCORE < 5, YOU MUST GENERATE A RISK OBJECT.
    - If the room is messy, create a risk called "CLUTTER/SEPAH" with category "HYGIENE".
    - If there are too many items, create a risk "HOARDING RISK".
    - Do NOT output a low score (e.g. 3/5) without providing a bounding box explaining WHY.
    - Every flaw contributing to the score deduction MUST be mapped with a 'box_2d'.

    RULE 2: CLASSIFICATION
    - Dirty/Messy/Dusty = Category 'HYGIENE'.
    - Rats/Mosquitoes/Water/Dark Corners = Category 'VECTOR'.
    - Wires/Trip Hazard/Sharp = Category 'SAFETY'.
  `;

  let systemInstruction = "";

  if (analysisMode === 'KKM_FOOD_STANDARD') {
      systemInstruction = `
        ROLE: SENIOR PEGAWAI KESIHATAN PERSEKITARAN (PPKP) - AUDIT MAKANAN.
        ${forensicVigilance}
        ${coreInstruction}

        TASK:
        1. Scan Floor: Dirty/Wet? -> HYGIENE Risk.
        2. Scan Walls: Stains/Peeling Paint? -> HYGIENE Risk.
        3. Scan Items: Organized? If no -> HYGIENE/SAFETY Risk.
        4. Scan Vectors: Any insects? -> VECTOR Risk.

        OUTPUT: JSON Only. Language: ${targetLang}.
      `;
  } else {
      systemInstruction = `
        ROLE: SENIOR BIOLOGICAL DEFENSE INSPECTOR (VECTOR CONTROL).
        ${forensicVigilance}
        ${coreInstruction}

        TASK:
        1. Scan for Clutter (Sepah): If identified, draw a box covering the messy area. Label: "Sarang Potensi".
        2. Scan for Water: Any container? Draw a box. Label: "Takungan Air".
        3. Scan for Safety: Wires/Obstacles? Draw a box. Label: "Halangan Keselamatan".

        OUTPUT: JSON Only. Language: ${targetLang}.
      `;
  }

  let lastError: any = null;

  try {
      const response = await retryWithBackoff(async () => {
          const ai = getAIClient();
          return await ai.models.generateContent({
            model: modelId,
            contents: {
                parts: [
                    { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, 
                    { text: `${systemInstruction} \n\n WAJIB Output JSON mengikut skema: ${schemaDescription}` }
                ]
            },
            config: { 
              responseMimeType: "application/json",
              thinkingConfig: { thinkingBudget: 32000 } 
            }
        });
      });

      let text = response.text || "{}";
      text = text.replace(/```json/g, '').replace(/```/g, '');
      const parsedResult = JSON.parse(text) as AnalysisResponse;

      // FAIL-SAFE: The "No Explanation" Paradox Fix.
      // If Hygiene/Safety is not perfect (5), but risks array is empty, we MUST inject a generic risk.
      // This ensures the user never sees "Score: 3/5" with "No Risks Detected".

      const isNotPerfect = parsedResult.hygieneLevel < 5 || parsedResult.safetyLevel < 5;
      const hasNoRisks = !parsedResult.risks || parsedResult.risks.length === 0;

      if (isNotPerfect && hasNoRisks) {
          parsedResult.risks = [];

          // Inject a "General Area" risk that covers the center of the image
          parsedResult.risks.push({
             id: 'fallback-hygiene-risk',
             category: parsedResult.hygieneLevel < 5 ? 'HYGIENE' : 'SAFETY',
             label: parsedResult.hygieneLevel < 5 ? 'KEKURANGAN KEBERSIHAN UMUM' : 'ISU KESELAMATAN UMUM',
             agent: 'Faktor Persekitaran',
             disease: 'Potensi Pembiakan Vektor',
             microbiology: 'Habuk / Bakteria',
             statistics: 'Risiko Sederhana',
             description: 'Markah dikurangkan kerana keadaan umum premis yang tidak mencapai piawaian optimum (habuk, susun atur tidak kemas, atau pencahayaan).',
             solution: 'Lakukan pembersihan am dan penyusunan semula barang (3S - Sisih, Susun, Sapu).',
             citations: [],
             box_2d: { ymin: 200, xmin: 200, ymax: 800, xmax: 800 } // Generic Center Box
          });
      }

      // Standardize boxes
      if (parsedResult.risks) {
        parsedResult.risks = parsedResult.risks.filter(r => r && r.box_2d && typeof r.box_2d.xmin === 'number');
        parsedResult.risks.forEach((r, idx) => {
            if (!r.id) r.id = `gen-${Date.now()}-${idx}`;
            // If AI returned a risk but forgot the box, give it a default box so it appears in the list
            if (!r.box_2d) r.box_2d = { ymin: 100, xmin: 100, ymax: 500, xmax: 500 };
        });
      } else {
        parsedResult.risks = [];
      }

      parsedResult.sensitivityUsed = sensitivity;
      parsedResult.mode = analysisMode; 
      return parsedResult;
  } catch (error: any) {
      console.error("Analysis Error:", error);
      throw new Error("Sistem terlalu sibuk atau gagal. Sila cuba lagi (Deep Scan Error).");
  }
};

