      if ((isHygieneLow || isSafetyLow) && riskListEmpty) {
          if (!parsedResult.risks) parsedResult.risks = [];

          // We forcefully inject a risk covering the central area of the image
          // This ensures the user SEES a box and an explanation.
          parsedResult.risks.push({
             id: 'forced-clutter-detection',
             category: isHygieneLow ? 'HYGIENE' : 'SAFETY',
             label: isHygieneLow ? 'PERSEKITARAN TIDAK TERURUS (SEPAH)' : 'SUSUN ATUR TIDAK SELAMAT',
             agent: 'Faktor Manusia',
             disease: 'Potensi Sarang Vektor',
             microbiology: 'Habuk & Sisa Organik',
             statistics: 'Risiko Sederhana',
             description: 'Sistem mengesan ketidakteraturan umum pada ruangan ini yang menyumbang kepada pengurangan markah. Keadaan bersepah (clutter) menghalang pembersihan berkesan dan menyediakan tempat persembunyian vektor.',
             solution: 'Lakukan sisihan (Sort) dan susun (Set in order) segera. Pastikan tiada barang di atas lantai yang menghalang aliran udara/pembersihan.',
             citations: [],
             // A generic central box (approx middle of a 1000x1000 grid)
             box_2d: { ymin: 200, xmin: 150, ymax: 850, xmax: 850 } 
          });
      }

      // Standardize boxes
      if (parsedResult.risks) {
        parsedResult.risks = parsedResult.risks.filter(r => r && r.box_2d && typeof r.box_2d.xmin === 'number');
        parsedResult.risks.forEach((r, idx) => {
            if (!r.id) r.id = `gen-${Date.now()}-${idx}`;
            // Double check validation
            if (!r.box_2d) r.box_2d = { ymin: 200, xmin: 200, ymax: 800, xmax: 800 };
        });
      } else {
        parsedResult.risks = [];
      }

      parsedResult.sensitivityUsed = sensitivity;
      parsedResult.mode = analysisMode; 
      return parsedResult;
  } catch (error: any) {
      console.error("Analysis Error:", error);
      throw new Error("Sistem terlalu sibuk atau gagal. Sila cuba lagi (Deep Scan Error).");
  }
};

