        TASK:
        1. Scan Floor: Dirty/Wet? -> Draw Box -> Label "Lantai Kotor/Licin".
        2. Scan Walls: Stains/Mold? -> Draw Box -> Label "Dinding Berkulat".
        3. Scan Items: Unorganized/Cross-contamination risk? -> Draw Box -> Label "Pencemaran Silang".

        OUTPUT: JSON Only. Language: ${targetLang}.
      `;
  } else {
      systemInstruction = `
        ROLE: SENIOR VECTOR CONTROL OFFICER (AKTA 1975).
        ${forensicVigilance}
        ${coreInstruction}

        TASK:
        1. CLUTTER SCAN (CRITICAL): Identify piles of items. Box them. Label: "Sarang Tikus/Lipas (Sepah)".
        2. WATER SCAN: Any cup/bucket? Box it. Label: "Potensi Aedes".
        3. STRUCTURAL SCAN: Holes/Cracks? Box it. Label: "Laluan Tikus".

        OUTPUT: JSON Only. Language: ${targetLang}.
      `;
  }

  try {
      const response = await retryWithBackoff(async () => {
          const ai = getAIClient();
          return await ai.models.generateContent({
            model: modelId,
            contents: {
                parts: [
                    { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, 
                    { text: `${systemInstruction} \n\n WAJIB Output JSON mengikut skema: ${schemaDescription}` }
                ]
            },
            config: { 
              responseMimeType: "application/json",
              thinkingConfig: { thinkingBudget: 32000 } // Max thinking to force it to consider small details
            }
        });
      });

      let text = response.text || "{}";
      text = text.replace(/```json/g, '').replace(/```/g, '');
      const parsedResult = JSON.parse(text) as AnalysisResponse;

      // ---------------------------------------------------------
      // FAIL-SAFE INJECTION SYSTEM (THE "FORCED BOX" LOGIC)
      // ---------------------------------------------------------

      // If AI says it's clean (5/5) but user selected EXTREME sensitivity, we challenge it.
      // Or if AI gives low score but NO RISKS (The specific bug user reported).

      const isHygieneLow = parsedResult.hygieneLevel < 5;
      const isSafetyLow = parsedResult.safetyLevel < 5;
      const riskListEmpty = !parsedResult.risks || parsedResult.risks.length === 0;

      // FORCE INJECTION: If score is imperfect OR sensitivity is extreme, ensures we have risks.
      if ((isHygieneLow || isSafetyLow || sensitivity === 'EXTREME') && riskListEmpty) {
          if (!parsedResult.risks) parsedResult.risks = [];

          // Create a "General Clutter" risk that covers the central 60% of the image
