                     {Math.min(hygieneLevel, safeLevel) === 1 ? 'IMMEDIATE CLOSURE' : Math.min(hygieneLevel, safeLevel) === 2 ? 'NOTICE ISSUED' : 'COMPLIANT'}
                 </span>
             </div>
        </div>
    );
};

