          if (!risk.box_2d || typeof risk.box_2d.xmin !== 'number') return null;

          const isSelected = activeId === risk.id;
          const isManual = risk.id?.startsWith('manual');

          // Color coding based on Category
          let mainColor = 'border-red-500 text-red-500 bg-red-500';
          if (risk.category === 'HYGIENE') mainColor = 'border-amber-500 text-amber-500 bg-amber-500';
          if (risk.category === 'SAFETY') mainColor = 'border-indigo-500 text-indigo-500 bg-indigo-500';
