          return (
            <div key={risk.id} 
              className={`absolute pointer-events-auto transition-all duration-300 group/box
                ${isEditing ? 'opacity-30 pointer-events-none' : 'opacity-100 cursor-pointer'} 
                ${isSelected ? 'z-[60]' : 'z-[40]'}
              `}
              style={getStyle(risk.box_2d)}
              onClick={(e) => handleBoxClick(e, risk)} 
            >
                {/* 
                    NEW DESIGN: HUD CORNERS
                    Instead of a full border, we use 4 corners that are always visible but subtle.
                    The full border only appears on hover/select.
