                <div className={`absolute top-0 right-0 w-3 h-3 border-t-2 border-r-2 ${mainColor} opacity-70`}></div>
                <div className={`absolute bottom-0 left-0 w-3 h-3 border-b-2 border-l-2 ${mainColor} opacity-70`}></div>
                <div className={`absolute bottom-0 right-0 w-3 h-3 border-b-2 border-r-2 ${mainColor} opacity-70`}></div>

                {/* 2. Full Border & Fill (Only on Hover/Select) */}
                <div className={`
                    absolute inset-0 border ${mainColor} transition-all duration-300
                    ${isSelected ? 'opacity-100 bg-white/5 shadow-[0_0_20px_rgba(255,255,255,0.2)]' : 'opacity-0 group-hover/box:opacity-60 group-hover/box:bg-black/20'}
                `}></div>

                {/* 3. Center Crosshair (Tech Feel) - Helps identify the center of the object without blocking it */}
                <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 pointer-events-none opacity-50 ${isSelected ? 'opacity-100' : ''}`}>
                    <div className={`absolute top-1/2 left-0 w-full h-[1px] ${mainColor.split(' ')[2]}`}></div>
                    <div className={`absolute left-1/2 top-0 h-full w-[1px] ${mainColor.split(' ')[2]}`}></div>
                </div>

                {/* 4. Minimalist Label Tag */}
                <div className={`
                    absolute -top-3 left-0 flex items-center transition-all duration-300 origin-bottom-left
                    ${isSelected ? 'scale-110 z-50' : 'scale-100 z-40'}
                `}>
                    {/* Index Number Badge (Always Visible) */}
                    <div className={`
                        flex items-center justify-center w-5 h-5 text-[10px] font-bold font-mono-sci 
                        ${mainColor.replace('border-', '').replace('text-', '')} text-black
                        ${isSelected ? 'shadow-[0_0_10px_currentColor]' : ''}
                    `}>
                        {index + 1}
                    </div>

                    {/* Text Label (Only Visible on Hover/Select) - Prevents clutter */}
                    <div className={`
                        overflow-hidden whitespace-nowrap bg-black/80 backdrop-blur-sm border-y border-r ${mainColor.split(' ')[0]}
                        transition-all duration-300 ease-out
                        ${isSelected || 'group-hover/box:max-w-[200px]'}
                        ${isSelected ? 'max-w-[200px] px-2 opacity-100' : 'max-w-0 px-0 opacity-0 group-hover/box:opacity-100 group-hover/box:px-2'}
                    `}>
                        <span className={`text-[10px] font-bold uppercase tracking-wider ${mainColor.split(' ')[1]}`}>
                            {risk.label}
                        </span>
                    </div>
                </div>

                {/* 5. Connecting Line (Tech aesthetic) */}
                {isSelected && (
                    <div className={`absolute top-0 left-5 w-[20px] h-[1px] ${mainColor.split(' ')[2]} -translate-y-[6px] -rotate-45 origin-left opacity-50`}></div>
                )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

