const compressImage = (base64Str: string, maxWidth = 1600, quality = 0.9): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = `data:image/jpeg;base64,${base64Str}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let width = img.width;
            let height = img.height;
            if (width > maxWidth) {
                height = Math.round((height * maxWidth) / width);
                width = maxWidth;
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            resolve(canvas.toDataURL('image/jpeg', quality).split(',')[1]);
        };
        img.onerror = () => resolve(base64Str); 
    });
};

const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 2, delay = 2000): Promise<T> => {
    try {
        return await fn();
    } catch (error: any) {
        const msg = error.message || "";
        const isQuotaError = msg.includes("429") || msg.includes("503") || msg.includes("overloaded");
        if (isQuotaError && retries > 0) {
            console.log(`AI Busy, Retrying in ${delay}ms...`);
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(fn, retries - 1, delay * 2);
        }
        throw error;
    }
};

// WATCHDOG KEYWORDS: If these are found in the 'detected_keywords' list,
// we force downgrade the score even if AI gave it 5/5.
const CLUTTER_KEYWORDS = [
  'trash', 'rubbish', 'garbage', 'sampah', 'sisa', 'mess', 'clutter', 
  'pile', 'timbunan', 'sepah', 'plastic bag', 'cardboard', 'boxes', 
  'clothes', 'baju', 'kasut', 'shoes', 'botol', 'bottle', 'can', 'tin',
  'food', 'sisa makanan', 'wrapper', 'plastik'
];

export const analyzeLandscape = async (base64Image: string, mimeType: string, mode: 'FAST' | 'DETAILED' = 'DETAILED', language: string = 'ms', sensitivity: SensitivityLevel = 'STANDARD', analysisMode: AnalysisMode = 'VECTOR_CONTROL'): Promise<AnalysisResponse> => {
  const langMap: Record<string, string> = { 'ms': 'Bahasa Melayu', 'en': 'English', 'zh': 'Chinese', 'ta': 'Tamil' };
  const targetLang = langMap[language] || 'Bahasa Melayu';
  const optimizedImage = await compressImage(base64Image);

  const modelId = "gemini-3-flash-preview";

  // STRICT SCHEMA DEFINITION
  let schemaDescription = `
    AnalysisResponse JSON structure (STRICTLY REQUIRED FIELDS):
    - risks: array of RiskDetection. EACH RISK MUST CONTAIN:
        - box_2d: [ymin, xmin, ymax, xmax] 0-1000.
        - label: (string) Short name of risk.
        - agent: (string) The specific vector/pest name (e.g. Aedes aegypti, Musca domestica, Rattus rattus).
        - microbiology: (string) **MANDATORY**: SCIENTIFIC NAME of potential pathogen (e.g. Salmonella typhi, Leptospira interrogans, Staphylococcus aureus). DO NOT LEAVE EMPTY. GUESS BASED ON CONTEXT IF NEEDED.
        - disease: (string) **MANDATORY**: Clinical disease name (e.g. Leptospirosis, Typhoid Fever, Gastroenteritis). DO NOT LEAVE EMPTY.
        - statistics: (string) Brief stat (e.g. "Fatality: 10%").
        - description: (string) Analysis.
        - solution: (string) Action plan.
    - detected_keywords: string[] (List ALL physical items seen e.g. "plastic bag", "bottle", "clothes").
    - hygieneLevel: number (1-5).
    - safetyLevel: number (1-5).
    - generalAdvice: string.
    - savageCommentary: string.
  `;

  const forensicVigilance = `
    ROLE: FORENSIC PATHOLOGIST & VECTOR CONTROL SPECIALIST.
    OBJECTIVE: IDENTIFY BIOLOGICAL HAZARDS WITH EXTREME PRECISION.

    CRITICAL RULE 1: FILL THE BLANKS.
    - 'microbiology' field CANNOT be empty. If you see trash, write "Leptospira interrogans" or "Salmonella spp.".
    - 'disease' field CANNOT be empty. Write the clinical condition.

    CRITICAL RULE 2: CLINICAL LINKAGE.
    - Trash/Clutter -> Rodents -> Leptospirosis.
    - Stagnant Water -> Mosquitoes -> Dengue Hemorrhagic Fever.
    - Food Waste -> Flies -> Cholera / Typhoid.
    - Dust/Mold -> Fungi -> Aspergillus / Respiratory Asthma.

    LANGUAGE: ${targetLang}.
  `;

  let systemInstruction = "";

  if (analysisMode === 'KKM_FOOD_STANDARD') {
      systemInstruction = `
        ROLE: KKM FOOD SAFETY AUDITOR.
        ${forensicVigilance}

        TASKS:
        1. Identify specific cross-contamination risks.
        2. Name the BACTERIA likely present on dirty surfaces (e.g. E. coli, Listeria).
        3. Output JSON only.
      `;
  } else {
      systemInstruction = `
        ROLE: VECTOR CONTROL ENFORCEMENT.
        ${forensicVigilance}

        TASKS:
        1. Detect breeding sites.
        2. Identify specific VECTORS and their PATHOGENS.
        3. Draw bounding boxes around risk areas.
        4. Output JSON only.
      `;
  }

  try {
      const response = await retryWithBackoff(async () => {
          const ai = getAIClient();
          return await ai.models.generateContent({
            model: modelId,
            contents: {
                parts: [
                    { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, 
                    { text: `${systemInstruction} \n\n WAJIB Output JSON mengikut skema: ${schemaDescription}` }
                ]
            },
            config: { 
              responseMimeType: "application/json",
              // DISABLE THINKING BUDGET FOR FLASH MODEL to avoid over-rationalizing/politeness
              thinkingConfig: { thinkingBudget: 0 } 
            }
        });
      });

      let text = response.text || "{}";
      text = text.replace(/```json/g, '').replace(/```/g, '').trim();
      const parsedResult = JSON.parse(text) as AnalysisResponse;

      // ---------------------------------------------------------
      // THE LOGIC WATCHDOG (RESTORES "INTELLIGENCE")
      // ---------------------------------------------------------
      const detectedWords = (parsedResult.detected_keywords || []).map(w => w.toLowerCase());
      const hasClutterKeywords = detectedWords.some(word => 
        CLUTTER_KEYWORDS.some(bad => word.includes(bad))
      );

      // FORCE DOWNGRADE: If clues found but score is perfect -> Punish it.
      if (hasClutterKeywords && parsedResult.hygieneLevel >= 4) {
          console.log("Watchdog triggered: Clutter detected but score was high. Downgrading.");
          parsedResult.hygieneLevel = 3; // Force downgrade
      }

      // FAIL-SAFE INJECTION (Redundant Check)
      const isHygieneLow = parsedResult.hygieneLevel < 5;
      const isSafetyLow = parsedResult.safetyLevel < 5;
      const riskListEmpty = !parsedResult.risks || parsedResult.risks.length === 0;

      if ((isHygieneLow || isSafetyLow || sensitivity === 'EXTREME') && riskListEmpty) {
          if (!parsedResult.risks) parsedResult.risks = [];
          const evidence = detectedWords.filter(w => CLUTTER_KEYWORDS.some(bad => w.includes(bad))).join(', ') || "Objek Tidak Teratur";

          parsedResult.risks.push({
             id: 'watchdog-clutter-detection',
             category: 'HYGIENE',
             label: 'PERSEKITARAN BERISIKO (KLINIKAL)',
             agent: 'Rattus rattus / Musca domestica',
             disease: 'Leptospirosis / Demam Tifoid',
             microbiology: 'Leptospira interrogans / Salmonella typhi', // FORCED VALUE
             statistics: 'Risiko Tinggi Jangkitan',
             description: `Sistem mengesan objek berikut yang menyumbang kepada risiko biologi: [${evidence}]. Keadaan ini menggalakkan pembiakan bakteria patogenik.`,
             solution: 'Lakukan sanitasi klinikal dan sisihan (Sort) segera.',
             citations: [],
             box_2d: { ymin: 200, xmin: 150, ymax: 850, xmax: 850 } 
          });
      }

      // Standardize boxes AND FILL EMPTY BIO FIELDS
      if (parsedResult.risks) {
        parsedResult.risks = parsedResult.risks.filter(r => r && r.box_2d && typeof r.box_2d.xmin === 'number');
        parsedResult.risks.forEach((r, idx) => {
            if (!r.id) r.id = `gen-${Date.now()}-${idx}`;
            if (!r.box_2d) r.box_2d = { ymin: 200, xmin: 200, ymax: 800, xmax: 800 };

            // CRITICAL FALLBACKS FOR BIO-FORENSIC GRID
            if (!r.microbiology || r.microbiology.length < 3) r.microbiology = "Pathogen Screening Required";
            if (!r.disease || r.disease.length < 3) r.disease = "Potential Clinical Risk";
            if (!r.agent) r.agent = "Unknown Vector";
        });
      } else {
        parsedResult.risks = [];
      }

      parsedResult.sensitivityUsed = sensitivity;
      parsedResult.mode = analysisMode; 
      return parsedResult;
  } catch (error: any) {
      console.error("Analysis Error:", error);
      throw new Error("Sistem terlalu sibuk atau gagal. Sila cuba lagi (Deep Scan Error).");
  }
};

export const analyzeManualRegion = async (base64Image: string, mimeType: string, box: BoundingBox, userContext: string, language: string = 'ms'): Promise<RiskDetection> => {
    const optimizedImage = await compressImage(base64Image);
    const ai = getAIClient();
    const prompt = `Region Analysis [${box.ymin}-${box.ymax}, ${box.xmin}-${box.xmax}]. 
    User Context: "${userContext}". 
    Perform extreme forensic analysis on this specific region using GEMINI 3.0 FLASH PREVIEW. 
    MUST IDENTIFY: 
    1. Specific Micro-organism (Latin name) for 'microbiology' field.
    2. Clinical Disease name for 'disease' field.

    Output JSON RiskDetection only.`;

    const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview", 
        contents: { parts: [{ inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, { text: prompt }] },
        config: { responseMimeType: "application/json" }
    });
    const result = JSON.parse(response.text!);
    result.id = `manual-${Date.now()}`;
    result.box_2d = box; 

    // Ensure manual results also have these fields
    if (!result.microbiology) result.microbiology = "Targeted Pathogen Analysis";
    if (!result.disease) result.disease = "Localized Infection Risk";

    return result;
};

