export const fetchLatestIDengueStats = async (): Promise<iDengueData> => {
  try {
      const ai = getAIClient();
      const prompt = `EKSTRAK DATA RASMI DENGGI MALAYSIA. 
      Rujuk portal idengue.mysa.gov.my atau berita terkini KKM.
      Dapatkan data bagi MINGGU EPIDEMIOLOGI (ME) TERKINI 2024/2025.
      Output JSON Structure: { "cumulativeCases": number, "cumulativeDeaths": number, "activeHotspots": number, "topState": string, "epidemiologicalWeek": string }`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview', 
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              cumulativeCases: { type: Type.NUMBER },
              cumulativeDeaths: { type: Type.NUMBER },
              activeHotspots: { type: Type.NUMBER },
              topState: { type: Type.STRING },
              lastUpdated: { type: Type.STRING },
              epidemiologicalWeek: { type: Type.STRING }
            },
            required: ["cumulativeCases", "cumulativeDeaths", "activeHotspots", "topState", "epidemiologicalWeek"]
          }
        }
      });
      let text = response.text || "{}";
      text = text.replace(/```json/g, '').replace(/```/g, '').trim();
      const data = JSON.parse(text);
      if (!data.cumulativeCases) throw new Error("Empty Data");
      return { ...data, sources: [{ title: "iDengue MYSA Official", url: "https://idengue.mysa.gov.my/" }] };
  } catch (error) {
      return FALLBACK_IDENGUE_DATA;
  }
};

export const fetchRegionalDengueStats = async (state: string, district: string): Promise<RegionalDengueData> => {
    try {
        const ai = getAIClient();
        const prompt = `Cari statistik denggi untuk Negeri: ${state}, Daerah: ${district}. Rujuk idengue.mysa.gov.my. Output JSON: { "stateName": "${state}", "districtName": "${district}", "stateCases": number, "districtCases": number, "districtHotspots": number, "districtRiskLevel": "LOW"|"MEDIUM"|"HIGH"|"EXTREME", "localAdvice": string, "epidemiologicalWeek": string }`;

        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: prompt,
          config: {
            tools: [{ googleSearch: {} }],
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.OBJECT,
              properties: {
                stateName: { type: Type.STRING },
                districtName: { type: Type.STRING },
                stateCases: { type: Type.NUMBER },
                districtCases: { type: Type.NUMBER },
                districtHotspots: { type: Type.NUMBER },
                districtRiskLevel: { type: Type.STRING, enum: ["LOW", "MEDIUM", "HIGH", "EXTREME"] },
                localAdvice: { type: Type.STRING },
                epidemiologicalWeek: { type: Type.STRING }
              },
              required: ["stateName", "districtName", "stateCases", "districtCases", "districtHotspots", "districtRiskLevel", "epidemiologicalWeek"]
            }
          }
        });
        let text = response.text || "{}";
        text = text.replace(/```json/g, '').replace(/```/g, '').trim();
        const data = JSON.parse(text);
        if (!data.stateCases) throw new Error("Empty Regional Data");
        return data;
    } catch (error) {
        return { ...FALLBACK_REGIONAL_DATA, stateName: state, districtName: district };
    }
};

const compressImage = (base64Str: string, maxWidth = 1600, quality = 0.9): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = `data:image/jpeg;base64,${base64Str}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let width = img.width;
            let height = img.height;
            if (width > maxWidth) {
                height = Math.round((height * maxWidth) / width);
                width = maxWidth;
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            resolve(canvas.toDataURL('image/jpeg', quality).split(',')[1]);
        };
        img.onerror = () => resolve(base64Str); 
    });
};

const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 2, delay = 2000): Promise<T> => {
    try {
        return await fn();
    } catch (error: any) {
        const msg = error.message || "";
        const isQuotaError = msg.includes("429") || msg.includes("503") || msg.includes("overloaded");
        if (isQuotaError && retries > 0) {
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(fn, retries - 1, delay * 2);
        }
        throw error;
    }
};

const CLUTTER_KEYWORDS = ['trash', 'rubbish', 'garbage', 'sampah', 'sisa', 'mess', 'clutter', 'pile', 'plastic bag', 'bottle', 'can', 'food', 'sisa makanan', 'kotor', 'dirty', 'stain', 'habuk', 'dust', 'web', 'sarang labah'];

export const analyzeLandscape = async (base64Image: string, mimeType: string, mode: 'FAST' | 'DETAILED' = 'DETAILED', language: string = 'ms', sensitivity: SensitivityLevel = 'STANDARD', analysisMode: AnalysisMode = 'VECTOR_CONTROL'): Promise<AnalysisResponse> => {
  const langMap: Record<string, string> = { 'ms': 'Bahasa Melayu', 'en': 'English', 'zh': 'Chinese', 'ta': 'Tamil' };
  const targetLang = langMap[language] || 'Bahasa Melayu';
  const optimizedImage = await compressImage(base64Image);

  // UPGRADE TO PRO MODEL FOR DEEP REASONING
  const modelId = "gemini-3-pro-preview";

  // STRICT JSON SCHEMA
  let schemaDescription = `
    Output MUST be valid JSON. Fields:
    - risks: Array of { 
        box_2d: [ymin, xmin, ymax, xmax], 
        label: string, 
        agent: string (Vector Name), 
        microbiology: string (Bacteria Name - REQUIRED), 
        disease: string (Clinical Disease - REQUIRED), 
        description: string, 
        solution: string 
      }
    - detected_keywords: string[]
    - hygieneLevel: INTEGER (1-5). REQUIRED.
    - safetyLevel: INTEGER (1-5). REQUIRED.
    - generalAdvice: string (Detailed Summary - REQUIRED).
    - savageCommentary: string (Sarcastic comment - REQUIRED).
  `;

  // UPDATED STRICT SCORING LOGIC
  const scoringLogic = `
    SCORING RULES (ABSOLUTE STRICTNESS):
    1. HYGIENE LEVEL (1-5):
       - 5: STERILE LAB ONLY. (Rarely given).
       - 4: PERFECTLY TIDY. No clutter, no dust.
       - 3: AVERAGE. Some items on tables, slight mess.
       - 2: DIRTY. Visible clutter, piles of clothes/paper, trash on floor, unwashed dishes.
       - 1: BIOHAZARD/DUMPSITE. Hoarding, rotting food, heavy stains, pests.

    CRITICAL OVERRIDE: 
    - IF YOU SEE ANY PILE OF OBJECTS (CLUTTER) -> MAX SCORE IS 3.
    - IF YOU SEE TRASH ON FLOOR -> MAX SCORE IS 2.
    - IF YOU SEE FOOD RESIDUE -> MAX SCORE IS 2.
  `;

  // DEEP FORENSIC INSTRUCTIONS
  const forensicVigilance = `
    ROLE: STRICT FORENSIC PATHOLOGIST & HEALTH INSPECTOR.
    TASK: Analyze image for disease vectors and HYGIENE VIOLATIONS.
    LANGUAGE: ${targetLang}.

    EXECUTION STEPS (USE YOUR 32k THINKING BUDGET):
    1.  **CLUTTER DETECTION**: Identify every pile of clothes, paper, or random objects. These are rat harbors. Mark them as risks.
    2.  **FLOOR ANALYSIS**: Is the floor clear? If there are objects on the floor, it is NOT clean.
    3.  **SURFACE SCAN**: Look for dust, stains, or water rings.
    4.  **BIOLOGICAL INFERENCE**: Clutter = Rats/Roaches. Water = Mosquitoes. Food = Flies.
    5.  **BE HARSH**: Do not be polite. If it looks messy, call it "DIRTY".

    INSTRUCTION:
    1. Identify every risk.
    2. Name the BACTERIA/VIRUS (e.g. Salmonella, Leptospira).
    3. Name the DISEASE (e.g. Typhoid, Dengue).
    4. CALCULATE THE SCORE based on the STRICT Scoring Rules.
  `;

  try {
      const response = await retryWithBackoff(async () => {
          const ai = getAIClient();
          return await ai.models.generateContent({
            model: modelId,
            contents: {
                parts: [
                    { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, 
                    { text: `${forensicVigilance}\n\n${scoringLogic}\n\n${schemaDescription}` }
                ]
            },
            config: { 
              responseMimeType: "application/json",
              // MAXIMIZED THINKING BUDGET FOR PRO MODEL
              // This ensures the model spends time (up to 2 mins) actually reasoning.
              thinkingConfig: { thinkingBudget: 32000 } 
            }
        });
      });

      let text = response.text || "{}";
      text = text.replace(/```json/g, '').replace(/```/g, '').trim();
      const parsedResult = JSON.parse(text) as AnalysisResponse;

      // ---------------------------------------------------------
      // JAVASCRIPT WATCHDOG (Double-Check Logic)
      // ---------------------------------------------------------
      const detectedWords = (parsedResult.detected_keywords || []).map(w => w.toLowerCase());
      const hasClutterKeywords = detectedWords.some(word => CLUTTER_KEYWORDS.some(bad => word.includes(bad)));

      // Override: If AI marked it 4 or 5 but found clutter keywords, FORCE DOWNGRADE.
      if (hasClutterKeywords && parsedResult.hygieneLevel >= 4) {
          console.log("Watchdog: Clutter found but score high. Forcing downgrade to 3.");
          parsedResult.hygieneLevel = 3;
      }

      // Override: If user selected 'EXTREME' sensitivity, cap max score at 4 unless empty.
      if (sensitivity === 'EXTREME' && parsedResult.hygieneLevel === 5) {
           parsedResult.hygieneLevel = 4; // Impossible perfection
      }

      // Ensure risks array exists
      if (!parsedResult.risks) parsedResult.risks = [];

      // Add ID if missing
      parsedResult.risks.forEach((r, idx) => {
          if (!r.id) r.id = `gen-${Date.now()}-${idx}`;
          if (!r.box_2d) r.box_2d = { ymin: 100, xmin: 100, ymax: 500, xmax: 500 }; // Fallback box
      });

      parsedResult.sensitivityUsed = sensitivity;
      parsedResult.mode = analysisMode; 
      return parsedResult;

  } catch (error: any) {
      console.error("Analysis Error:", error);
      throw new Error("Sistem sedang sibuk atau imej terlalu kompleks. Sila cuba lagi.");
  }
};

