const compressImage = (base64Str: string, maxWidth = 1600, quality = 0.9): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = `data:image/jpeg;base64,${base64Str}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let width = img.width;
            let height = img.height;
            if (width > maxWidth) {
                height = Math.round((height * maxWidth) / width);
                width = maxWidth;
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            resolve(canvas.toDataURL('image/jpeg', quality).split(',')[1]);
        };
        img.onerror = () => resolve(base64Str); 
    });
};

const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 2, delay = 2000): Promise<T> => {
    try {
        return await fn();
    } catch (error: any) {
        const msg = error.message || "";
        const isQuotaError = msg.includes("429") || msg.includes("503") || msg.includes("overloaded");
        if (isQuotaError && retries > 0) {
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(fn, retries - 1, delay * 2);
        }
        throw error;
    }
};

const CLUTTER_KEYWORDS = ['trash', 'rubbish', 'garbage', 'sampah', 'sisa', 'mess', 'clutter', 'pile', 'plastic bag', 'bottle', 'can', 'food', 'sisa makanan', 'kotor', 'dirty', 'stain', 'habuk', 'dust', 'web', 'sarang labah'];

export const analyzeLandscape = async (base64Image: string, mimeType: string, mode: 'FAST' | 'DETAILED' = 'DETAILED', language: string = 'ms', sensitivity: SensitivityLevel = 'STANDARD', analysisMode: AnalysisMode = 'VECTOR_CONTROL'): Promise<AnalysisResponse> => {
  const langMap: Record<string, string> = { 'ms': 'Bahasa Melayu', 'en': 'English', 'zh': 'Chinese', 'ta': 'Tamil' };
  const targetLang = langMap[language] || 'Bahasa Melayu';
  const optimizedImage = await compressImage(base64Image);

  // ALWAYS USE PRO MODEL FOR VISION TASKS TO ENSURE COORDINATES ARE CORRECT
  // We control the "intelligence" via prompts and thinking budget.
  const modelId = "gemini-3-pro-preview";

  let thinkingBudget = 2000; // Default Low
  let promptTone = "";
  let scoringStrictness = "";
  let visualTask = "";

  // --- DYNAMIC LOGIC SCALING ---
  switch (sensitivity) {
    case 'STANDARD':
        thinkingBudget = 2000; // Fast response
        promptTone = "PRACTICAL & BALANCED. Focus on obvious risks only.";
        visualTask = "Scan for VISIBLE vectors (live insects) and MAJOR trash accumulations.";
        scoringStrictness = "Be fair. If it's a normal messy house, score 3 or 4. Only score 1 or 2 for disasters.";
        break;

    case 'HIGH':
        thinkingBudget = 16000; // Medium-Deep thought
        promptTone = "STRICT & PREVENTIVE. Look for potential breeding grounds.";
        visualTask = "Scan for standing water, dark corners (mosquito resting sites), and unsealed food.";
        scoringStrictness = "Be strict. Any potential breeding ground must lower the score below 4.";
        break;

    case 'EXTREME':
        thinkingBudget = 32000; // Max thought
        promptTone = "FORENSIC PATHOLOGIST & PERFECTIONIST AUDITOR. Guilty until proven innocent.";
        visualTask = "DEEP SCAN. Analyze surface porosity, biofilm, microscopic dust patterns, structural gaps, and hidden organic residue. Divide image into 32 grids mentally.";
        scoringStrictness = "BRUTAL. One speck of dust = Fail. Any clutter = Score 2. Visible trash = Score 1.";
        break;
  }

  // JSON SCHEMA
  let schemaDescription = `
    Output MUST be valid JSON. Fields:
    - risks: Array of { 
        box_2d: [ymin, xmin, ymax, xmax] (MANDATORY: Draw precise box around the threat), 
        label: string, 
        agent: string (Vector Name), 
        microbiology: string (Bacteria Name - REQUIRED), 
        disease: string (Clinical Disease - REQUIRED), 
        description: string, 
        solution: string 
      }
    - detected_keywords: string[]
    - hygieneLevel: INTEGER (1-5). REQUIRED.
    - safetyLevel: INTEGER (1-5). REQUIRED.
    - generalAdvice: string (Detailed Summary - REQUIRED).
    - savageCommentary: string (Sarcastic comment - REQUIRED).
  `;

  // SYSTEM INSTRUCTION
  const forensicVigilance = `
    ROLE: ${promptTone}
    MODE: ${sensitivity} SENSITIVITY.
    TASK: ${visualTask}
    LANGUAGE: ${targetLang}.

    CRITICAL INSTRUCTION FOR BOUNDING BOXES:
    - You MUST return 'box_2d' for EVERY risk detected.
    - The box must tightly enclose the object (trash, stain, insect).
    - Do not hallucinate boxes on empty space.

    SCORING RULES:
    ${scoringStrictness}

    EXECUTION STEPS:
    1. Scan the image based on '${sensitivity}' mode depth.
    2. Identify threats.
    3. DRAW BOXES accurately.
    4. Infer biological risks (Bacteria/Virus).
    5. Calculate score.
  `;

  try {
      const response = await retryWithBackoff(async () => {
          const ai = getAIClient();
          return await ai.models.generateContent({
            model: modelId,
            contents: {
                parts: [
                    { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, 
                    { text: `${forensicVigilance}\n\n${schemaDescription}` }
                ]
            },
            config: { 
              responseMimeType: "application/json",
              thinkingConfig: { thinkingBudget: thinkingBudget } 
            }
        });
      });

      let text = response.text || "{}";
      text = text.replace(/```json/g, '').replace(/```/g, '').trim();
      const parsedResult = JSON.parse(text) as AnalysisResponse;

      // ---------------------------------------------------------
      // JAVASCRIPT WATCHDOG (Logic Enforcer)
      // ---------------------------------------------------------
      const detectedWords = (parsedResult.detected_keywords || []).map(w => w.toLowerCase());
      const hasClutterKeywords = detectedWords.some(word => CLUTTER_KEYWORDS.some(bad => word.includes(bad)));

      // Override: If EXTREME mode and clutter found, force score down.
      if (sensitivity === 'EXTREME' && hasClutterKeywords && parsedResult.hygieneLevel > 2) {
          console.log("Watchdog: EXTREME mode + Clutter detected. Downgrading score to 2.");
          parsedResult.hygieneLevel = 2;
      }

      // Ensure risks array exists
      if (!parsedResult.risks) parsedResult.risks = [];

      // Add ID if missing & Ensure box_2d exists
      parsedResult.risks.forEach((r, idx) => {
          if (!r.id) r.id = `gen-${Date.now()}-${idx}`;
          // Fallback box if AI fails (rare with Pro model but possible)
          if (!r.box_2d) r.box_2d = { ymin: 300, xmin: 300, ymax: 600, xmax: 600 }; 
      });

      parsedResult.sensitivityUsed = sensitivity;
      parsedResult.mode = analysisMode; 
      return parsedResult;

  } catch (error: any) {
      console.error("Analysis Error:", error);
      throw new Error("Sistem sedang sibuk. Sila cuba lagi.");
  }
};

export const analyzeManualRegion = async (base64Image: string, mimeType: string, box: BoundingBox, userContext: string, language: string = 'ms'): Promise<RiskDetection> => {
    const optimizedImage = await compressImage(base64Image);
    const ai = getAIClient();
    const prompt = `Region Analysis [${box.ymin}-${box.ymax}, ${box.xmin}-${box.xmax}]. 
    Context: "${userContext}". 
    Identify: 1. Vector Name (agent), 2. Pathogen (microbiology), 3. Disease. 
    Output JSON RiskDetection only.`;

    const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview", 
        contents: { parts: [{ inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, { text: prompt }] },
        config: { responseMimeType: "application/json" }
    });
    const result = JSON.parse(response.text!);
    result.id = `manual-${Date.now()}`;
    result.box_2d = box; 

    if (!result.microbiology) result.microbiology = "Targeted Pathogen Analysis";
    if (!result.disease) result.disease = "Localized Infection Risk";

    return result;
};

