const compressImage = (base64Str: string, maxWidth = 1600, quality = 0.9): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = `data:image/jpeg;base64,${base64Str}`;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let width = img.width;
            let height = img.height;
            if (width > maxWidth) {
                height = Math.round((height * maxWidth) / width);
                width = maxWidth;
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            resolve(canvas.toDataURL('image/jpeg', quality).split(',')[1]);
        };
        img.onerror = () => resolve(base64Str); 
    });
};

const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 2, delay = 2000): Promise<T> => {
    try {
        return await fn();
    } catch (error: any) {
        const msg = error.message || "";
        const isQuotaError = msg.includes("429") || msg.includes("503") || msg.includes("overloaded");
        if (isQuotaError && retries > 0) {
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(fn, retries - 1, delay * 2);
        }
        throw error;
    }
};

const CLUTTER_KEYWORDS = ['trash', 'rubbish', 'garbage', 'sampah', 'sisa', 'mess', 'clutter', 'pile', 'plastic bag', 'bottle', 'can', 'food', 'sisa makanan', 'kotor', 'dirty', 'stain', 'habuk', 'dust', 'web', 'sarang labah'];

export const analyzeLandscape = async (base64Image: string, mimeType: string, mode: 'FAST' | 'DETAILED' = 'DETAILED', language: string = 'ms', sensitivity: SensitivityLevel = 'STANDARD', analysisMode: AnalysisMode = 'VECTOR_CONTROL'): Promise<AnalysisResponse> => {
  const langMap: Record<string, string> = { 'ms': 'Bahasa Melayu', 'en': 'English', 'zh': 'Chinese', 'ta': 'Tamil' };
  const targetLang = langMap[language] || 'Bahasa Melayu';
  const optimizedImage = await compressImage(base64Image);

  const modelId = "gemini-3-pro-preview";

  let thinkingBudget = 2000; 
  let rolePrompt = "";
  let visualTask = "";
  let scoringStrictness = "";

  switch (sensitivity) {
    case 'STANDARD':
        thinkingBudget = 4000;
        rolePrompt = "VECTOR CONTROL OFFICER.";
        visualTask = "Locate VISIBLE Vectors and Trash.";
        scoringStrictness = "Balanced.";
        break;

    case 'HIGH':
        thinkingBudget = 16000;
        rolePrompt = "SENIOR HEALTH INSPECTOR.";
        visualTask = "Locate breeding grounds and potential hazards.";
        scoringStrictness = "Strict.";
        break;

    case 'EXTREME':
        thinkingBudget = 32000;
        rolePrompt = "FORENSIC PATHOLOGIST & OSHA AUDITOR.";
        visualTask = "DEEP SCAN. Find every speck of dust, crack, or hazard. Divide image into grids and scan pixel-by-pixel.";
        scoringStrictness = "ZERO TOLERANCE.";
        break;
  }

  // UPDATED SCHEMA DESCRIPTION TO EMPHASIZE COORDINATES
  let schemaDescription = `
    Output MUST be valid JSON. Fields:
    - risks: Array of { 
        box_2d: [ymin, xmin, ymax, xmax] (MANDATORY: Scale 0-1000. DO NOT OVERLAP BOXES. Each risk must have its own UNIQUE location), 
        category: "VECTOR" | "HYGIENE" | "SAFETY",
        label: string, 
        agent: string, 
        microbiology: string, 
        disease: string, 
        description: string, 
        solution: string 
      }
    - detected_keywords: string[]
    - hygieneLevel: INTEGER (1-5).
    - safetyLevel: INTEGER (1-5).
    - generalAdvice: string.
    - savageCommentary: string.
  `;

  // SYSTEM INSTRUCTION
  const forensicVigilance = `
    ROLE: ${rolePrompt}
    MODE: ${sensitivity} SENSITIVITY.
    TASK: ${visualTask}
    LANGUAGE: ${targetLang}.

    CRITICAL INSTRUCTION FOR BOUNDING BOXES:
    1. **NO STACKING:** Do not put all boxes in the center. Look at the specific pixels where the object is.
    2. **DISTRIBUTION:** If there is trash on the left, the box must be on the left. If a wire is on top, box the top.
    3. **SCALE:** Use 0 to 1000 scale. [0,0,1000,1000] covers the whole image.
    4. **PRECISION:** Box tightly around the specific object (bottle, stain, insect), not the whole room.

    RISK CATEGORIES:
    - VECTOR: Insects, Animals.
    - HYGIENE: Trash, Stains, Mold.
    - SAFETY: Wires, Fire Hazards, Trip Hazards.

    SCORING RULES:
    ${scoringStrictness}
  `;

  try {
      const response = await retryWithBackoff(async () => {
          const ai = getAIClient();
          return await ai.models.generateContent({
            model: modelId,
            contents: {
                parts: [
                    { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, 
                    { text: `${forensicVigilance}\n\n${schemaDescription}` }
                ]
            },
            config: { 
              responseMimeType: "application/json",
              thinkingConfig: { thinkingBudget: thinkingBudget } 
            }
        });
      });

      let text = response.text || "{}";
      text = text.replace(/```json/g, '').replace(/```/g, '').trim();
      const parsedResult = JSON.parse(text) as AnalysisResponse;

      // Watchdog
      const detectedWords = (parsedResult.detected_keywords || []).map(w => w.toLowerCase());
      const hasClutterKeywords = detectedWords.some(word => CLUTTER_KEYWORDS.some(bad => word.includes(bad)));
      if (sensitivity === 'EXTREME' && hasClutterKeywords && parsedResult.hygieneLevel > 2) {
          parsedResult.hygieneLevel = 2;
      }

      if (!parsedResult.risks) parsedResult.risks = [];

      // --- INTELLIGENT COORDINATE FIXER ---
      parsedResult.risks.forEach((r, idx) => {
          if (!r.id) r.id = `gen-${Date.now()}-${idx}`;

          if (r.box_2d) {
             // 1. Detect Normalize Scale (0-1) and convert to 0-1000
             if (r.box_2d.ymax <= 1 && r.box_2d.xmax <= 1) {
                 r.box_2d.ymin *= 1000;
                 r.box_2d.xmin *= 1000;
                 r.box_2d.ymax *= 1000;
                 r.box_2d.xmax *= 1000;
             }

             // 2. Ensure min size (prevent invisible boxes)
             if ((r.box_2d.ymax - r.box_2d.ymin) < 20) r.box_2d.ymax += 50;
             if ((r.box_2d.xmax - r.box_2d.xmin) < 20) r.box_2d.xmax += 50;
          } else {
             // If NO box returned, place it randomly instead of stacking in center
             // This prevents the "bertindih setempat" visual bug
             const randomY = Math.floor(Math.random() * 600) + 100;
             const randomX = Math.floor(Math.random() * 600) + 100;
             r.box_2d = { 
                 ymin: randomY, 
                 xmin: randomX, 
                 ymax: randomY + 150, 
                 xmax: randomX + 150 
             }; 
          }

          if (!r.category) {
              if (r.label.toLowerCase().includes('wire') || r.label.toLowerCase().includes('trip') || r.label.toLowerCase().includes('sharp')) {
                  r.category = 'SAFETY';
              } else {
                  r.category = 'HYGIENE';
              }
          }
      });

      parsedResult.sensitivityUsed = sensitivity;
      parsedResult.mode = analysisMode; 
      return parsedResult;

  } catch (error: any) {
      console.error("Analysis Error:", error);
      throw new Error("Sistem sedang sibuk. Sila cuba lagi.");
  }
};

