        4. agent: string (**STRICTLY ENGLISH/SCIENTIFIC NAME** e.g., "Aedes aegypti", "Musca domestica", "Rattus rattus". DO NOT TRANSLATE THIS.)
        5. microbiology: string (**STRICTLY ENGLISH/SCIENTIFIC NAME** e.g., "Dengue Virus Serotype 2", "Salmonella typhi", "Leptospira". DO NOT TRANSLATE THIS.)
        6. disease: string (**STRICTLY ENGLISH/MEDICAL TERM** e.g., "Dengue Hemorrhagic Fever", "Typhoid", "Leptospirosis". DO NOT TRANSLATE THIS.)
        7. description: string (Forensic Observation in ${targetLang})
        8. solution: string (Engineering/Medical Intervention in ${targetLang})

    - detected_keywords: string[]
    - hygieneLevel: INTEGER (1-5)
    - safetyLevel: INTEGER (1-5)
    - generalAdvice: string (Technical Summary in ${targetLang})
    - savageCommentary: string (Direct, Harsh Critique in ${targetLang})
  `;

  // SYSTEM INSTRUCTION
  const spatialEngineeringPrompt = `
    ${engineerPersona}
    OPERATIONAL MODE: ${sensitivity} SENSITIVITY.
    TARGET LANGUAGE: ${targetLang} (Except for Scientific Terms).

    >>> SPATIAL ANALYSIS PROTOCOL (BOUNDING BOXES) <<<
    1. **VISUAL GROUNDING IS MANDATORY.** You are an optical system, not a text bot. 
    2. **EVERY RISK MUST HAVE A BOX.** If you list a risk, you MUST identify its pixels [ymin, xmin, ymax, xmax] on a 1000x1000 grid.
    3. **NO STACKING.** Objects are in different places. Coordinates must differ.

    >>> RISK CLASSIFICATION LOGIC <<<
    1. **VECTOR (Biological)**: Mosquitoes, Larvae, Rats, Flies. Focus: Water, Organic Waste.
    2. **HYGIENE (Sanitation)**: Mold, Stains, Dust, Food Residue, Overflowing Bins.
    3. **SAFETY (OSHA/Physical)**: Exposed Wiring, Trip Hazards, Chemical Spills, Structural Cracks, Sharp Edges.

    ${scanProtocol}
    ${severityThreshold}
  `;

  try {
      const response = await retryWithBackoff(async () => {
          const ai = getAIClient();
          return await ai.models.generateContent({
            model: modelId,
            contents: {
                parts: [
                    { inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, 
                    { text: `${spatialEngineeringPrompt}\n\n${schemaDescription}` }
                ]
            },
            config: { 
              responseMimeType: "application/json",
              thinkingConfig: { thinkingBudget: thinkingBudget } 
            }
        });
      });

      let text = response.text || "{}";
      text = text.replace(/```json/g, '').replace(/```/g, '').trim();
      const parsedResult = JSON.parse(text) as AnalysisResponse;

      // Watchdog Logic
      const detectedWords = (parsedResult.detected_keywords || []).map(w => w.toLowerCase());
      const hasClutterKeywords = detectedWords.some(word => CLUTTER_KEYWORDS.some(bad => word.includes(bad)));
      if (sensitivity === 'EXTREME' && hasClutterKeywords && parsedResult.hygieneLevel > 2) {
          parsedResult.hygieneLevel = 2;
      }

      if (!parsedResult.risks) parsedResult.risks = [];

      // --- COORDINATE SANITIZER ---
      // This ensures that even if AI slips up, we force a structure that the UI can render.
      parsedResult.risks.forEach((r, idx) => {
          if (!r.id) r.id = `gen-${Date.now()}-${idx}`;

          if (!r.box_2d) {
             // AI failed to generate box -> Assign a grid position based on index to prevent stacking
             // Map index to a 3x3 grid position to separate them visually
             const gridX = (idx % 3) * 330;
             const gridY = (Math.floor(idx / 3)) * 330;
             r.box_2d = { ymin: gridY, xmin: gridX, ymax: gridY + 300, xmax: gridX + 300 };
          } else {
             // Normalize Check: If AI used 0-1 float, convert to 0-1000 int
             if (r.box_2d.ymax <= 1 && r.box_2d.xmax <= 1) {
                 r.box_2d.ymin = Math.floor(r.box_2d.ymin * 1000);
                 r.box_2d.xmin = Math.floor(r.box_2d.xmin * 1000);
                 r.box_2d.ymax = Math.floor(r.box_2d.ymax * 1000);
                 r.box_2d.xmax = Math.floor(r.box_2d.xmax * 1000);
             }

             // Sanity Check: Ensure min dimensions (at least 50x50 pixels in 1000 scale)
             if ((r.box_2d.ymax - r.box_2d.ymin) < 50) r.box_2d.ymax = r.box_2d.ymin + 50;
             if ((r.box_2d.xmax - r.box_2d.xmin) < 50) r.box_2d.xmax = r.box_2d.xmin + 50;
          }

          // Fallback Category Inference
          if (!r.category) {
              const labelLower = r.label.toLowerCase();
              if (['wire', 'trip', 'hazard', 'sharp', 'crack', 'chemical', 'fire', 'electric'].some(k => labelLower.includes(k))) {
                  r.category = 'SAFETY';
              } else if (['mosquito', 'aedes', 'larvae', 'rat', 'fly', 'cockroach', 'pest'].some(k => labelLower.includes(k))) {
                  r.category = 'VECTOR';
              } else {
                  r.category = 'HYGIENE';
              }
          }
      });

      parsedResult.sensitivityUsed = sensitivity;
      parsedResult.mode = analysisMode; 
      return parsedResult;

  } catch (error: any) {
      console.error("Analysis Error:", error);
      throw new Error("Sistem Bio-Analisis sibuk. Sila cuba sebentar lagi.");
  }
};

export const analyzeManualRegion = async (base64Image: string, mimeType: string, box: BoundingBox, userContext: string, language: string = 'ms'): Promise<RiskDetection> => {
    const optimizedImage = await compressImage(base64Image);
    const ai = getAIClient();

    // Manual analysis also gets the upgrade
    const prompt = `ENGINEERING ANALYSIS OF ROI [${box.ymin}-${box.ymax}, ${box.xmin}-${box.xmax}]. 
    CONTEXT: "${userContext}". 
    TASK: IDENTIFY PATHOGEN, VECTOR AGENT, OR SAFETY HAZARD.
    RETURN 'agent', 'microbiology', and 'disease' IN ENGLISH/SCIENTIFIC LATIN.
    OUTPUT FORMAT: JSON (RiskDetection Schema).`;

    const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview", 
        contents: { parts: [{ inlineData: { mimeType: 'image/jpeg', data: optimizedImage } }, { text: prompt }] },
        config: { responseMimeType: "application/json" }
    });
    const result = JSON.parse(response.text!);
    result.id = `manual-${Date.now()}`;
    result.box_2d = box; 

    if (!result.category) result.category = 'HYGIENE';
    if (!result.microbiology) result.microbiology = "Targeted Analysis";
    if (!result.disease) result.disease = "Localized Risk";

    return result;
};

